    [2178] = "Bringt 5 Stücke Schreiterfleisch zu Alanndarian Nightsonng in Auberdine.",
    [2198] = "Sucht nach dem Erschaffer der zerrissenen Halskette, um etwas über ihren möglichen Wert zu erfahren.",
    [2199] = "Bringt fünf Silberbarren zu Talvash del Kissel in Ironforge.",
    [2200] = "Sucht in Uldaman nach Hinweisen auf den momentanen Zustand von Talvashs Halskette. Der getötete Paladin, den Talvash erwähnte, hatte die Kette zuletzt.",
    [2201] = "Findet den Rubin, den Saphir und den Topas, die in ganz Uldaman verstreut sind. Wenn Ihr sie habt, wendet Euch aus der Ferne an Talvash del Kissel, indem Ihr die Wahrsagephiole nutzt, die er Euch zuvor gegeben hat. Aus dem Tagebuch, wisst Ihr... * Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt. * Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz. * Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen.",
    [2202] = "Bringt 12 magenta Funguskappen nach Kargath zu Jarkal Mossmeld.",
    [2203] = "Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Jarkal Mossmeld in Kargath.",
    [2204] = "Besorgt Euch eine Kraftquelle vom mächtigsten Konstrukt, das Ihr in Uldaman finden könnt, und liefert sie bei Talvash del Kissel in Ironforge ab.",
    [2205] = "Liefert Keryn Sylvius' Päckchen an Meister Mathias Shaw in der Kaserne von Stormwind.",
    [2206] = "Sucht den Dockmeister der Defias und beschafft den Lieferzeitplan für Meister Mathias Shaw.",
    [2218] = "Sprecht mit Hulfdan Blackbeard in Ironforge.",
    [2238] = "Sucht Onin MacHammar bei Gnomeregan.",
    [2239] = "Bringt Onins Bericht zu Hulfdan in Ironforge.",
    [2240] = "Lest Baelogs Tagebuch, erforscht die geheime Kammer und erstattet dann Ausgrabungsleiter Stormpike Bericht.",
    [2241] = "Bringt Jannoks Rose zu Syurna in Darnassus.",
    [2242] = "Sucht Sethir den Uralten und bringt alle Hinweise, die Ihr finden könnt, zu Syurna.",
    [2258] = "Bringt Jarkal Mossmeld in Kargath im Ödland 5 Bussard-Mägen, 10 Klippenkojoten-Fangzähne und 5 Felselementarsplitter.",
    [2259] = "Kontaktiert Erion Shadewhisper in Darnassus.",
    [2260] = "Reist zur Stadt Stormwind und meldet Euch bei Renzik \"Das Messer\".",
    [2278] = "Sprecht mit dem Steinbehüter und findet heraus, welche uralten Lehren er aufbewahrt. Sobald Ihr alles erfahren habt, was er weiß, aktiviert die Scheiben von Norgannon.",
    [2279] = "Bringt die Miniaturausgabe der Scheiben von Norgannon zur Forscherliga nach Ironforge.",
    [2280] = "Bringt die Miniaturausgabe der Scheiben von Norgannon zu einem der Weisen von Thunder Bluff.",
    [2281] = "Geht nach Seenhain im Rotkammgebirge und sprecht mit Lucius.",
    [2282] = "Öffnet Lucius' Schließkassette, nehmt die Marke der Diebeskunst heraus und bringt sie zu Lucius nach Seenhain.",
    [2283] = "Sucht in der Grabungsstätte von Uldaman nach einer wertvollen Halskette und bringt sie nach Orgrimmar zu Dran Droffers. Die Halskette ist vielleicht beschädigt.",
    [2284] = "Sucht in den Tiefen von Uldaman nach einem Hinweis auf den Verbleib der Edelsteine.",
    [2298] = "Reist nach Stormwind und sucht Renzik \"Das Messer\" auf.",
    [2299] = "Reist nach Ironforge und sprecht mit Hulfdan Blackbeard.",
    [2300] = "Reist nach Stormwind und sucht Renzik \"Das Messer\" auf.",
    [2318] = "Sucht jemanden, der das Tagebuch des Paladins übersetzen kann. Der nächstgelegene Ort, wo Ihr so jemanden finden könntet, ist Kargath im Ödland.",
    [2338] = "Leiht Jarkal die Halskette. Im Gegenzug wird er das Tagebuch für Euch übersetzen.",
    [2339] = "Beschafft in Uldaman alle drei Edelsteine sowie eine Kraftquelle für die Halskette und bringt sie anschließend zu Jarkal Mossmeld nach Kargath. Jarkal glaubt, dass sich eine Kraftquelle vielleicht im stärksten Konstrukt in Uldaman findet. Aus dem Tagebuch, wisst Ihr... * Der Rubin wurde in einer Bastion der Zwerge der Schattenschmiede versteckt. * Der Topas steckt in einer Urne in einem der Trogg-Gebiete, in der Nähe einiger Zwerge der Allianz. * Der Saphir wurde von Grimlok, dem Anführer der Troggs, mitgenommen.",
    [2340] = "Liefert die Halskette und die geborgenen Edelsteine bei Dran Droffers in Orgrimmar ab.",
    [2341] = "Besucht Jarkal Mossmeld in Kargath, um festzustellen, ob er Erfolg gehabt hat.",
    [2342] = "Holt Patrick Garretts Familienschatz aus der Truhe der Familie in der südlichen Bankenhalle von Uldaman und bringt diesen zu ihm nach Undercity.",
    [2359] = "Stehlt den Turmschlüssel der Defias, brecht in den Turm der Defias ein und stellt fest, was sich in der Dämmerwaldtruhe befindet. Bringt Mathias Shaw in Stormwind dann alle Informationen über das, was Ihr herausgefunden habt. Lest Kearnens Tagebuch, um neue Erkenntnisse über den Turm zu erlangen.",
    [2360] = "Reist nach Westfall und sucht Agentin Kearnen. Sie wird Euch Bericht erstatten.",
    [2378] = "Reist nach Orgrimmar und sprecht an der Kluft der Schatten mit Shenthul.",
    [2379] = "Sprecht an der Kluft der Schatten mit Zando'zan.",
    [2380] = "Sprecht an der Kluft der Schatten in Orgrimmar mit Shenthul.",
    [2381] = "Bringt den Schatz der Südmeerfreibeuter zu Wrenix dem Jämmerlichen in Ratchet. Vergesst nicht, einen R.C.V.K. und Diebeswerkzeug von Wrennixs Elektrodingsda-Apparat zu bringen. Ihr werdet diese Dinge brauchen, um Eure Mission zu beenden. Wenn Ihr von ungewöhnlich feindlichen Papageien angegriffen werdet, benutzt Euren R.C.V.K.!",
    [2382] = "Reist nach Ratchet und sprecht mit Wrenix dem Jämmerlichen.",
    [2383] = "Lest das einfache Pergament und sprecht mit Frang im Tal der Prüfungen.",
    [2398] = "Sucht in Uldaman nach Baelog.",
    [2418] = "Bringt Rigglefuzz im Ödland 8 Kraftsteine aus Dentrium und 8 Kraftsteine aus An'Alleum.",
    [2438] = "Bringt den smaragdgrünen Traumfänger zu Tallonkai Swiftroot in Dolanaar.",
    [2439] = "Bringt Euren Belohnungsgutschein zu Dinita Stonemantle im Gewölbe von Ironforge.",
    [2440] = "Bringt den Belohnungsgutschein zu Bena Winterhoof nach Thunder Bluff.",
    [2458] = "Reist zum Turm der Venture Company nördlich des Schlickermoores und kontaktiert dort den Agenten der Shattered-Hand, Zuchtmeister Fizzule. Sobald der Turm in Sichtweite ist, verwendet die Leuchtfeuerwaffe, um Zuchtmeister Fizzule Eure Ankunft anzuzeigen. Feuert ZWEI Leuchtfeuergeschosse ab, nähert Euch dann Zuchtmeister Fizzule und zeigt den Gruß der Shattered-Hand. Es ist wichtig, dass Ihr diese Aktionen in der richtigen Reihenfolge durchführt, da Fizzule jede Person, die er nicht erkennt, angreift und eliminiert.",
    [2459] = "Tallonkai Swiftroot aus Dolanaar möchte, dass Ihr 7 Mystiker der Knarzklauen tötet und das verlorene Juwel findet.",
    [2460] = "Führt Shenthul gegenüber den Shattered-Gruß aus.",
    [2478] = "Stehlt Silixiz' Turmschlüssel von Großknecht Silixiz. Tötet dann 2 mutierte Drohnen der Venture Co., 2 Patrouillen der Venture Co. und 2 Ausgucker der Venture Co. Eliminiert den obersten Großknecht Gallywix und nehmt seinen Kopf. Knackt dann das Schloss von Gallywix' Schließkassette und stehlt den Vorrat an Zanzils veränderter Mixtur. Bringt den Vorrat und Gallywix' Kopf zu Shentul nach Orgrimmar; er wird Euch weitere Anweisungen geben.",
    [2479] = "Reist nach Tarrens Mühle im Vorgebirge von Hillsbrad und liefert die Probe von Zanzils Mixtur bei Serge Hinott ab. Um nach Tarrens Mühle zu kommen, müsst Ihr den Zeppelin nach Undercity nehmen und dann auf der Straße nach Süden durch den Silberwald in Richtung Hillsbrad reisen. Folgt den Schildern!",
    [2480] = "Wartet auf Serge Hinott, um das Heilmittel fertig zu stellen.",
    [2498] = "Rellian Greenspyre möchte, dass Ihr am Al'Amethsee mit Denalan sprecht.",
    [2499] = "Denalan vom Al'Amethsee möchte, dass Ihr den riesengroßen Tumor von Grimmeiche einsammelt.",
    [2500] = "Beschafft die Reagenzien, die Ghak Healtouch aus dem Ödland braucht, und bringt sie ihm nach Thelsamar.",
    [2501] = "Benutzt die leeren thaumaturgischen Gefäße bei versengten Wächtergroßdrachen im Ödland. Wenn Ihr sie gefüllt habt, bringt sie zu Ghak Healtouch in Thelsamar.",
    [2518] = "Priesterin A'moora vom Tempel des Mondes in Darnassus möchte, dass Ihr ihr Lady Sathrahs silbrige Spinndrüsen bringt.",
    [2519] = "Schwester Aquinne möchte, dass Ihr im Tempel des Mondes mit Priesterin A'moora sprecht.",
    [2520] = "Priesterin A'moora möchte, dass Ihr Lady Sathrahs silbrige Spinndrüsen am Brunnen innerhalb des Tempels ablegt und dann zu ihr zurückkehrt.",
    [2521] = "Falls Ihr auf Euren Reisen durch die verwüsteten Lande je auf eine fehlerlose Draenethystsphäre stoßen solltet, bringt sie zu Kum'isha dem Sammler. Doch seid gewarnt. Der Edelstein ist einer der rarsten Kristalle von ganz Azeroth. Jedes Wesen in diesem Land könnte eine fehlerlose Draenethystsphäre bei sich haben. Ihr erhaltet eine Belohnung für jede fehlerlose Draenethystsphäre, die Ihr beschaffen könnt.",
    [2522] = "Findet eine fehlerlose Draenethystsphäre und bringt sie Kum'isha dem Sammler.",
    [2541] = "Bringt einen Voodooglücksbringer des Schamanen zu Oben Zornklaue in den Grabhügel von Ban'ethil.",
    [2561] = "Oben Zornklaue möchte, dass Ihr seinen seelenlosen Körper tötet und dann den Voodooglücksbringer anwendet.",
    [2581] = "Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange.",
    [2582] = "Bringt Blutmagier Drazial 3 Kicherfangunterkiefer, 2 feuerverbrannte Eberlungen und 1 Skorpokzange.",
    [2583] = "Bringt Blutmagier Drazial 3 feuerverbrannte Eberlungen, 2 Skorpokzangen und 1 Basiliskengehirn.",
    [2584] = "Bringt Blutmagier Drazial 3 feuerverbrannte Eberlungen, 2 Skorpokzangen und 1 Basiliskengehirn.",
    [2585] = "Bringt Blutmagier Drazial 3 Skorpokzangen, 2 Geiermuskelmägen und 1 feuerverbrannte Eberlunge.",
    [2586] = "Bringt Blutmagier Drazial 3 Skorpokzangen, 2 Geiermuskelmägen und 1 feuerverbrannte Eberlunge.",
    [2601] = "Bringt Blutmagierin Lynnore 10 Basiliskengehirne und 2 Geiermuskelmägen.",
    [2602] = "Bringt Blutmagierin Lynnore 10 Basiliskengehirne und 2 Geiermuskelmägen.",
    [2603] = "Bringt Blutmagierin Lynnore 10 Geiermuskelmägen und 2 Kicherfangunterkiefer.",
    [2604] = "Bringt Blutmagierin Lynnore 10 Geiermuskelmägen und 2 Kicherfangunterkiefer.",
    [2605] = "Beschafft Euch eine volle Taudrüse und bringt sie nach Gadgetzan zu Marin Noggenfogger.",
    [2606] = "Marin Noggenfogger möchte, dass Ihr in Gadgetzan mit Sprinkle sprecht.",
    [2607] = "Sprecht im Keller der Kaserne mit Doc Mixilpixil.",
