    [3128] = "Bringt 2 abgesplitterte Baumstämme, 6 verkrustete Mineralien, 20 Stücke widerstandsfähige Sehne und 40 metallische Fragmente zu Hexendoktor Uzer'i ins Camp Mojache.",
    [3129] = "Hexendoktor Uzer'i will, dass Ihr einen Moment wartet, während er die Waffen vorbereitet.",
    [3130] = "Meldet Euch bei Latronicus Moonspear in der Festung Feathermoon.",
    [3141] = "Lasst Loramus Thalipedes seine Geschichte erzählen.",
    [3161] = "Marvon Rivetseeker in Tanaris möchte, dass Ihr 30 Gahz'ridian-Ornamente sammelt.",
    [3181] = "Bringt Margols gigantisches Horn zu Gebirgsjägerin Pebblebitty.",
    [3182] = "Bringt Margols gigantisches Horn zu Kurator Thorius in Ironforge.",
    [3201] = "Bringt die Urkunde für die Tat zurück zu Gebirgsjägerin Pebblebitty.",
    [3221] = "Sprecht mit Apotheker Renferrel in dem Grabmal.",
    [3261] = "Sprecht im Camp Taurajo mit Jorn Skyseer.",
    [3281] = "Bringt das gestohlene Silber zu Gazrog in Crossroads.",
    [3301] = "Sprecht mit Mura Runetotem in dem Grabmal.",
    [3321] = "Wartet, bis Trenton seine Arbeit erledigt hat.",
    [3341] = "Andrew Brownell will, dass Ihr Amnennar den Kältebringer tötet und ihm dessen Schädel bringt.",
    [3361] = "Bringt Felix Whindlebolt in Anvilmar den Kasten, die Truhe und den Bolzeneimer von Felix.",
    [3362] = "Tran'rek in Gadgetzan möchte, dass Ihr 8 knorrige Distelwandler und 8 Distelwurzelformer erledigt.",
    [3363] = "Blah.",
    [3364] = "Bringt ein kochend heißes Morgengebräu zu Durnan Furcutter ins Anvilmar hinein, bevor es innerhalb von fünf Minuten kalt wird!",
    [3365] = "Bringt Nori Pridedrift den Becher zurück.",
    [3367] = "Helft Dorius, zurück nach Ironforge zu kommen.",
    [3368] = "Bringt den angesengten Brief zu Thorius in Ironforge. Er befindet sich in der Halle der Forscher.",
    [3369] = "Bringt den Alptraum-Splitter zu Hamuul Runtetotem auf der Anhöhe der Ältesten.",
    [3370] = "Bringt den Alptraum-Splitter zu Mathrengyl Bearwalker in Darnassus.",
    [3371] = "Kehrt zur sengenden Schlucht zurück und sucht Dorius' Archäologenteam.",
    [3372] = "Sucht das mysteriöse Artefakt, das im Norden von den Twilight-Hammer bewacht wird.",
    [3373] = "Legt die Essenz von Eranikus in den Essenzborn, der sich in dem Versunkenen Tempel in seinem Unterschlupf befindet.",
    [3374] = "Bringt den Schwurstein von Yseras Drachenschwarm sowie die gekettete Essenz von Eranikus zu Itharius in die Sümpfe des Elends. Dort werdet Ihr Eure Entscheidung treffen, ob Ihr Yseras Drachenschwarm helfen wollt oder nicht.",
    [3375] = "Bringt einen Manatrank, Kohle und Süßen Nektar zu Talvash del Kissel in Ironforge, um einen Ersatz für Talvashs Wahrsagephiole zu bekommen.",
    [3376] = "Bringt den Kopf von Häuptling Spitzhauer Dornenmantel zu Kriegerheld Windfeather nach Red Cloud Mesa.",
    [3377] = "Hört Zamaels Geschichte.",
    [3378] = "Findet das Gebet an Elune und bringt es zu Astarii Starseeker in Darnassus.",
    [3379] = "Tötet die Gruppe der Schattenseidewilderer, die in der sengenden Schlucht umherstreifen. Nilith hat Grund zu der Annahme, dass es fünf von ihnen gibt, die ausgeschaltet werden müssen.",
    [3380] = "Sucht Marvon Rivetseeker in Tanaris.",
    [3382] = "Verteidigt Kapitän Vanessa Beltis, ihre Mannschaft und die Passagiere der HERRIN DES HORIZONTS gegen den Angriff der Naga. Captain Vanessa Beltis muss überleben.",
    [3385] = "Erschlagt Handelsmeister Kovic und seinen Diener Clunk. Nehmt den Händlerranzen von seinem Leichnam und bringt ihn zu Nilith.",
    [3402] = "Sprecht mit Vizzklick in Gadgetzan.",
    [3441] = "Lasst Velarok Windblade seine Geschichte erzählen.",
    [3442] = "Sammelt 4 Herzen der Flamme und 4 Kugeln Golemöl und bringt die Gegenstände zu Velarok Windblade.",
    [3443] = "Bringt 8 mit Thorium beschichtete Dolche zu Velarok Windblade.",
    [3444] = "Holt den runden Stein aus Marvon Rivetseekers Werkstatt in Ratchet.",
    [3445] = "Sucht Marvon Rivetseeker in Tanaris.",
    [3446] = "Sucht den Altar von Hakkar im Versunkenen Tempel in den Sümpfen des Elends.",
    [3447] = "Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt.",
    [3448] = "Sprecht mit Magier Tymor in Ironforge.",
    [3449] = "Verwendet das Zeichenset, um Abpausbilder von der Rune von Beth'Amara, der Rune von Jin'yael, der Rune von Markri und der Rune von Sael'hai herzustellen, bevor Ihr Euch zu der kleinen Insel vor der südlichen Halbinsel von Azshara aufmacht und dem Piloten Xiggs Fuselighter signalisiert, dass er sie abholen kann.",
    [3450] = "Sprecht mit Xiggs Fuselighter in Ironforge.",
    [3451] = "Sprecht mit Xiggs Fuselighter in Ironforge und erhaltet von ihm eine Standardausrüstung-Leuchtfeuerwaffe.",
    [3452] = "Bringt ein Symbol von Ragnaros zu Velarok Windblade.",
    [3453] = "Wartet bis Velarok Windblade die Fackel der Vergeltung vollendet hat.",
    [3454] = "Nehmt die Fackel der Vergeltung.",
    [3461] = "Bringt Magier Tymors Zeichenset zu ihm zurück nach Ironforge.",
    [3462] = "Sprecht mit dem Knappen Maltrake.",
    [3463] = "Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt.",
    [3481] = "Öffnet die Truhe.",
    [3501] = "Bringt Kum'isha unvollständige Draenethystfragmente und Ihr werdet für jedes, das Ihr bringt, belohnt.",
    [3502] = "Bringt Kum'isha unvollständige Draenethystfragmente. Jede Art von Monster in den verwüsteten Landen könnte ein Fragment bei sich tragen.",
    [3504] = "Bringt den versiegelten Brief zu Ag'tor Bloodfist nach Azshara.",
    [3505] = "Tötet 6 Blutelfenwiederbeschaffer und 6 Blutelfenfeldmesser, bevor Ihr Euch aufmacht, Rimtoris Quelle der Macht zu finden.",
    [3506] = "Zerstört den arkanen Fokussierkristall, der an Magus Rimtori gebunden ist, und tötet sie danach. Bringt dann den Kopf von Magus Rimtori zu Ag'tor Bloodfist nach Azshara.",
    [3507] = "Sprecht mit Belgrom Rockmaul in Orgrimmar.",
    [3508] = "Wartet, bis Loramus den Erleuchtungszauber vollendet hat.",
    [3509] = "Sprecht mit Lord Arkkoroc in Azshara. Beginnt Eure Suche am Rand des Wassers, um den Tempel von Arkkoran zu finden.",
    [3510] = "Erschlagt Hetäre und bringt den blutigen Hetärenkopf, den geschlagenen Hetärenkopf und den verwundeten Hetärenkopf zu Lord Arkkoroc.",
    [3511] = "Bringt den Härter zurück zu Loramus Thalipedes.",
    [3512] = "Reist in den östlichen Teil von Winterspring und sprecht mit Umbranse, dem Geistsprecher.",
    [3513] = "Bringt die runenverzierte Rolle zum nördlichen Wachturm des Brachlandes.",
    [3514] = "Tötet die Anführerin des Krallenbaus, Rynthariel die Schlüsselmeisterin.",
    [3517] = "Sucht die Schrifttafel von Beth'Amara, die Schrifttafel von Jin'yael, die Schrifttafel von Markri und die Schrifttafel von Sael'hai für Jediga in Valormok.",
    [3518] = "Bringt die Schrifttafel von Beth'Amara zu Magatha Grimmtotem in Thunder Bluff.",
    [3519] = "Sprecht mit Dirania Silvershine in Shadowglen.",
    [3520] = "Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya in Steamwheedle zurück.",
    [3521] = "Sammelt 7 Hyazinth-Pilze, 4 Mondblütenlilien und 1 Waldwebersekret für Dirania Silvershine in Shadowglen.",
    [3522] = "Bringt Iverrons Gegengift zu Iverron, bevor die Zeit um ist. Ihr findet Iverron bei der Höhle im Norden.",
    [3523] = "Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab.",
    [3524] = "Sammelt Meereskreaturknochen von der gestrandeten Meereskreatur unmittelbar südlich von Auberdine und kehrt dann mit ihnen zu Gwennyth Bly'Leggonde nach Auberdine zurück.",
    [3525] = "Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln von Razorfen. Beschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten.",
    [3526] = "Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan.",
    [3527] = "Bringt die erste und die zweite Mosh'aru-Schrifttafel zu Yeh'kinya nach Tanaris.",
    [3528] = "Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris.",
    [3541] = "Bringt die Schrifttafel von Jin'yael zu Jes'rimon nach Orgrimmar.",
    [3542] = "Bringt die Schrifttafel von Markri zu Andron Gant nach Undercity.",
    [3561] = "Bringt die Schrifttafel von Sael'hai zu Erzmagier Xylem in Azshara.",
    [3562] = "Bringt Magathas Notiz zu Jediga in Azshara.",
    [3563] = "Bringt Jes'rimons Notiz zu Jediga in Azshara.",
    [3564] = "Bringt Androns Notiz zu Jediga in Azshara.",
    [3565] = "Bringt Xylems Notiz zu Jediga in Azshara.",
    [3566] = "Tötet Lathoric den Schwarzen und Obsidion. Kehrt zurück zu Thorius nach Ironforge mit dem Kopf von Lathoric dem Schwarzen und dem Herzen von Obsidion.",
    [3568] = "Füllt alle 4 leeren Phiolen an den Gezeitenteichen entlang der Küste der Ruinen von Eldarath in Azshara und kehrt dann zu Chemiker Cuely zurück.",
    [3569] = "Gebt Cuelys Elixier Thersa Windsong in Undercity.",
    [3601] = "Durchsucht den Thalassian-Stützpunkt nach Kim'jaels Kompass, Zielfernrohr, ausgestopftem Huhn und Wizzlegoober und bringt ihm dann alles nach Azshara zurück.",
    [3602] = "Sammelt 20 kristallisierte Azsharite im südlichen Azshara. Ihr könnt den Teufelshund benutzen, damit er Euch beim 'Erschnüffeln' der gut versteckten Ablagerungen behilflich ist. Kehrt zu Loramus zurück, sobald Ihr die Aufgabe erfüllt habt.",
    [3621] = "Bringt die Lieferung zu Galvan dem Alten im Schlingendorntal.",
    [3625] = "Wartet, bis Galvan die Waffen fertig geschmiedet hat.",
    [3626] = "Kehrt zum Gefallenen Helden der Horde zurück.",
    [3627] = "Tötet Grol den Zerstörer, Lady Sevine und Erzmagier Allistarj. Nehmt das Amulett von Grol, das Amulett von Sevine und das Amulett von Allistarj von ihren Leichen. Denkt daran, Eure Verzauberte Azsharit-Teufelswaffe zu BENUTZEN, um die Triade zu schwächen. Auf eine andere Weise können sie nicht getötet werden - aber verwendet sie weise ...",
    [3628] = "Vernichtet Razelikh den Entweiher und bringt das abgespaltene Horn des Entweihers zum Gefallenen Helden der Horde. Ihr müsst außerdem den Zauberschutz des Entweihers mit zurückbringen, damit der Gefallene Held ihn zerstören und somit verhindern kann, dass er jemals in die falschen Hände fällt.",
    [3629] = "Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan.",
    [3630] = "Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge.",
    [3631] = "Sprecht mit Strahad Farsan im Brachland.",
    [3632] = "Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge.",
    [3633] = "Wenn Ihr etwas über die Goblin-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan.",
    [3634] = "Wenn Ihr etwas über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Tüftlermeister Overspark nach Ironforge.",
    [3635] = "Wenn Ihr mehr über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Oglethorpe Obnoticus nach Booty Bay.",
    [3636] = "Erzbischof Benedictus will, dass Ihr Amnennar den Kältebringer in den Hügeln von Razorfen tötet.",
    [3637] = "Wenn Ihr mehr über die Gnomen-Ingenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunst-Disziplinen zu Oglethorpe Obnoticus nach Booty Bay.",
    [3638] = "Wenn Ihr ein Goblin-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Nixx Sprocketspring in Gadgetzan sprechen.",
    [3639] = "Bringt 20 große Eisenbomben, 20 robuste Dynamitstangen und 5 explosive Schafe zu Nixx Sprocketspring nach Gadgetzan.",
    [3640] = "Wenn Ihr ein Gnomen-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Tüftlermeister Overspark in Ironforge sprechen.",
    [3641] = "Bringt 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Tüftlermeister Overspark in Ironforge.",
    [3642] = "Wenn Ihr ein Gnomen-Ingenieur werden wollt, dann müsst Ihr auf den Schwur der Geheimhaltung rechtsklicken und erneut mit Oglethorpe in Booty Bay sprechen.",
    [3643] = "Bringt 6 Mithrilröhren, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Oglethorpe Obnoticus in Booty Bay.",
    [3661] = "Sammelt 15 Wildekinfedern aus dem Hinterland für Erelas Ambersky in Rut'theran.",
    [3681] = "Sprecht mit Duthorian Rall in Stormwind.",
    [3701] = "Begebt Euch zu den Ruinen von Thaurissan in der brennenden Steppe und sammelt Informationen über die Thaurissan-Relikte. Kehrt zur königlichen Historikerin Archesonus zurück, wenn Ihr die Informationen besorgt habt.",
    [3702] = "Hört die Erzählung der königlichen Historikerin Archesonus über die Geschichte von Thaurissan.",
    [3741] = "Sucht Hilarys Halskette und bringt sie Hilary in Seenhain zurück.",
    [3761] = "Bringt 20 Un'Goro-Erdproben zu Ghede in Thunder Bluff.",
    [3762] = "Sprecht in Thunder Bluff mit Erzdruide Hamuul Runetotem.",
    [3763] = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.",
    [3764] = "Bringt 20 Un'Goro-Erdproben zu Jenal in Darnassus.",
    [3765] = "Reist zu Gershala Nightwhisper in Auberdine.",
    [3781] = "Bringt den Samenkorngutschein des Erzdruiden zu Mathrengyl Bearwalker in der Enklave des Cenarius von Darnassus.",
    [3782] = "Bringt den Samenkorngutschein zu Bashana Runetotem in Thunder Bluff.",
    [3783] = "Sammelt 10 dicke Yetifelle für Umi Rumplesnicker in Everlook.",
    [3784] = "Sprecht in Thunder Bluff mit Erzdruide Hamuul Runetotem.",
    [3785] = "Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Un'Goro-Erdproben, um Morgenkorn zu kultivieren. Bringt 10 Einheiten Morgenkorn zu Mathrengyl Bearwalker in Darnassus.",
    [3786] = "Benutzt einen Immergrünbeutel mit einem Paket Tharlendrissamenkörner sowie zwei Un'Goro-Erdproben, um Morgenkorn zu kultivieren. Bringt 10 Einheiten Morgenkorn zu Bashana Runetotem in Thunder Bluff.",
    [3787] = "Sprecht mit Quintis Jonespyre in der Festung Feathermoon.",
    [3788] = "Sprecht mit Quintis Jonespyre in der Festung Feathermoon.",
    [3789] = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.",
    [3790] = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.",
    [3791] = "Bringt 10 Einheiten Morgenkorn zu Quintis Jonespyre in der Festung Feathermoon.",
    [3801] = "Sprecht mit Franclorn Forgewright, wenn Ihr daran interessiert seid, einen Schlüssel für die Hauptstadt zu erhalten.",
    [3802] = "Erschlagt Fineous Darkvire und bergt den großen Hammer Ironfel. Bringt Ironfel zum Schrein von Thaurissan und legt ihn auf die Statue von Franclorn Forgewright.",
    [3821] = "Begebt Euch in die brennende Steppe und findet heraus, was aus Sha'ni Proudtusk geworden ist.",
    [3822] = "Holt Sha'nis Nasenring von Krom'Grul zurück und bringt ihn zu Thal'trak in Kargath. Durchsucht die verschiedenen Höhlen und Minen im Schreckensfels.",
    [3823] = "Tötet 15 Ogermagier der Feuermägen, 7 Oger der Feuermägen sowie 7 Schläger der Feuermägen und kehrt zu Oralius zurück, wenn Ihr fertig seid.",
    [3824] = "Sucht Gor'tesh irgendwo im Westen des Schreckensfelsens. Tötet Gor'tesh und bringt dann seinen abgehackten Kopf zu Oralius in der brennenden Steppe zurück.",
    [3825] = "Nehmt Gor'teshs abgehackten Kopf und platziert ihn auf dem Gipfel des Schreckensfelsens. Sucht nach einem weichen Erdhügel, um den Pfahl aufzustellen.",
    [3841] = "Sprecht mit Quentin in Tausend Nadeln.",
    [3842] = "Bringt 2 Elixiere der geringen Seelenstärke zu Quentin in Tausend Nadeln.",
    [3843] = "Bringt Euer empfindliches Grimmlingflitzerei ins Hinterland und sprecht mit Agnar Beastamer, aber beeilt Euch. Ihr habt nur eine Stunde Zeit, ihn zu finden. Dann stirbt das Jungtier in dem Ei.",
    [3844] = "Sucht in dem Tümpel nach einem Hinweis darauf, wem dieses havarierte Floß gehören könnte.",
    [3845] = "Untersucht die Gegenstände in dem Bündel und bringt sie zu ihrem Besitzer.",
    [3861] = "Beschafft Euch etwas Spezial-Hühnerfutter und kehrt zu dem Huhn zurück, das sich mit Euch angefreundet hat. Wenn Ihr es gefunden habt, dann benutzt erst /cheer, ehe Ihr dem Huhn das Spezial-Hühnerfutter gebt.",
    [3881] = "Bringt eine Kiste mit Nahrungsmitteln und Forscherausrüstung zu Williden Marshal im Un'Goro Krater.",
    [3882] = "Bringt 8 Dinosaurierknochen zu Spark Nilminer im Un'Goro Krater.",
    [3883] = "Verwendet die Kratzphiole, um damit eine Schwarmbauwandprobe von einer der Schwarmbrutstätten der Gorishi im Un'Goro Krater zu holen. Sucht nach den Kammern mit der hängenden Larvenbrut. Bringt die Schwarmbauwandprobe zu Hol'anyee Marshal im Un'Goro Krater.",
    [3884] = "Bringt das Tagebuch zu Williden Marshal zurück. Er befindet sich irgendwo im Un'Goro Krater.",
    [3901] = "Tötet 12 klappernde Skelette und kehrt zu Schattenpriester Sarvis in Deathknell zurück, wenn Ihr fertig seid.",
    [3902] = "Durchsucht Deathknell und Umgebung nach 6 Stücken aufgestöberter Ware und bringt sie zu Todeswache Saltain zurück.",
    [3903] = "Sprecht mit Milly Osworth.",
    [3904] = "Bringt 8 Kisten mit Millys Ernte zu Milly Osworth in der Nähe der Abtei von Nordhain.",
    [3905] = "Bringt die Traubenliste zu Bruder Neals in der Abtei von Nordhain.",
    [3906] = "Reist zum Steinbruch am Blackrock und tötet Übermeister Pyron. Kehrt zu Thunderheart zurück, sobald Ihr den Auftrag erledigt habt.",
    [3907] = "Betretet die Blackrocktiefen und spürt Lord Incendius auf. Tötet ihn und bringt jegliche Informationsquelle, die Ihr finden könnt, zu Thunderheart.",
    [3908] = "Bringt Linkens Schwert zu Donova Snowden in Winterspring.",
    [3909] = "Sucht nach Gregan Brewspewer im nördlichen Feralas. Lasst Euch von ihm erklären, wie Ihr Euch das Videre-Elixier beschaffen könnt, und kehrt dann zu Donova Snowden nach Winterspring zurück.",
    [3912] = "Geht zum Friedhof außerhalb von Gadgetzan und benutzt dort das Videre-Elixier. Befolgt Donovas übrige Anweisungen, um Gaeriyan zu finden.",
    [3913] = "Wenn Ihr auferstanden seid, sucht nach dem Grabstein, von dem Gaeriyan Euch erzählt hat.",
    [3914] = "Liefert Linkens überragendes Schwert bei Linken im Un'Goro Krater ab.",
    [3921] = "Bringt das zerbrochene Samophlang zu Wenikee Boltbucket.",
    [3922] = "Bringt 15 Nugget-Patronen zu Wenikee Boltbucket im Brachland.",
    [3923] = "Bringt das zerbrochene Samophlang nach Orgrimmar zu Rilli Greasygob.",
    [3924] = "Bringt das Samophlang-Handbuch nach Orgrimmar zu Rilli Greasygob.",
    [3941] = "Sucht J.D. Collie in der Höhle in Marshals Zuflucht auf.",
    [3942] = "Sucht Eridan Bluewind im südlichen Teil des Teufelswalds.",
    [3961] = "Bringt das Silbertotem von Aquementas zu Linken in Marshals Zuflucht.",
    [3962] = "Begebt Euch zum Feuerfedergrat südlich von Marshals Zuflucht. Sucht Sturmflamme und verwendet das Totem, um die schützende Aura, die ihn umgibt, zu entfernen. Sobald er besiegt ist, holt die Goldene Flamme aus der Höhle.",
    [3981] = "Sucht Kommandant Gor'shak in den Blackrocktiefen. Ihr erinnert Euch, dass auf dem primitiv gezeichneten Bild des Orcs auch Gitter vor dem Gesicht zu sehen waren. Vielleicht solltet Ihr nach einer Art Gefängnis suchen.",
    [3982] = "Verteidigt Gor'shak.",
    [4001] = "Sprecht mit Kharan Mighthammer und sammelt Informationen über die Entführung von Prinzessin Moira Bronzebeard. Bringt diese Informationen dann zu Thrall nach Orgrimmar. Ihr erinnert Euch, dass Gor'shak gesagt hat, Kharan werde in einer Zelle in seiner Nähe festgehalten.",
    [4002] = "Sprecht mit Thrall, wenn Ihr bereit seid, die von ihm geplante Mission zu übernehmen.",
    [4003] = "Tötet Imperator Dagran Thaurissan und befreit Prinzessin Moira Bronzebeard von seinem bösen Zauber.",
    [4004] = "Kehrt zu Thrall zurück!",
    [4005] = "Bringt das Buch von Aquor, die silbrigen Klauen und das Eisenstammherz nach Tanaris. Benutzt das Buch von Aquor, um Aquementas zu beschwören. Wenn Ihr das vollständige Totem habt, bringt es zu J.D. Collie in Marshals Zuflucht zurück.",
    [4021] = "Bringt ein Teil von Krom'zars Flagge zu Regthar Deathgate, westlich von Crossroads.",
    [4022] = "Zeigt Cyrus Therepentous die abgestreifte Haut des schwarzen Drachenschwarms, die Ihr von Velarok Windblade erhalten habt.",
    [4023] = "Zeigt Cyrus Therepentous einen Beweis für Eure Nützlichkeit. Ihr habt so ein Gefühl, dass Cyrus bereits weiß, dass Ihr unwürdig seid.",
    [4024] = "Begebt Euch in die Blackrocktiefen und tötet Bael'Gar. Ihr wisst lediglich, dass der Riese irgendwo in den Blackrocktiefen haust. Vergesst nicht, die veränderte Haut des schwarzen Drachenschwarms mit Bael'Gars Überresten zu benutzen und damit die feurige Essenz einzufangen. Bringt die eingeschlossene feurige Essenz zu Cyrus Therepentous zurück.",
    [4061] = "Begebt Euch in die brennende Steppe und beschafft für Theodora Mulvadania 10 gerissene Elementarsplitter. Euch fällt ein, dass Theodora gesagt hat, die Golems und Elementare in der Gegend seien eine gute Quelle für solche Splitter.",
    [4062] = "Bringt die Elementarsplitterprobe zu Lotwil Veriatus. Ihr erinnert Euch, dass Theodora sagte, Lotwil sei in einem Lager im Osten stationiert.",
    [4063] = "Sucht und tötet Golemlord Argelmach. Bringt Lotwil seinen Kopf. Außerdem müsst Ihr 10 intakte Elementarkerne von den Wuthäschergolems und Kriegshetzerkonstrukten, die Argelmach beschützen, beschaffen. Das wisst Ihr, weil Ihr übernatürliche Fähigkeiten habt.",
    [4081] = "Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren! Kriegsherr Goretooth möchte, dass Ihr 15 Gardisten der Zorneshämmer, 10 Aufseher der Zorneshämmer und 5 Fußsoldaten der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.",
    [4082] = "Begebt Euch in die Blackrocktiefen und vernichtet die üblen Aggressoren! Kriegsherr Goretooth möchte, dass Ihr 10 Sanitäter der Zorneshämmer, 10 Soldaten der Zorneshämmer und 10 Offiziere der Zorneshämmer tötet. Kehrt zu ihm zurück, sobald Ihr die Aufgabe erfüllt habt.",
    [4084] = "Beschafft 11 silbrige Klauen und 1 Eisenstammherz für Eridan Bluewind im Teufelswald.",
    [4101] = "Bringt 15 Einheiten Blutharz zu Arathandris Silversky im Teufelswald.",
    [4102] = "Bringt 15 Einheiten Blutharz zu Maybess Riverbreeze im Teufelswald.",
    [4120] = "Talo Thornhoff im Camp Mojache in Feralas möchte, dass Ihr 12 Wutklauengrizzlys und 12 Teufelspfotenverheerer im Teufelswald erledigt.",
    [4121] = "Eskortiert Euren Gefangenen, Grark Lorkrub, durch die brennende Steppe und durch den Blackrock in die sengende Schlucht. Euch fällt ein, dass Lexlort gesagt hat, seine Männer würden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen. Ihr werdet außerdem Eure Thoriumfesseln an Lexlort übergeben müssen.",
    [4122] = "Begebt Euch in die brennende Steppe und sucht Grark Lorkrub. Ihr erinnert Euch, dass Lexlort gesagt hat, er sei zuletzt in einer großen Festung der Blackrock gesehen worden. Wenn Ihr Grark Lorkrub gefunden habt, verwendet die Thoriumfesseln, um ihn zu binden, und bringt ihn dann über den Blackrock in die sengende Schlucht zurück. Lexlorts Männer werden auf der anderen Seite warten, um Grark in Gewahrsam zu nehmen.",
    [4123] = "Bringt das 'Herz des Berges' zu Maxwort Uberglint in der brennenden Steppe.",
    [4124] = "Sprecht mit Ginro Hearthkindle in der Festung Feathermoon.",
    [4125] = "Sucht das Boot des Kuriers irgendwo entlang der Küste von Feralas.",
    [4126] = "Bringt Ragnar Donnerbräu in Kharanos das gestohlene Donnerbräurezept.",
    [4127] = "Kehrt zur Festung Feathermoon zurück und zeigt Ginro Hearthkindle das gefundene Messer.",
    [4128] = "Sprecht mit Ragnar Donnerbräu.",
    [4129] = "Bringt Quintis Jonespyre in der Festung Feathermoon das gefundene Messer.",
    [4130] = "Sprecht mit Ginro Hearthkindle in der Festung Feathermoon.",
    [4131] = "Durchsucht die Lager der Waldpfotengnolle im Süden Feralas nach Hinweisen auf den Verbleib des Kuriers oder seiner Habseligkeiten.",
    [4132] = "Begebt Euch zu den Blackrocktiefen und eliminiert General Zornesschmied! Kehrt zum Kriegsherrn Goretooth zurück, sobald Ihr diese Aufgabe erledigt habt.",
    [4133] = "Sprecht mit Schattenmeisterin Vivian Lagrave in Kargath.",
    [4134] = "Bringt Vivian Lagrave in Kargath das gestohlene Donnerbräurezept.",
    [4135] = "Da Ihr jetzt Raschals letzten bekannten Aufenthaltsort in Erfahrung gebracht habt, setzt Ihr die Suche nach ihm oder seinen sterblichen Überresten in der verwundenen Tiefe fort. Laut Notiz soll dieser Ort südlich der Lager der Waldpfotengnolle liegen.",
    [4136] = "Bringt Yuka Screwspigot in der brennenden Steppe Ribblys Kopf.",
    [4141] = "Sammelt 15 Blutblüten und kehrt zu Muigin zurück.",
    [4142] = "Bringt Gregan Brewspewer in Feralas eine Blutblüte.",
    [4143] = "Sammelt 5 Proben Dunst der Atal'ai und bringt sie Muigin im Un'Goro Krater.",
    [4145] = "Jagt 5 Blutblütenpeitscher, 5 Blutblütendrescher, 5 Blutblütenschinder und 5 Blutblütenfallen für Larion in Marshals Zuflucht.",
    [4146] = "Bringt Larion in Marshals Zuflucht den ungeladenen Schrumpfer und 5 Proben Dunst der Atal'ai.",
    [4147] = "Reist zu Marvon Rivetseekers Werkstatt in Ratchet.",
    [4161] = "Sammelt 7 kleine Spinnenbeine für Zarrin in Dolanaar.",
    [4181] = "Wenn Ihr mehr über die Goblin-Ingenieurskunst wissen wollt, dann bringt das Handbuch der Ingenieurskunst-Disziplinen zu Nixx Sprocketspring nach Gadgetzan.",
    [4182] = "Erschlagt 15 schwarze Brutlinge, 10 Exemplare der schwarzen Großdrachenbrut, 4 schwarze Wyrmkin und 1 Schwarzdrachen. Kehrt zu Helendis Riverhorn zurück, sobald die Aufgabe erledigt ist.",
    [4183] = "Reist nach Seenhain und händigt Magistrat Solomon Helendis Riverhorns Brief aus.",
    [4184] = "Reist nach Stormwind und tragt Solomons Hilfegesuch dem Hochlord Bolvar Fordragon vor. Bolvar residiert in der Burg Stormwind.",
    [4185] = "Sprecht zuerst mit Lady Katrana Prestor, dann mit Hochlord Bolvar Fordragon.",
    [4186] = "Händigt Bolvars Erlass an Magistrat Solomon in Seenhain aus.",
    [4201] = "Bringt 4 Gromsblut-Kräuter, 10 Riesensilbervenen und Nagmaras gefüllte Phiole zu Herrin Nagmara in den Blackrocktiefen.",
    [4223] = "Sprecht mit Marshal Maxwell in der brennenden Steppe.",
    [4224] = "Sprecht mit dem struppigen John, um etwas über Marshal Windsors Schicksal zu erfahren, und kehrt dann zu Marshal Maxwell zurück, wenn Ihr diese Aufgabe erledigt habt. Ihr erinnert Euch daran, dass Marshal Maxwell Euch geraten hat, ihn in einer Höhle im Norden zu suchen.",
    [4241] = "Reist zum Blackrock im Nordwesten und dann weiter zu den Blackrocktiefen. Findet heraus, was aus Marshal Windsor geworden ist. Ihr erinnert Euch daran, dass der struppige John sagte, man hätte Windsor in ein Gefängnis verschleppt.",
    [4242] = "Überbringt Marshal Maxwell die schlechten Neuigkeiten.",
    [4243] = "Sucht im Un'Goro Krater nach A-Me 01.",
    [4244] = "Sucht ein Mithrilgehäuse und bringt es zu A-Me 01 im Un'Goro Krater.",
    [4245] = "Begleitet A-Me 01 zu Karna Remtravel im Un'Goro Krater.",
    [4261] = "Bringt Arei in Sicherheit und sprecht dann mit Kayneth Stillwind in Forest Song, im Osten von Ashenvale.",
    [4262] = "Erschlagt Übermeister Pyron und kehrt dann zu Jalinda Sprig zurück. Ihr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?",
    [4263] = "Sucht Lord Incendius in den Blackrocktiefen und vernichtet ihn!",
    [4264] = "Soeben seid Ihr auf etwas gestoßen, das Marshal Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung.",
    [4265] = "Begleitet Raschal sicher aus dem Schwarmbau der Zukk'ash hinaus. Kehrt zu Ginro Hearthkindle in der Festung Feathermoon zurück und lasst ihn wissen, dass Raschal am Leben ist und dass es ihm gut geht.",
    [4266] = "Sprecht mit Shandris Feathermoon in der Festung Feathermoon.",
    [4267] = "Bringt Raschals Bericht zu Gracina Spiritmight in Darnassus.",
    [4281] = "Bringt das nicht ausgelieferte Paket zu Falfindel Waywarder in Thalanaar.",
    [4282] = "Holt Marshal Windsors verloren gegangene Informationen zurück. Marshal Windsor glaubt, dass sich die Informationen in den Händen des Golemlords Argelmach und des Generals Zornesschmied befinden.",
    [4283] = "Oralius will 50 Medaillons der Blackrock haben. Die Chancen stehen gut, dass man die Medaillons bei den Orcs in der brennenden Steppe findet.",
    [4284] = "Sammelt 7 Machtkristalle von jeder Farbe: rot, blau, gelb und grün. Bringt sie zu J. D. Collie in Marshals Zuflucht.",
    [4285] = "Findet den Standort des nördlichen Kristallpylonen im Un'Goro Krater.",
    [4286] = "Reist in die Blackrocktiefen und holt 20 Dunkeleisengürteltaschen. Kehrt zu Oralius zurück, sobald die Aufgabe erledigt ist. Ihr nehmt an, dass die Dunkeleisenzwerge in den Blackrocktiefen diese 'Gürteltaschen'-Dinger tragen.",
    [4287] = "Findet den Standort des östlichen Kristallpylonen im Un'Goro Krater.",
    [4288] = "Findet den Standort des westlichen Kristallpylonen.",
    [4289] = "Bringt Torwa Pathfinder am Eingang zum Un'Goro Krater 2 Un'Goro-Gorillapelze, 2 Un'Goro-Stampferpelze und 2 Un'Goro-Donnererpelze.",
    [4290] = "Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes; kehrt dann zu Torwa Pathfinder im Un'Goro Krater zurück.",
    [4291] = "Bringt Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater 2 Ravasaurus-Pheromondrüsen.",
    [4292] = "Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pathfinder in der Nähe des Eingangs zum Un'Goro Krater.",
    [4293] = "Sammelt Teufelswaldschleimproben von den Brühschlammern im Teufelswald. Verwendet dann die Testausrüstung neben Chemiker Fuely in Undercity, um zu sehen, welche Eurer Proben am verderbtesten sind. Bringt 5 der verderbten Teufelswaldproben, die Ihr findet, zu Chemiker Fuely.",
    [4294] = "Sammelt Un'Goro-Brühschleimerproben von jedem der Brühschleimer im Un'Goro Krater. Verwendet dann die Testausrüstung neben Chemiker Fuely in Undercity, um zu sehen, welche Eurer Proben am reinsten sind. Bringt 5 der reinen Un'Goro-Proben, die Ihr findet, zu Chemiker Fuely.",
    [4296] = "Bringt Maxwort Uberglint in der brennenden Steppe die Abschrift der Schrifttafel.",
    [4297] = "Bringt Agnar Beastamer im Hinterland 5 Silbermähnenpirscherflanken.",
    [4298] = "Sprecht mit Agnar Beastamer im Hinterland.",
    [4300] = "Bringt Jes'rimon in Orgrimmar 8 weiße Ravasaurusklauen.",
    [4301] = "Bringt U'chas Pelz zu Torwa Pathfinder am Eingang des Un'Goro Kraters.",
    [4321] = "Sprecht demnächst mit J. D. Collie.",
    [4322] = "Helft Marshal Windsor, seine Ausrüstung zurückzuholen und seine Freunde zu befreien. Kehrt zu Marshal Windsor zurück, wenn Ihr Erfolg hattet.",
    [4324] = "Sprecht mit Yuka Screwspigot in der brennenden Steppe.",
    [4341] = "Begebt Euch in die Blackrocktiefen und findet Kharan Mighthammer. Der König erwähnte, dass Kharan dort gefangen sei - vielleicht solltet Ihr nach einem Gefängnis Ausschau halten.",
    [4342] = "Lasst Kharan Mighthammer seine Geschichte erzählen.",
    [4361] = "Kehrt nach Ironforge zurück und überbringt König Magni Bronzebeard die schlechten Nachrichten.",
    [4362] = "Kehrt in die Blackrocktiefen zurück und rettet Prinzessin Moira Bronzebeard aus den Fängen des bösen Imperators Dagran Thaurissan.",
    [4363] = "Kehrt nach Ironforge zurück und sprecht mit König Magni Bronzebeard.",
    [4402] = "Bringt Galgar 10 Kaktusäpfel. Ihr erinnert Euch, dass er gesagt hat, man fände sie in der Nähe von Kakteen.",
    [4421] = "Tötet Xavathras sowie 11 Jadefeuerteufelsanbeter, 9 Jadefeuerschattenpirscher und 9 Jadefeuerschurken. Kehrt zu Eridan Bluewind im Teufelswald zurück, sobald die Aufgabe erledigt ist.",
    [4441] = "Begebt Euch nach Darnassus und verwendet Eridans Phiole, um Euch im Tempel des Mondes eine Phiole mit gesegnetem Wasser zu holen. Kehrt mit der gefüllten Phiole zu Eridan zurück.",
    [4442] = "Sprecht Eridan gleich noch einmal an.",
    [4449] = "Tötet 8 Geologen der Dunkeleisenzwerge und bringt der Person, die im Plumpsklo in der sengenden Schlucht eingesperrt ist, 15 Stücke Seidenstoff.",
    [4450] = "Nehmt die Abschrift von Goodsteels Geschäftsbuch und beschafft Euch dann die darin aufgeführten Gegenstände, ehe Ihr Krinkle Goodsteel in Tanaris aufsucht.",
    [4451] = "Sucht in der sengenden Schlucht, bis Ihr etwas findet, wofür man den Schlüssel des Grimsilt-Nebengebäudes verwenden kann, den Ihr gefunden habt.",
    [4485] = "Sprecht mit Duthorian Rall in Stormwind.",
    [4486] = "Sprecht mit Duthorian Rall in Stormwind.",
    [4487] = "Sprecht mit Strahad Farsan in Ratchet.",
    [4488] = "Sprecht mit Strahad Farsan in Ratchet.",
    [4489] = "Sprecht mit Strahad Farsan in Ratchet.",
    [4490] = "Sprecht in Ratchet mit Strahad Farsan, um zu lernen, wie man ein Teufelsross beschwört.",
    [4491] = "Führt Ringo zu Spraggle Frock in Marshals Zuflucht. Falls Ringo ohnmächtig werden sollte, verwendet Spraggles Feldflasche, um ihn zu beleben.",
    [4492] = "Sucht Ringo am Feuerfedergrat.",
    [4493] = "Sprecht in Gadgetzan mit Alchimist Pestlezugg.",
    [4494] = "Sprecht in Gadgetzan mit Alchimist Pestlezugg.",
    [4495] = "Sucht Iverron an der Höhle im Norden.",
    [4496] = "Bringt eine Gorishiduftdrüse und 5 Un'Goro-Erdproben zu Alchimist Pestlezugg in Gadgetzan.",
    [4501] = "Tötet 10 Pterrordax und 15 rasende Pterrordax und sprecht dann mit Spraggle Frock in Marshals Zuflucht.",
    [4502] = "Sammelt 9 Proben Un'Goro-Asche von den Feuerelementare am Vulkan im Un'Goro Krater ein und bringt die Proben zu Liv Rizzlefix in Ratchet.",
    [4503] = "Sammelt 8 eingesponnene Dimetrodon-Schuppen und 8 eingesponnene Pterrordax-Schuppen für Shizzle in Marshals Zuflucht.",
    [4504] = "Sammelt 12 Proben superklebrigen Teer für Tran'rek in Gadgetzan.",
    [4505] = "Beschafft eine Probe verderbten Wassers vom Mondbrunnen der Jadefeuersatyrn und bringt sie zu Winna Hazzard am Blutgiftposten.",
    [4506] = "Bringt Winnas Kätzchen zum verderbten Mondbrunnen, lasst es dort frei und bringt es dann wieder zu Winna zurück. Sobald Ihr wieder bei Winna seid, klickt auf die Katze, um sie Winna zu übergeben.",
    [4507] = "Besiegt die Schwarmkönigin der Gorishi, sobald sie erscheint. Bringt das Gehirn der Schwarmkönigin zu Alchimist Pestlezugg nach Gadgetzan.",
    [4508] = "Bringt Pestlezuggs Un'Goro-Bericht zu Gracina Spiritmight in Darnassus.",
    [4509] = "Bringt Pestlezuggs Un'Goro-Bericht zu Zilzibin Drumlore in Orgrimmar.",
    [4510] = "Bringt den Bankgutschein zu Idriana in der Bank von Darnassus.",
    [4511] = "Bringt den Bankgutschein zu Karus in der Bank von Orgrimmar.",
    [4512] = "Bringt 6 mit verfluchten Brühschlammern gefüllte Behälter und 6 mit besudelten Brühschlammern gefüllte Behälter zu Laris Geardawdle in Ironforge.",
    [4513] = "Bringt 10 mit reinen Proben gefüllte Krüge zu Laris Geardawdle in Ironforge. Falls Ihr Probleme habt, fündig zu werden, dann kann Laris Euch vielleicht noch den einen oder anderen Hinweis geben.",
    [4521] = "Trull Failbane im Teufelswald möchte, dass Ihr 15 tobende Eulenbestien und 15 struppige Eulenbestien tötet.",
    [4542] = "Bringt Klippenbehüter Longhorn am Freiwindposten die dringende Nachricht.",
    [4581] = "Bringt Shindrells Notiz zu Kayneth Stillwind in Forest Song.",
    [4621] = "Tötet Flottenmeister Seehorn und Baron Revilgaz aus Booty Bay und kehrt dann zu Flottenmeister Firallon zurück. Er befindet sich auf der CRIMSON VEIL vor der Küste des Schlingendorntals.",
    [4641] = "Sprecht mit Gornek. Euch fällt ein, dass Kaltunk auf Eurer Karte markiert hat, wo er sich befindet. Außerdem erwähnte er, dass Gornek sich im Höhlenbau aufhielte, einem Gebäude im Westen.",
    [4642] = "Bringt eine verschmolzene Brühschlammerprobe zum Chemiker Fuely in Undercity.",
    [4681] = "Bergt die Meeresschildkrötenüberreste der skelettierten Meeresschildkröte in den Gewässern westlich von Auberdine und sprecht anschließend in Auberdine mit Gwennyth Bly'Leggonde.",
    [4701] = "Begebt Euch zur Blackrockspitze und vernichtet die Quelle der Bedrohung durch die Worgs. Als Ihr Helendis verlasst, ruft er Euch noch einen Namen hinterher: Halycon. Darauf beziehen sich die Orcs im Zusammenhang mit den Worgs.",
    [4721] = "Trull Failbane im Teufelswald möchte, dass Ihr in Winterspring 10 Berserkereulenbestien jagt.",
    [4722] = "Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde.",
    [4723] = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.",
    [4724] = "Erschlagt Halycon, die Rudelführerin der Worgs der Blutäxte.",
    [4725] = "Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde.",
    [4726] = "Bringt 8 Brutlingessenzen sowie den Draco-Incarcinatrix 900 zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe.",
    [4727] = "Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde.",
    [4728] = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.",
    [4729] = "Begebt Euch zur Blackrockspitze und sucht Worgwelpen der Blutäxte. Benutzt den Käfig, um die wilden kleinen Bestien zu transportieren. Bringt einen eingesperrten Worgwelpen zu Kibler.",
    [4730] = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.",
    [4731] = "Bringt den seltsam markierten Kasten nach Auberdine zu Gwennyth Bly'Leggonde.",
    [4732] = "Bringt die Meeresschildkrötenüberreste nach Auberdine zu Gwennyth Bly'Leggonde.",
    [4733] = "Bringt die Meereskreaturknochen nach Auberdine zu Gwennyth Bly'Leggonde.",
    [4734] = "Benutzt den Prototyp des Eiszilloskops an einem Ei im Horst.",
    [4735] = "Bringt 8 eingesammelte Dracheneier sowie das kollektronische Modul zu Tinkee Steamboil am Flammenkamm in der brennenden Steppe.",
    [4736] = "Sprecht mit Menara Voidrender im Brachland.",
    [4737] = "Sprecht mit Menara Voidrender im Brachland.",
    [4738] = "Sprecht im Brachland mit Menara Voidrender.",
    [4739] = "Sprecht mit Menara Voidrender im Brachland.",
    [4740] = "Sucht und tötet den Murloc namens Gurgelbacke. Man nimmt an, dass die Kreatur die Hütten der Murlocs am Strand südlich von Auberdine beschützt. Informiert Schildwache Glynda Nal'Shea über Gurgelbackes Tod.",
    [4741] = "Trull Failbane im Teufelswald möchte, dass Ihr in Winterspring 13 mondbestrahlte Eulenbestien jagt.",
    [4742] = "Sucht die drei Edelsteine der Befehlsgewalt: den Edelstein der Gluthauer, den Edelstein der Felsspitzoger und den Edelstein der Blutäxte. Bringt sie zusammen mit dem unverzierten Siegel des Aufstiegs zu Vaelan zurück. Vaelan nannte Euch auch die Namen der drei Generäle: Kriegsmeister Voone von den Gluthauern, Hochlord Omokk von den Felsspitzogern und Oberanführer Wyrmthalak von den Blutäxten.",
    [4743] = "Reist zum Drachensumpf in den Marschen von Dustwallow. Sucht den alten Drachen Aschenschwinge auf und bekämpft ihn ohne Gnade, bis sein Wille gebrochen ist. In genau diesem Moment müsst Ihr das ungeschmiedete Siegel des Aufstiegs vor der großen Bestie hinlegen. Dann müsst Ihr schnell die Kugel der drachischen Energie auf seine geschwächte Gestalt anwenden und die Kontrolle über seine geistigen Kräfte übernehmen. Kontrolliert die Bestie und zwingt die Flammen des schwarzen Drachenschwarms auf das ungeschmiedete Siegel des Aufstiegs!",
    [4761] = "Sprecht mit Thundris Windwirker in Auberdine.",
    [4762] = "Geht von Auberdine aus nach Norden zum ersten Wasserfall des Cliffspring und entnehmt aus dem Teich dort eine Probe. Kehrt mit der Cliffspringprobe zu Thundris Windwirker nach Auberdine zurück.",
    [4763] = "Füllt die leere Säuberungsschale am Mondbrunnen in Auberdine. Holt jeweils eine Probe von Früchten, Nüssen und Getreide aus dem Lager der Schwarzfellfurbolgs im Norden. Mischt alles in der Schale und stellt diese bei dem Freudenfeuer neben dem Cliffspring auf Höhe des nördlichen Lagers ab und lockt dadurch den Satyrverderber an. Nehmt den Talisman der Verderbnis und bringt ihn zu Thundris Windwirker in Auberdine.",
    [4764] = "Bringt Mayara Brightwing in der brennenden Steppe Doomriggers Schnalle.",
    [4765] = "Bringt Ridgewells Kiste zu Remington Ridgewell nach Stormwind.",
    [4766] = "Sprecht mit Mayara Brightwing in der brennenden Steppe.",
    [4767] = "Bringt Elu am Freiwindposten 10 Eier von Steilhangflügeldrachen.",
    [4768] = "Bringt der Schattenmagierin Vivian Lagrave in Kargath die Darkstone-Schrifttafel.",
    [4769] = "Sprecht mit Schattenmagierin Vivian Lagrave.",
    [4770] = "Begleitet Pao'ka Swiftmountain aus dem Steilhang heraus und sprecht dann am Weißgipfelposten mit Motega Firemane.",
    [4771] = "Legt die Dämmerungstrickfalle in den Vorführraum von Scholomance. Besiegt Vectus und kehrt dann zu Betina Bigglezink zurück.",
    [4781] = "Bringt Xizk Goodstitch im Schlingendorntal einen Goldbarren.",
    [4782] = "Kehrt zu Menara Voidrender im Brachland zurück.",
    [4783] = "Bringt Menara Voidrender im Brachland 10 Phiolen Zornsäerblut und 1 geringen Höllenstein.",
    [4784] = "Bringt Menara Voidrender im Brachland Goldgarn, 2 glimmende Kohlen und einen Seelensplitter.",
    [4786] = "Wartet, bis Menara Voidrender Eure Robe fertig gestellt hat, und sprecht dann noch einmal mit ihr.",
    [4787] = "Bringt das uralte Ei zu Yeh'kinya nach Tanaris.",
    [4788] = "Bringt Ausgrabungsleiter Ironboot in Tanaris die fünfte und sechste Schrifttafel von Mosh'aru.",
    [4808] = "Gebt Felnok Steelspring Tinkees Brief.",
    [4809] = "Bringt Felnok Steelspring 8 unbeschädigte Hörner einer Eiswindschimäre.",
    [4810] = "Bringt Tinkee Steamboil in der brennenden Steppe Felnoks Päckchen.",
    [4811] = "Reist von Auberdine nach Osten und sucht nach einem großen, roten Kristall entlang der östlichen Bergkette von Dunkelküste. Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse.",
    [4812] = "Füllt die leere Wasserröhre am Mondbrunnen von Auberdine und untersucht dann den roten Kristall an der östlichen Bergkette von Dunkelküste.",
    [4813] = "Informiert Schildwache Glynda Nal'Shea in Auberdine über Eure Erkenntnisse.",
    [4821] = "Bringt Hagar Lightninghoof am Freiwindposten das fremdartige Ei.",
    [4841] = "Tötet 12 Späher der Galak, 10 Zänker der Galak sowie 6 Windjäger der Galak und kehrt dann zu Klippenbehüter Longhorn am Freiwindposten zurück.",
    [4842] = "Befolgt Donova Snowdens Anweisungen und meldet Euch dann wieder bei ihr.",
    [4861] = "Findet Jaron Stoneshapers ruiniertes Lager samt dessen Vorräte im südlichen Winterspring.",
    [4862] = "Reist zur Blackrockspitze und sammelt 15 Spitzenspinnen-Eier für Kibler. Logischerweise müsstet Ihr diese Eier in der Nähe von Spinnen finden.",
    [4863] = "Sucht Jaron Stoneshapers zerstörten Wagen.",
    [4864] = "Klaubt Jarons Vorräte aus dem Schnee und sucht dann die Wildekin, die das Amulett gestohlen haben, von dem Jaron gesprochen hatte. Bringt Jaron Stoneshaper in der Lodge in Winterspring dessen Vorräte und das blaugefiederte Amulett.",
    [4865] = "Berichtet Motega Firemane von Euren Entdeckungen.",
    [4866] = "Ihr findet Mutter Glimmernetz im Herzen der Blackrockspitze. Kämpft mit ihr und bringt sie dazu, Euch zu vergiften. Es kann gut sein, dass Ihr sie sogar töten müsst. Kehrt zum struppigen John zurück, sobald Ihr vergiftet seid, damit er Euch 'melken' kann.",
    [4867] = "Lest Waroshs Rolle. Bringt Waroshs Mojo zu Warosh.",
    [4881] = "Warnt Kanati Greycloud am Weißgipfelposten, dass man vorhat, ihn zu töten.",
    [4882] = "Bringt Trull Failbane beim Blutgiftposten das blaugefiederte Amulett.",
    [4883] = "Bringt Nara Wildmane das blaugefiederte Amulett.",
    [4901] = "Schützt Ranshalla, während sie versucht, den Altar von Elune wieder zu aktivieren. Berichtet Erelas Ambersky in Rut'theran von Eurem Fund.",
    [4902] = "Sprecht mit Erzdruide Fandral Staghelm in Darnassus.",
    [4903] = "Tötet Hochlord Omokk, Kriegsmeister Voone und Oberanführer Wyrmthalak. Findet die wichtigen Blackrockdokumente. Kehrt zum Kriegsherrn Goretooth nach Kargath zurück, sobald Ihr diese Mission erledigt habt.",
    [4904] = "Geleitet Lakota Windsong vom Düsterwolkengipfel hinab und sprecht dann im Freiwindposten mit Thalia Amberhide.",
    [4906] = "Eridan Bluewind im Teufelswald möchte, dass Ihr Xavaric sowie 8 Jadefeuerhöllenrufer, 8 Jadefeuerverräter und 8 Jadefeuerschwindler tötet. Kehrt zu Eridan zurück, sobald Ihr die Aufgabe erfüllt habt.",
    [4907] = "Sprecht mit Tinkee Steamboil.",
    [4921] = "Sucht Mankriks Frau und kehrt dann zu ihm nach Crossroads zurück.",
    [4941] = "Sprecht mit Etrigg in Orgrimmar. Wenn Ihr die Angelegenheit mit Etrigg besprochen habt, bittet Thrall um Rat. Ihr erinnert Euch, dass Ihr Etrigg in Thralls Gemächern gesehen habt.",
    [4961] = "Tötet den Dämon der Kugel und sprecht dann mit Tabetha.",
    [4962] = "Nehmt den Felhas-Rubin und benutzt ihn bei einem der Teufelshunde von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Voidrender im Brachland den eingekerkerten Teufelshundgeist und den Felhas-Rubin.",
    [4963] = "Nehmt den Infus-Smaragd und benutzt ihn bei einer der Höllenbestien von Desolace. Wenn Ihr Erfolg hattet, bringt Menara Voidrender im Brachland den eingekerkerten Höllenbestiengeist und den Infus-Smaragd.",
    [4964] = "Wartet, bis Menara Voidrender die Kugel von Dar'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr.",
    [4965] = "Sprecht mit Menara Voidrender im Brachland.",
    [4966] = "Beschützt Kanati Greycloud vor den Angriffen der Zentauren.",
    [4967] = "Sprecht mit Menara Voidrender im Brachland.",
    [4968] = "Sprecht mit Menara Voidrender im Brachland.",
    [4969] = "Sprecht mit Menara Voidrender im Brachland.",
    [4970] = "Sammelt 5 Splitterzahnfleischstücke und 5 Fleischstücke einer Eiswindschimäre für Rivern Frostwind in Winterspring.",
    [4971] = "Benutzt den Temporalversetzer in der Nähe eines der Silos von Andorhal, um die temporalen Parasiten aufzuspüren. Tötet 15 temporale Parasiten und bringt dann den Temporalversetzer zu Chromie im Gasthaus Andorhal in den Westlichen Pestländern.",
    [4972] = "Sucht 5 Andorhal-Uhren, die in Schließkassetten überall im Schutt der Stadt zu finden sind. Kehrt mit ihnen zu Chromie ins Gasthaus Andorhal in den Westlichen Pestländern zurück.",
    [4973] = "Sucht 5 Andorhal-Uhren in den Ruinen der Stadt und bringt sie Chromie im Gasthaus Andorhal in den Westlichen Pestländern.",
    [4974] = "Begebt Euch zur Blackrockspitze und tötet den Kriegshäuptling Rend Blackhand. Nehmt seinen Kopf und kehrt nach Orgrimmar zurück.",
    [4975] = "Wartet, bis Menara Voidrender die Kugel von Noh'Orahil fertig gestellt hat, und sprecht dann noch einmal mit ihr.",
    [4976] = "Bringt die gesäuberte Höllenkugel zu Menara Voidrender ins Brachland.",
    [4981] = "Begebt Euch zur Blackrockspitze und findet heraus, was aus Bijou geworden ist.",
    [4982] = "Sucht Bijous Habseligkeiten und bringt sie ihr. Ihr erinnert Euch daran, dass sie erwähnte, ihre Sachen auf der untersten Ebene der Stadt versteckt zu haben.",
    [4983] = "Bringt Bijous Aufklärungsbericht zu Großmeister Lexlort nach Kargath.",
    [4984] = "Tötet 8 kranke Wölfe und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück.",
    [4985] = "Tötet 8 kranke Grizzlys und kehrt dann zu Mulgris Deepriver auf dem trostlosen Feld in den Westlichen Pestländern zurück.",
    [4986] = "Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Darnassus bringt. Bittet einen der Druiden dort um Hilfe.",
    [4987] = "Nach der Magie zu urteilen, mit der der glyphenverzierte Eichenast erfüllt ist, hatte der Taurendruide wohl gewollt, dass Ihr den Ast zum Zirkel des Cenarius nach Thunder Bluff bringt. Bittet einen der Druiden dort um Hilfe.",
    [5001] = "Sucht Bijous Habseligkeiten und bringt sie ihr. Viel Glück!",
    [5002] = "Begebt Euch in die brennende Steppe und leitet Bijous Informationen an Marshal Maxwell weiter.",
    [5021] = "Das wilde Gebrabbel der Geisterfrau deutete darauf hin, dass sie ein Paket ausliefern musste. Sie behauptete, dass es dort war, wo auch ihr Pferd war. Darüber, wo das Pferd jetzt ist oder wohin das Paket ausgeliefert werden muss, sagt der Geist nichts.",
    [5022] = "Wendet Euch an die königlichen Disponenten von Stormwind, um etwas über den Aufenthaltsort von Emma Felstone herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter im Rathaus.",
    [5023] = "Wendet Euch an die königlichen Vorarbeiter von Undercity, um etwas über den Aufenthaltsort von Jeremiah Felstone herauszufinden. Normalerweise findet sich ein Volkszählungsbeamter in der Nähe der Gilden- und Wappenrock-Registrierung.",
    [5041] = "Findet die Crossroads-Vorratskisten und bringt sie zu Thork im Brachland zurück.",
    [5047] = "Sprecht mit Malyfous Darkhammer in Everlook.",
    [5048] = "Sucht die alte Emma in Stormwind und findet heraus, ob sie tatsächlich Emma Felstone ist. Wenn sie es ist, dann möchte sie vielleicht das Paket haben, das Janice Felstone für sie gepackt hat.",
    [5049] = "Sucht Jeremiah Payson in Undercity und findet heraus, ob er tatsächlich Jeremiah Felstone ist. Wenn er es ist, dann möchte er vielleicht das Paket haben, das Janice Felstone für ihn gepackt hat.",
    [5050] = "Bringt Janice Felstone in den Westlichen Pestländern die Hälfte ihres Glücksbringers zurück.",
    [5051] = "Sucht auf dem Teufelssteinfeld in den Westlichen Pestländern nach der anderen Hälfte des Glücksbringers und setzt ihn wieder zusammen. Gebt den Glücksbringer Janice Felstone auf demTeufelssteinfeld in den Westlichen Pestländern.",
    [5052] = "Bringt Quetschzahn im Camp Taurajo im Brachland einen Blutsplitter. Sammelt weitere Blutsplitter, wenn Ihr von ihm mit Agammagans Macht gesegnet werden möchtet.",
    [5054] = "Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Ursius tötet.",
    [5055] = "Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Brumeran tötet.",
    [5056] = "Storm Shadowhoof in Everlook in Winterspring möchte, dass Ihr Shy-Rotam besiegt.",
    [5057] = "Bringt Storm Shadowhoofs Gutschein zu Melor Stonehoof in Thunder Bluff.",
    [5061] = "Kehrt nach Darnassus zurück und zeigt Mathrengyl Bearwalker den Anhänger des Seelöwen.",
    [5062] = "Sammelt 10 Scheffel Brandpulveragaven und beratet Euch dann mit Magatha Grimmtotem auf der Anhöhe der Ältesten in Thunder Bluff.",
    [5063] = "Um die Kappe des scharlachroten Wissenden herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Darkhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 8 Arkankristalle; 5 verzauberte scharlachrote Fäden. Ihr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.",
    [5064] = "Sucht die drei geheimen Notizen im Düsterwolkengipfel und bringt sie zurück.",
    [5065] = "Bringt Ausgrabungsleiter Ironboot in Tanaris die dritte und vierte Schrifttafel von Mosh'aru.",
    [5066] = "Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges.",
    [5067] = "Um die Gamaschen von Arcana herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Darkhammer bringen: 1 makelloser Balg der Bestie; 5 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Einheiten Frostraunens Balsamierungsflüssigkeit. Ihr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.",
    [5068] = "Um die Brustplatte des Blutdurstes herzustellen, müsst Ihr die folgenden Dinge zu Malyfous Darkhammer bringen: 1 makelloser Balg der Bestie; 10 ausgefranste Monstrositätenstickereien; 5 Arkanitbarren; 5 Häute des Schattens. Ihr müsst außerdem 50 Goldstücke für die Herstellung des Gegenstandes zahlen.",
    [5081] = "Reist zur Blackrockspitze und schaltet Kriegsmeister Voone, Hochlord Omokk und Oberanführer Wyrmthalak aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist.",
    [5082] = "Donova Snowden in Winterspring möchte, dass Ihr 8 Pfadfinder der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Totemiker der Winterfelle erledigt.",
    [5083] = "Bringt das leere Feuerwasserfläschchen zu Donova Snowden in Winterspring.",
    [5084] = "Durchsucht das Furbolglager der Totenwaldfelle im nördlichen Teil des Teufelswalds nach einem Hinweis.",
    [5085] = "Berichtet Donova Snowden von Euren Entdeckungen.",
    [5086] = "Sammelt 3 Toxinschrecken-Tröpfchen für Donova Snowden in Winterspring.",
    [5087] = "Sucht die Läufer der Winterfelle und hindert sie daran, ihre Lieferung zum Lager der Winterfelle zu bringen.",
    [5088] = "Tötet Arikara. Bringt ihre Überreste und das Brandpulver zu Motega Firemane im Weißgipfelposten als Beweis für Eure Taten.",
    [5089] = "Bringt den Befehl von General Drakkisath zu Marshal Maxwell in der brennenden Steppe.",
    [5090] = "Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges.",
    [5091] = "Sucht Kommandant Ashlam Valorfist auf. Sein Stützpunkt befindet sich an der Chillwindspitze, nördlich des Alteracgebirges.",
    [5092] = "Tötet 10 Skelettschinder und 10 sabbernde Ghuls in Sorrow Hill. Kehrt zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück.",
    [5093] = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity.",
    [5094] = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity.",
    [5095] = "Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Undercity.",
    [5096] = "Zieht zum Basislager des Scharlachroten Kreuzzugs zwischen dem Teufelssteinfeld und Dalsons Tränenfeld und zerstört sein Kommandozelt. Lasst das Banner der Geißel im Lager wehen und kehrt dann zu Hochexekutor Derrington am Bollwerk in den Westlichen Pestländern zurück.",
    [5097] = "Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren. Wenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Kommandant Ashlam Valorfist an der Chillwindspitze, Westliche Pestländer, zurück.",
    [5098] = "Markiert mit der Signalfackel jeden Turm in Andorhal; Ihr müsst im Eingang jedes Turmes stehen, um ihn erfolgreich zu markieren. Wenn alle vier Türme markiert sind, bringt Ihr die Signalfackel zu Hochexekutor Derrington am Bollwerk, Westliche Pestländer, zurück.",
    [5102] = "Begebt Euch zur Blackrockspitze und schaltet General Drakkisath aus. Kehrt zu Marshal Maxwell zurück, wenn Eure Aufgabe erledigt ist.",
    [5103] = "Jemand auf dieser Welt muss doch wissen, was mit diesen Stulpen zu tun ist. Viel Glück!",
    [5121] = "Donova Snowden in Winterspring möchte, dass Ihr den Oberhäuptling der Winterfelle besiegt.",
    [5123] = "Bringt das kunstlos geschriebene Logbuch zu Donova Snowden in Winterspring.",
    [5124] = "Bringt Malyfous Darkhammer 6 verzauberte Thoriumbarren, 2 Essenzen des Feuers und 4 Sternrubine. Ihr müsst außerdem Eure ungebrannten Plattenstulpen abgeben.",
    [5126] = "Sprecht mit Lorax. Hört, was er zu sagen hat.",
    [5127] = "Begebt Euch zur Blackrockspitze und sucht Goraluk Hammerbruch. Erschlagt ihn und wendet dann die blutbefleckte Pike auf seine Leiche an. Nachdem seine Seele abgesaugt wurde, wird die Pike seelenbefleckt sein. Ihr müsst außerdem die ungeschmiedete runenbedeckte Brustplatte finden. Bringt die seelenbefleckte Pike und die ungeschmiedete runenbedeckte Brustplate zu Lorax in Winterspring.",
    [5128] = "Bringt das kunstlos geschriebene Logbuch zu Kelek Skykeeper im südlichen Teil des Teufelswalds.",
    [5141] = "Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Peter Galen in Azshara. Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten. Ihr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.",
    [5142] = "Sucht Pamela Redpath.",
    [5143] = "Bringt eine Wildlederweste und einen Wildlederhelm zu Caryssia Moonhunter in Feralas. Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten. Wenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.",
    [5144] = "Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Sarah Tanner in die sengende Schlucht. Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten. Wenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.",
    [5145] = "Bringt 2 feste Skorpidbrustplatten, 2 feste Skorpidhandschuhe und 10 Drachenschuppen zu Thorkaf Dragoneye im Ödland. Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Drachenlederverarbeitung erhalten. Ihr könnt dann allerdings weder Elementarlederverarbeitung noch Stammeslederverarbeitung erlernen; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.",
    [5146] = "Bringt 2 Herzen des Feuers, 2 Kugeln des Wassers, 2 Erdenkerne und 2 Odem des Windes zu Brumn Winterhoof in den Arathi-Bergen. Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Elementarlederverarbeitung erhalten. Wenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Stammeslederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.",
    [5147] = "Erschlagt Arnak Grimmtotem und bringt den Beweis Eurer Tat zu Klippenbehüter Longhorn im Freiwindposten.",
    [5148] = "Bringt eine Wildlederweste und einen Wildlederhelm zu Se'Jib im Schlingendorntal. Wenn Ihr diese Aufgabe abschließt, werdet Ihr Zugang zur Kunst der Stammeslederverarbeitung erhalten. Wenn Ihr diese Aufgabe abschließt, werdet Ihr allerdings weder Drachenlederverarbeitung noch Elementarlederverarbeitung erlernen können; seid also vorher sicher, dass dies der Weg ist, dem Ihr folgen wollt.",
    [5149] = "Sucht Pamelas Puppe.",
    [5151] = "Erschlagt die Bestie und bringt den Hyperkondensator sowie den Pantherkäfigschlüssel zu Wizlo Bearingshiner zurück.",
    [5152] = "Sprecht mit Marlene, südlich der Ruinen von Andorhal.",
    [5153] = "Bringt Josephs Ehering zu Chromie.",
    [5154] = "Bringt die 'Annalen von Darrowshire' zu Chromie in Andorhal.",
    [5155] = "Betretet Jaedenar und erschlagt 4 Hunde von Jaedenar, 4 Gardisten von Jaedenar, 6 Adepten von Jaedenar und 6 Kultisten von Jaedenar, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt.",
    [5156] = "Sucht und zerstört 2 entropische Bestien und 2 entropische Schrecken, während Ihr das Shatter Scar-Tal erforscht. Nachdem Ihr überprüft habt, ob die Krater immer noch mit verderbtem Fel-Wasser gefüllt sind, kehrt zu Taronn Redfeather im Teufelswald zurück.",
    [5157] = "Bringt die leere Feldflasche zum Mondbrunnen im Zentrum von Jaedenar und füllt sie, bevor Ihr zu Greta Mosshoof im Teufelswald zurückkehrt.",
    [5158] = "Bringt das verderbte Mondbrunnenwasser in das Brachland zu Islen Waterseer.",
    [5159] = "Bringt das geläuterte Mondbrunnenwasser zu Greta Mosshoof im Teufelswald.",
    [5160] = "Begebt Euch nach Winterspring und sucht Haleh. Gebt ihr Awbees Schuppe.",
    [5161] = "Sprecht mit Haleh, wenn Ihr weitermachen wollt.",
    [5162] = "Sprecht mit Jeziba in den Pestländern. Er wohnt in Andorhal.",
    [5163] = "Nehmt Umis mechanischen Yeti und erschreckt ihre Freunde damit: Legacki in Everlook (Winterspring) Sprinkle in Gadgetzan (Tanaris) Quixxil in Marshals Zuflucht (Un'Goro Krater) Wenn Ihr damit fertig seid, bringt den mechanischen Yeti zu Umi zurück.",
    [5164] = "Lest das 'Verzeichnis der Abtrünnigen'.",
    [5165] = "Übergießt die Flammen der vier Kohlenpfannen des Schutzes in der Schattenfeste im Teufelswald mit dem geläuterten Mondbrunnenwasser.",
    [5166] = "Um die Brustplatte des chromatischen Drachenschwarms zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen: 1 chromatischer Knochenpanzer. 10 glänzende chromatische Schuppen. 10 Einheiten Blut von Helden. 10 ausgefranste Monstrositätenstickereien.",
    [5167] = "Um die Beinplatten des chromatischen Widersetzers zu schmieden, müsst Ihr die folgenden Gegenstände zu Jeziba dem 'Bildhauer' bringen: 1 chromatischer Knochenpanzer. 10 glänzende chromatische Schuppen. 10 Einheiten Blut von Helden. 5 Häute des Schattens.",
    [5168] = "Bringt Davils Buchband und Redpaths Schild zu Carlin Redpath.",
    [5181] = "Bringt den Schädel von Horgus und das zertrümmerte Schwert von Marduk zu Carlin Redpath in der Kapelle des hoffnungsvollen Lichts.",
    [5201] = "Rivern Frostwind möchte, dass Ihr 5 Schamanen der Winterfelle und 5 Ursa der Winterfelle erschlagt.",
    [5202] = "Durchsucht Jaedenar, um herauszufinden, wofür der blutrote Schlüssel verwendet wird.",
    [5203] = "Bringt Arko'narin dorthin, wo Lightforge und ihre Ausrüstung aufbewahrt werden, und beschützt sie dann bei eurer Flucht aus der Schattenfeste. Sucht danach Jessir Moonbow im Teufelswald auf und lasst sie wissen, was mit ihren Freunden geschehen ist.",
    [5204] = "Kehrt nach Jaedenar zurück und tötet den Sukkubus Rakaiah, bevor Ihr die Überreste von Trey Lightforge sucht.",
    [5206] = "Bringt 5 widerhallende Schädel und den mystischen Kristall zu Carlin Redpath in den Östlichen Pestländern.",
    [5210] = "Bringt die erweiterten 'Annalen von Darrowshire' zu Carlin Redpath in den Östlichen Pestländern.",
    [5211] = "Befreit 15 Geister von Darrowshire und kehrt dann zu Carlin Redpath zurück.",
    [5212] = "Sammelt 20 verseuchte Fleischproben in Stratholme und bringt sie zu Betina Bigglezink zurück. Ihr vermutet, dass Ihr besagte Fleischproben bei jeder Kreatur in Stratholme finden könnt.",
    [5213] = "Reist nach Stratholme und durchsucht die Ziggurats. Sucht neue Geißeldaten und bringt sie zu Betina Bigglezink zurück.",
    [5214] = "Sucht Ezra Grimms Raucherladen in Stratholme und bergt einen Kasten von Grimms Tollem Tabak. Kehrt zu Smokey LaRue zurück, wenn Eure Aufgabe erledigt ist.",
    [5215] = "Sprecht mit der Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.",
    [5216] = "Geht zum Teufelssteinfeld im den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.",
    [5217] = "Bringt die gefüllte Flasche: Teufelssteinfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.",
    [5219] = "Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.",
    [5220] = "Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.",
    [5222] = "Begebt Euch zum trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.",
    [5223] = "Bringt die gefüllte Flasche: Das trostlose Feld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.",
    [5225] = "Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.",
    [5226] = "Bringt die gefüllte Flasche: Gahrrons Trauerfeld zur Hohepriesterin MacDonnell an der Chillwindspitze, Westliche Pestländer.",
    [5228] = "Sprecht mit der Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer.",
    [5229] = "Geht zum Teufelssteinfeld im den Westlichen Pestländern. Sucht nach dem dortigen Kessellord und besiegt ihn. Er könnte einen Schlüssel haben, der den Zugang zu dem Kessel ermöglicht. Ihr müsst die leere Flasche: Teufelssteinfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.",
    [5230] = "Bringt die gefüllte Flasche: Teufelssteinfeld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer.",
    [5231] = "Begebt Euch zu Dalsons Tränenfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Dalsons Tränenfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.",
    [5232] = "Bringt die gefüllte Flasche: Dalsons Tränenfeld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer.",
    [5233] = "Begebt Euch zum trostlosen Feld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Das trostlose Feld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.",
    [5234] = "Bringt die gefüllte Flasche: Das trostlose Feld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer.",
    [5235] = "Begebt Euch zu Gahrrons Trauerfeld in den Westlichen Pestländern, um den dortigen Kessellord zu suchen und zu besiegen. Verwendet dann seinen Schlüssel, um Zugang zum Kessel zu erhalten. Ihr müsst die leere Flasche: Gahrrons Trauerfeld bei Euch haben, um eine Probe des Giftes zu entnehmen, das sich in dem Kessel findet.",
    [5236] = "Bringt die gefüllte Flasche: Gahrrons Trauerfeld zur Schattenpriesterin Vandis am Bollwerk, Westliche Pestländer.",
    [5241] = "Sucht Carlin Redpath.",
    [5242] = "Tötet Moora und Salia und bringt den Kopf von Schattenlord Fel'dan zu Greta Mosshoof im Teufelswald.",
    [5243] = "Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Heiliges Wasser von Stratholme. Kehrt zu Leonid Barthalomew dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt.",
    [5244] = "Sprecht mit Jaron Stoneshaper in Starfall.",
    [5245] = "Benutzt Jarons Hacke, um die vier Fragmente des Hochgeborenenrelikts zu suchen. Bringt sie zu Aurora Skycaller in den Östlichen Pestländern.",
    [5246] = "Sucht die hochheiligen Schriften der Hochgeborenen im Tempel von Zin-Malor in Azshara und bringt sie zu Aurora Skycaller beim Nordpassturm in den östlichen Pestländern.",
    [5247] = "Bringt einen verzauberten Thoriumbarren, 5 Kristallflicker und eine Phiole mit Düsterwasser zu Aurora Skycaller beim Nordpassturm in den östlichen Pestländern.",
    [5248] = "Bringt den Kristall von Zin-Malor zum Kel'Therilsee in Winterspring und sucht einen Geist eines Hochgeborenen, der mit Euch sprechen will.",
    [5249] = "Sucht Starfall in Winterspring und sprecht mit Wynd Nightchaser.",
    [5250] = "Sucht Starfall in Winterspring und sprecht mit Wynd Nightchaser.",
    [5251] = "Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv.",
    [5252] = "Sprecht mit Wynd Nightchaser in Starfall und fragt nach dem richtigen Ort für den Kristall von Zin-Malor.",
    [5253] = "Überbringt dem Erzdruiden Fandral Staghelm in Darnassus den Kristall von Zin-Malor.",
    [5261] = "Sprecht mit Eagan Peltskinner.",
    [5262] = "Bringt den Kopf von Balnazzar zu Fürst Nicholas Zverenhoff in den Östlichen Pestländern.",
    [5263] = "Zieht nach Stratholme und vernichtet Baron Rivendare. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück.",
    [5264] = "Sprecht mit Lord Maxwell Tyrosus. Er befindet sich in der Kirche.",
    [5265] = "Öffnet den Argentumtresor und nehmt Euch Eure Belohnung.",
    [5281] = "Sucht Egan. Ihr wisst nur, dass er zuletzt in der Nähe von Stratholme gesehen wurde.",
    [5282] = "Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei! Befreit 15 ruhelose Seelen und kehrt zu Egan zurück.",
    [5283] = "Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Grumnus bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte.",
    [5284] = "Um Waffenschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Ironus bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben.",
    [5301] = "Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Okothos bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte.",
    [5302] = "Um Waffenschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Borgosh bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben.",
    [5305] = "Begebt Euch nach Stratholme und tötet den purpurroten Hammerschmied. Nehmt die Schürze des purpurroten Hammerschmiedes und kehrt zu Lilith zurück.",
    [5306] = "Begebt Euch zur Blackrockspitze und erschlagt Schattenjägerin Vosh'gajin. Holt Vosh'gajins Schlangenstein und kehrt zu Kilram zurück.",
    [5307] = "Findet den Schwertschmied der schwarzen Wache in Stratholme und vernichtet ihn. Holt die Insignien der schwarzen Wache und kehrt zu Seril Scourgebane zurück.",
    [5321] = "Eskortiert Kerlonian Evershade zu Liladris Moonriver nach Süden entlang der Straße, um seine Tasche in Dunkelküste zu finden.",
    [5341] = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Alexi Barov zurück, sobald die Aufgabe erledigt ist.",
    [5342] = "Begebt Euch zum Chillwind-Lager - Territorium der Allianz - und ermordet Weldon Barov. Nehmt seinen Kopf und kehrt zu Alexi Barov zurück. Seid gewarnt, Weldon wird wahrscheinlich gut von Abschaum der Allianz geschützt.",
    [5343] = "Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Caer Darrow, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Southshore. Kehrt zu Weldon Barov zurück, sobald die Aufgabe erledigt ist.",
    [5344] = "Begebt Euch zum Bollwerk - Territorium der Horde - und ermordet Alexi Barov. Nehmt seinen Kopf und kehrt zu Weldon Barov zurück. Seid gewarnt, Alexi wird wahrscheinlich gut durch Abschaum der Horde geschützt.",
    [5361] = "Bringt den Bericht von Klippenbehüter Longhorn zu Nataka Longhorn am Geistwandlerposten in Desolace.",
    [5381] = "Holt den Dämonenkasten aus der Festung Thunder Axe und kehrt damit zu Taiga Wisemane nach Shadowprey zurück.",
    [5382] = "Sucht Doktor Theolen Krastinov in der Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt.",
    [5384] = "Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren. Kämpft tapfer, gebt keinen Fußbreit nach! Vernichtet Kirtonos und kehrt zu Eva Sarkhoff zurück.",
    [5385] = "Bringt die Überreste von Trey Lightforge zu Jessir Moonbow im Teufelswald.",
    [5386] = "Sprecht mit Jinar'Zillen in Shadowprey und bringt Nataka Longhorn dann 2 Blutbauchfische.",
    [5441] = "Benutzt den Totschläger des Großknechts an faulen Peons, wenn sie schlafen. Weckt 5 Peons auf und bringt dann den Totschläger des Großknechts zu Großknecht Thazz'ril ins Tal der Prüfungen zurück.",
    [5461] = "Reist in das Arathihochland zu den Ruinen von Stromgarde. Durchsucht Stromgarde nach einem Andenken der Erinnerung. Wenn Ihr einen solchen Gegenstand findet, kehrt mit ihm zu Magistrat Marduke zurück.",
    [5462] = "Reist zur Hoffnung des Lichts in den Östlichen Pestländern und sucht Leonid Barthalomew den Geachteten auf. Zeigt ihm das Andenken der Erinnerung und berichtet ihm alles, was Ihr entdeckt habt.",
    [5463] = "Begebt Euch nach Stratholme und sucht Menethils Geschenk. Platziert das Andenken der Erinnerung auf dem unheiligen Boden.",
    [5464] = "Bringt das seelengebundene Andenken zu Leonid Barthalomew in den Östlichen Pestländern.",
    [5465] = "Kehrt zu Magistrat Marduke in Caer Darrow zurück. Zeigt ihm das seelengebundene Andenken.",
    [5466] = "Sucht Ras Frostraunen in der Scholomance. Wenn Ihr ihn gefunden habt, wendet das seelengebundene Andenken auf sein untotes Antlitz an. Solltet Ihr ihn erfolgreich in einen Sterblichen zurückverwandeln können, dann schlagt ihn nieder und nehmt den menschlichen Kopf von Ras Frostraunen an Euch. Bringt den Kopf zu Magistrat Marduke.",
    [5481] = "Sammelt 3 Düsterkräuter und bringt sie zu Jungapotheker Holland auf den Brill-Friedhof.",
    [5482] = "Sammelt 10 Verdammniskräuter und bringt sie zu Jungapotheker Holland.",
    [5501] = "Bringt Bibbly F'utzbuckle bei Kormeks Hütte 10 Kodoknochen vom Kodofriedhof.",
    [5504] = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Hasana ins Bollwerk in den westlichen Pestländern.",
    [5507] = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Lightspark im Chillwind-Lager in den westlichen Pestländern.",
    [5513] = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Breechlock an der Kapelle des hoffnungsvollen Lichts, östliche Pestländer.",
    [5514] = "Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goodsteel in Gadgetzan.",
    [5515] = "Sucht nach Jandice Barov in der Scholomance und vernichtet sie. Entnehmt ihrer Leiche Krastinovs Tasche der Schrecken. Bringt die Tasche zu Eva Sarkhoff.",
    [5517] = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Breechlock an der Kapelle des hoffnungsvollen Lichts, östliche Pestländer.",
    [5518] = "Bringt 4 Runenstoffballen, 8 Stücke unverwüstliches Leder, 2 Runenfaden und etwas Ogergerbemittel zu Knot Thimblejack. Momentan ist er im Gordokflügel von Düsterbruch angekettet.",
    [5521] = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Lightspark im Chillwind-Lager in den westlichen Pestländern.",
    [5522] = "Bringt die gefrorenen Eier zu Leonid Barthalomew in den Östlichen Pestländern.",
    [5524] = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Hasana ins Bollwerk in den westlichen Pestländern.",
    [5526] = "Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach, werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Requiliar der Reinheit, um darin den Splitter sicher zu versiegeln und bringt das versiegelte Reliquiar zu Rabine Saturna in Nighthaven, Moonglade.",
    [5527] = "Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nighthaven, Moonglade zurück.",
    [5529] = "Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts zurück.",
    [5531] = "Bringt die gefrorenen Eier zu Betina Bigglezink.",
    [5533] = "Sprecht mit Alchimist Arbington an der Chillwindspitze, Westliche Pestländer.",
    [5534] = "Sucht, in den Ruinen von Eldarath irgendeine Rune, die die Naga in ihrem Besitz haben, und bringt sie Kim'jal in Azshara.",
    [5535] = "Vernichtet 6 Erscheinungen einer Hochgeborenen und 6 Lichlinge eines Hochgeborenen, bevor Ihr zu Loh'atu in Azshara zurückkehrt.",
    [5536] = "Tötet 6 Satyrn der Haldarr, 2 Schwindler der Haldarr sowie 2 Teufelsanbeter der Haldarr und kehrt dann zu Loh'atu an der Grenze zu Ashenvale zurück.",
    [5537] = "Bringt 15 Skelettfragmente zu Alchimist Arbington an der Chillwindspitze, Westliche Pestländer.",
    [5538] = "Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goodsteel in Gadgetzan.",
    [5541] = "Bringt Rumbleshots Munition zu Hegnar Rumbleshot in Dun Morogh.",
    [5542] = "Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt.",
    [5543] = "Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück.",
    [5544] = "Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt.",
    [5545] = "Bringt 8 Holzbündel zu Raelen beim Holzfällerlager des Osttals.",
    [5561] = "Bringt fünf gezähmte Kodos sowie den Kodokombobulator zu Smeed Scrabblescrew bei Scrabblescrews Lager.",
    [5581] = "Verbannt 6 Portale in Mannorocs Koven und kehrt dann zu Taiga Wisemane nach Shadowprey zurück.",
    [5582] = "Bringt die gesunde Großdrachenschuppe zu Betina Bigglezink bei der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern.",
    [5601] = "Sucht Pamela Redpath in Darrowshire.",
    [5621] = "Sucht die Schildwache Shaya und heilt ihre Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Laurna Morninglight in Dolanaar zurück.",
    [5622] = "Sprecht mit Laurna Morninglight in Teldrassil.",
    [5623] = "Sprecht mit der Priesterin Josetta im Wald von Elwynn.",
    [5624] = "Sucht die Wache Roberts und heilt seine Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Priesterin Josetta in Goldhain zurück.",
    [5625] = "Sucht den Gebirgsjäger Dolf und heilt seine Wunden mit Hilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Maxan Anvol in Kharanos zurück.",
    [5626] = "Sprecht mit Maxan Anvol in Dun Morogh.",
