    [5661] = "Sprecht mit Aelthalyste in Undercity.",
    [5662] = "Sprecht mit Aelthalyste in Undercity.",
    [5663] = "Sprecht mit Aelthalyste in Undercity.",
    [5673] = "Sprecht mit der Priesterin Alathea in Darnassus.",
    [5674] = "Sprecht mit der Priesterin Alathea in Darnassus.",
    [5675] = "Sprecht mit der Priesterin Alathea in Darnassus.",
    [5677] = "Sprecht mit der Hohepriesterin Laurena in Stormwind.",
    [5678] = "Sprecht mit der Hohepriesterin Laurena in Stormwind.",
    [5713] = "Schützt die Schildwache Aynasha und sprecht dann mit Onaeya bei Maestras Posten in Ashenvale.",
    [5721] = "Legt das Reliktbündel auf den Marktplatz von Darrowshire. Verhindert Davil Lightfires Tod, bis Horgus stirbt. Verhindert Captain Redpaths Tod, bis Redpath der Verderbte erscheint. Besiegt Redpath den Verderbten. Sprecht mit dem Geist von Josef Redpath, sobald er auf dem Marktplatz erscheint, und sprecht dann mit Pamela in ihrem Zuhause.",
    [5722] = "Sucht im Ragefireabgrund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen.",
    [5723] = "Sucht in Orgrimmar nach dem Ragefireabgrund, tötet dann 8 Ragefire-Troggs und 8 Ragefire-Schamanen und kehrt anschließend zu Rahauro in Thunder Bluff zurück.",
    [5724] = "Bringt den Grimmtotemranzen zu Rahauro nach Thunder Bluff.",
    [5725] = "Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Varimathras nach Undercity.",
    [5726] = "Bringt die Insignie eines Offiziers zu Thrall nach Orgrimmar.",
    [5727] = "Bringt Neeru Fireblade die Insignie des Offiziers und sprecht mit ihm. Seht, ob er Euch glaubt, dass Ihr ein Mitglied der Burning Blade seid, und kehrt dann zu Thrall nach Orgrimmar zurück.",
    [5728] = "Tötet Bazzalan und Jergosh den Herbeirufer, bevor Ihr zu Thrall nach Orgrimmar zurückkehrt.",
    [5729] = "Sprecht mit Neeru Fireblade in Orgrimmar.",
    [5730] = "Sprecht in Orgrimmar mit Thrall und berichtet ihm, was Ihr erfahren habt.",
    [5741] = "Besorgt das Szepter des Lichts und bringt es zurück zu Azore Aldamort am Turm in Ethel Rethor.",
    [5742] = "Hört Euch an, was Tirion Fordring zu sagen hat.",
    [5761] = "Begebt Euch in den Ragefireabgrund und erschlagt Taragaman den Hungerleider. Bringt anschließend dessen Herz zu Neeru Fireblade nach Orgrimmar.",
    [5762] = "Bringt Kravels Kiste zu Hemet Nesingwary ins Schlingendorntal.",
    [5763] = "Bringt Roons Kodohorn zu Hemet Nesingwary ins Schlingendorntal.",
    [5781] = "Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.",
    [5801] = "Bringt die Skelettschlüsselform und 2 Barren Thorium zur Spitze des Feuerfedergrats im Un'Goro Krater. Benutzt die Skelettschlüsselform am Lavasee, um den unvollendeten Skelettschlüssel zu schmieden. Bringt den unvollendeten Skelettschlüssel dann zum Alchimisten Arbington an der Chillwindspitze in den Westlichen Pestländern.",
    [5802] = "Bringt die Skelettschlüsselform und 2 Barren Thorium zur Spitze des Feuerfedergrats im Un'Goro Krater. Benutzt die Skelettschlüsselform am Lavasee, um den unvollendeten Skelettschlüssel zu schmieden. Bringt den unvollendeten Skelettschlüssel zu Apotheker Dithers im Bollwerk, Westliche Pestländer.",
    [5803] = "Zerstört Araj den Beschwörer und bringt Arajs Skarabäus zum Alchimisten Arbington an der Chillwindspitze in den westlichen Pestländern.",
    [5804] = "Vernichtet Araj den Beschwörer und bringt Arajs Skarabäus zum Apotheker Dithers im Bollwerk, in den westlichen Pestländern.",
    [5821] = "Bringt Gizeltons Karawane am Dorf der Kolkarzentauren vorbei. Sprecht in Scrabblescrews Lager mit Smeed, um Eure Belohnung zu erhalten.",
    [5845] = "Reist nach Northdale im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.",
    [5846] = "Begebt Euch zur Insel Caer Darrow im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte.",
    [5848] = "Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der Scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind. Bringt das Gemälde zu Tirion Fordring.",
    [5861] = "Begebt Euch zu Uthers Grabmal in den Südlichen Pestländern. Zeigt Myranda der Vettel Tirions Geschenk.",
    [5862] = "Sprecht mit Myranda, um die scharlachrote Illusion zu erhalten. Begebt Euch nach Hearthglen, während Ihr unter dem Einfluss der scharlachroten Illusion steht, und übergebt dem Hochlord Taelan Fordring Tirions Geschenk. Hearthglen liegt im Norden, Taelan dürfte sich in der Burg Mardenholde aufhalten.",
    [5863] = "Andi Lynn in Gadgetzan möchte, dass Ihr das Truppenlager der Dünenbrecher vernichtet, indem Ihr 10 Schläger der Dünenbrecher 10 Vollstrecker der Dünenbrecher sowie Gor'marok den Verheerer tötet.",
    [5881] = "Maggran möchte, dass Ihr Grish Longrunner am großen Aufzug im Brachland einen Brief zustellt.",
    [5892] = "Bringt 10 Irondeep-Vorräte zum Rüstmeister der Allianz in Dun Baldar.",
    [5893] = "Bringt 10 Coldtooth-Vorräte zum Rüstmeister der Horde in die Burg Frostwolf.",
    [5901] = "Wendet den leeren Termitenkrug auf die Termitenhügel in den östlichen Pestländern an. Sobald Ihr 100 Pestland-Termiten gesammelt habt, kehrt zu Mickey Levine am Bollwerk in Tirisfal zurück.",
    [5902] = "Sucht Euch einen geeigneten Ort in der Mitte des Northridge-Sägewerks in den Westlichen Pestländern, um das Fass mit den Pestland-Termiten abzustellen.",
    [5903] = "Wendet den leeren Termitenkrug auf die Termitenhügel in den Östlichen Pestländern an. Sobald Ihr 100 Pestland-Termiten gesammelt habt, kehrt zu Nathaniel Dumah am Chillwindposten in den Westlichen Pestländern zurück.",
    [5904] = "Sucht Euch einen geeigneten Ort in der Mitte des Northridge-Sägewerks in den Westlichen Pestländern, um das Fass mit den Pestland-Termiten abzustellen.",
    [5921] = "Benutzt den Zauber 'Teleportation: Moonglade', um nach Moonglade zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Starblaze in Nighthaven.",
    [5922] = "Benutzt den Zauber 'Teleportation: Moonglade', um nach Moonglade zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Starblaze in Nighthaven.",
    [5923] = "Sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius in Darnassus.",
    [5924] = "Sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius in Darnassus.",
    [5925] = "Sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius in Darnassus.",
    [5926] = "Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.",
    [5927] = "Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.",
    [5928] = "Sprecht mit Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.",
    [5929] = "Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.",
    [5930] = "Sucht den großen Bärengeist im nordwestlichen Moonglade auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Starblaze nach Nighthaven in Moonglade zurück.",
    [5931] = "Kehrt nach Darnassus zurück und sprecht mit Mathrengyl Bearwalker in der Enklave von Cenarius.",
    [5932] = "Kehrt nach Thunder Bluff zurück und sprecht mit Turak Runetotem auf der Anhöhe der Ältesten.",
    [5941] = "Bringt das Reliktbündel zu Chromie nach Andorhal.",
    [5942] = "Bringt Josephs Schlüssel zu Josephs Truhe.",
    [5943] = "Geleitet Gizeltons Karawane durch Mannorocs Koven. Sprecht in Scrabblescrews Lager mit Smeed, um Eure Belohnung zu erhalten.",
    [5944] = "Geleitet Taelan Fordring aus Hearthglen hinaus.",
    [5961] = "Sprecht mit Nathanos Blightcaller in den Östlichen Pestländern. Es heißt, dass er sich in Marris Siedlung niedergelassen hätte.",
    [5981] = "Rivern Frostwind möchte, dass Ihr 4 Frosthagelriesen und 4 Frosthagelbewahrer besiegt.",
    [6001] = "Benutzt den Mondstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt. Sprecht mit Mathrengyl Bearwalker in Darnassus, wenn Ihr fertig seid.",
    [6002] = "Benutzt den Lunarstaub des Cenarius mit dem Moonkinstein, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt. Sprecht mit Turak Runetotem in Thunder Bluff, wenn Ihr fertig seid.",
    [6004] = "Tötet 2 scharlachrote Sanitäter, 2 scharlachrote Jäger, 2 scharlachrote Magi und 2 scharlachrote Ritter, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt.",
    [6021] = "Bringt Zaeldarrs Kopf zu Verwalter Alen in der Kapelle des hoffnungsvollen Lichts.",
    [6022] = "Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis.",
    [6023] = "Besiegt Jägerin Radley und Chevalier Durgen, bevor Ihr zu Kirsta Deepshadow in den Westlichen Pestländern zurückkehrt.",
    [6024] = "Tötet Spitzel Hameya. Benutzt seinen Schlüssel bei dem Erdhaufen hinter dem Tiefgewölbe.",
    [6025] = "Geht nach Hearthglen, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Deepshadow in den Westlichen Pestländern zurück.",
    [6026] = "Smokey LaRue möchte, dass Ihr 2 Thoriumbarren, 1 Goldrute, 8 hochexplosive Bomben und 8 instabile Auslöser beschafft. Für diese Gegenstände müsst Ihr einen Schmied und einen Ingenieur finden.",
    [6027] = "Beschafft das 'Buch der Uralten' und kehrt zu Azore Aldamort im Turm von Ethel Rethor zurück.",
    [6028] = "Bringt den Everlook-Bericht zu Argentumoffizier Pureheart im Chillwind-Lager in den westlichen Pestländern.",
    [6029] = "Bringt den Everlook-Bericht zu Argentumoffizier Garush im Bollwerk in den Westlichen Pestländern.",
    [6030] = "Bringt das Buch 'Studien zur Geistersuche' zu Fürst Nicholas Zverenhoff in der Kapelle des hoffnungsvollen Lichts in den Östlichen Pestländern.",
    [6031] = "Bringt 30 Runenstoff zu Meilosh in der Holzschlundfeste.",
    [6032] = "Bringt 2 Mondstoff zu Meilosh in der Holzschlundfeste.",
    [6041] = "Reist in den Pestwald, nordwestlich der Hoffnung des Lichts. Zerstört 8 Geißelbauwerke, indem Ihr Smokeys spezielles Präparat am Mal der Zerstörung in jedem Bauwerk benutzt. Smokey hat die Ziggurats und Schlachthäuser markieren lassen. Wenn ihr die Bombe gelegt habt, dann verlasst das Bauwerk und staunt über Euer Geschick. Übrigens, Smokeys spezielles Präparat ist recht ... instabil.",
    [6042] = "Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Blightcaller zurück, wenn Ihr fertig seid.",
    [6061] = "Benutzt die Zähmrute, um einen ausgewachsenen Ebenenschreiter zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.",
    [6062] = "Benutzt die Zähmrute, um einen scheckigen Terroreber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.",
    [6063] = "Benutzt die Zähmrute, um einen Waldweberlauerer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.",
    [6064] = "Benutzt die Zähmrute, um einen großen Klippeneber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildheart in Kharanos.",
    [6065] = "Sprecht mit Yaw Sharpmane in Bloodhoof.",
    [6066] = "Sprecht mit Yaw Sharpmane in Bloodhoof.",
    [6067] = "Sprecht mit Yaw Sharpmane in Bloodhoof.",
    [6068] = "Sprecht mit Thotar in Klingenhügel.",
    [6069] = "Sprecht mit Thotar in Klingenhügel.",
    [6070] = "Sprecht mit Thotar in Klingenhügel.",
    [6071] = "Sprecht mit Dazalar in Dolanaar.",
    [6073] = "Sprecht mit Dazalar in Dolanaar.",
    [6074] = "Sprecht mit Grif Wildheart in Kharanos.",
    [6075] = "Sprecht mit Grif Wildheart in Kharanos.",
    [6076] = "Sprecht mit Grif Wildheart in Kharanos.",
    [6081] = "Sprecht mit Ormak Grimshot in Orgrimmar.",
    [6082] = "Benutzt die Zähmrute, um einen gepanzerten Skorpid zu zähmen. Übt Eure Fertigkeiten und kehrt zu Thotar in Klingenhügel zurück.",
    [6083] = "Benutzt die Zähmrute, um einen Brandungskriecher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.",
    [6084] = "Benutzt die Zähmrute, um einen Schneeleoparden zu zähmen. Übt Eure Fertigkeiten und kehrt dann zu Grif Wildheart in Kharanos zurück.",
    [6085] = "Benutzt die Zähmrute, um einen Eisklauenbären zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildheart in Kharanos.",
    [6086] = "Sprecht mit Belia Thundergranite in Ironforge.",
    [6087] = "Benutzt die Zähmrute, um einen Präriepirscher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.",
    [6088] = "Benutzt die Zähmrute, um einen Sturzflieger zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Sharpmane in Bloodhoof.",
    [6089] = "Sprecht mit Holt Thunderhorn auf der Anhöhe der Jäger in Thunder Bluff.",
    [6101] = "Benutzt die Zähmerrute, um einen pirschenden Nachtsäbler zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.",
    [6102] = "Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.",
    [6103] = "Sprecht mit Jocaste in der Enklave des Cenarius in Darnassus.",
    [6121] = "Reist nach Moonglade und sprecht mit Dendrite Starblaze im Dorf Nighthaven.",
    [6122] = "Benutzt das leere Gefäß bei Cliffspring Falls und nehmt eine Wasserprobe vom Höhleneingang bei den Wasserfällen. Bringt das gefüllte Gefäß von Cliffspring Falls zu Alanndarian Nightsong nach Auberdine in Dunkelküste.",
    [6123] = "Bringt 5 Erdwurzeln und 12 Lunarfungi zu Alanndarian Nightsong in Auberdine, damit sie eine Heilsalbe machen kann.",
    [6124] = "Benutzt die Tier-Heilsalbe bei 10 kranken Wildtieren rund um Dunkelküste. Das müsste sie heilen. Es wurde berichtet, dass krankes Wild südlich des Cliffspring, im Norden von Auberdine und bis hinunter in die südlichen Regionen von Dunkelküste, wo Ashenvale beginnt, aufgetaucht ist.",
    [6125] = "Kehrt zu Mathrengyl Bearwalker in der Enklave des Cenarius in Darnassus zurück.",
    [6126] = "Reist nach Moonglade und sprecht mit Dendrite Starblaze im Dorf Nighthaven.",
    [6127] = "Benutzt die leere Glutnebelgipfelprobe beim Glutnebelgipfel und nehmt eine Wasserprobe vom Teich auf der Spitze des Gipfels. Bringt das gefüllte Behältnis vom Glutnebelgipfel zu Tonga Runetotem in Crossroads im Brachland.",
    [6128] = "Bringt 5 Erdwurzeln und 5 Kodohörner zu Tonga Runetotem in Crossroads, damit er eine Heilsalbe machen kann.",
    [6129] = "Benutzt die heilende Tiersalbe bei 10 kränklichen Gazellen im nördlichen Teil des Brachlandes. Das müsste sie heilen. Kränkliche Gazellen wurden überall nördlich der Ost-West-Straße durch Crossroads gesehen.",
    [6130] = "Kehrt zu Turak Runetotem auf der Anhöhe der Ältesten in Thunder Bluff zurück.",
    [6132] = "Eskortiert Melizza Brimbuzzle und sprecht anschließend mit Hornizz Brimbuzzle beim Kodofriedhdof Desolace.",
    [6133] = "Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Quel'Thalas-Registratur zurück. Der Gegenstand befindet sich irgendwo in der Quel'Lithien-Lodge. Außerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten.",
    [6134] = "Bringt 8 Einheiten Geisterplasma und die Kiste mit den Geistermagneten zu Hornizz Brimbuzzle in Desolace.",
    [6135] = "Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Blightcaller. Man sagt, dass Dämmerschwinge nördlich von hier durch das Land streift.",
    [6136] = "Sucht in den nördlichen Wüsten der Östlichen Pestländer nach Blutschlinger und vernichtet ihn. Kehrt zu Nathanos Blightcaller zurück, sobald Ihr diese Mission erledigt habt.",
    [6141] = "Sprecht mit Bruder Anton in Desolace.",
    [6142] = "Sucht 10 Teile Fleisch der weichschaligen Muschel und bringt sie zu Mai'Lahii im Dorf Shadowprey.",
    [6143] = "Tötet 7 Myrmidonen der Zackenkämme, 7 Naga der Zackenkämme und 5 Zauberhexerinnen der Zackenkämme, dann sprecht in Desolace mit Drulzegar in Shadowprey.",
    [6144] = "Reist in die Undercity und sprecht mit Varimathras.",
    [6145] = "Kehrt in die östlichen Pestländer zurück und spürt den Purpurroten Kurier auf. Tötet den Kurier und schnappt Euch den Befehl des obersten Kreuzzüglers. Bringt den Befehl zu Nathanos Blightcaller und wartet auf weitere Anweisungen.",
    [6146] = "Reist nach Tyrs Hand, südöstlich der Siedlung Marris. Dort angekommen beißt in den faulen Apfel. In der Verkleidung des Scharlachroten Kreuzzugs überbringt Ihr Lord Valdelmar den Befehl des obersten Kreuzzüglers.",
    [6147] = "Kehrt mit der neuen Information zu Nathanos Blightcaller zurück.",
    [6148] = "Der Scharlachrote Kreuzzug ist unterwegs. Irgendwo auf der Straße von Tyrs Hand nach Stratholme findet Ihr das Orakel Demetria und ihr Gefolge. Jagt sie und tötet sie. Kehrt zu Nathanos Blightcaller zurück, wenn Ihr erfolgreich wart.",
    [6161] = "Sucht Rackmores Silberschlüssel. Sucht Rackmores Goldschlüssel. Sucht und öffnet Rackmores Truhe.",
    [6162] = "Tötet Oberanführer Ror und bringt seine Klaue zu Dreka'Sur beim Blutgiftposten im Teufelswald.",
    [6163] = "Reist nach Stratholme und tötet Ramstein den Würger. Bringt seinen Kopf als Souvenir zu Nathanos.",
    [6164] = "Bringt Augustus' Quittungsbuch zu Augustus dem Meschuggenen im Schreckenstal.",
    [6181] = "Bringt Lewis' Notiz zu Thor dem Greifenmeister.",
    [6182] = "Sprecht mit Meister Mathias Shaw in der Altstadt von Stormwind. Er wohnt in der Kaserne.",
    [6183] = "Sprecht wieder mit Mathias Shaw, wenn Ihr seine Aufgabe annehmen wollt.",
    [6184] = "Reist zur Chillwindspitze in den Westlichen Pestländern und trefft Euren Kontaktmann Flint Shadowmore.",
    [6185] = "Sucht in den östlichen Pestländern nach Hinweisen auf den 'Blightcaller' und die vermissten SI:7-Agenten. Wenn Ihr SI:7-Insignien findet, bringt sie zu Flint Shadowmore an der Chillwindspitze.",
    [6186] = "Kehrt nach Stormwind zurück und informiert Hochlord Bolvar Fordragon über das Schicksal von Nathanos Marris.",
    [6187] = "Stellt eine Armee auf und reist zu den östlichen Pestländern. Beginnt einen gnadenlosen Angriff auf Nathanos Blightcaller und jeden Abschaum der Horde, der ihn beschützen mag. Bewahrt einen klaren Kopf, <name>. Die Horde wird den Waldläuferlord mit dem Leben verteidigen.",
    [6261] = "Bringt Osrics Kiste zu Dungar Longdrink dem Greifenmeister.",
    [6281] = "Bucht einen Greifenritt bei Greifenmeister Thor, dann bringt Lewis' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in Stormwind.",
    [6282] = "Maggran Earthbinder in Sonnenfels möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt.",
    [6283] = "Maggran in Sonnenfels möchte, dass Ihr die Zerfetzerin der Blutfurien beseitigt und ihre sterblichen Überreste als Beweis für Eure Tat mitbringt.",
    [6284] = "Tötet Besseleth und bringt Besseleths Fangzahn zu Maggran in Sonnenfels.",
    [6285] = "Bucht einen Greifenritt zur Späherkuppe bei Greifenmeister Dungar Longdrink, dann bringt Osrics Kiste zu Lewis an der Späherkuppe.",
    [6301] = "Tammra Windfield in Sonnenfels möchte, dass Ihr 10 Gaeasamenkörner sammelt.",
    [6321] = "Bringt Podrigs Liste zu Karos Razok.",
    [6322] = "Bringt Gordons Kiste zu Michael Garret.",
    [6323] = "Bucht einen Fledermausritt zur Undercity bei Fledermausmeister Karos Razok und bringt dann Podrigs Anforderungsliste zu Gordon Wendham in Undercity.",
    [6324] = "Bucht einen Fledermausritt zum Grabmal bei Fledermausmeister Michael Garret und bringt dann Gordons Kiste zu Todeswache Podrig beim Grabmal.",
    [6341] = "Bringt Nessas Sammlung zu Vesprystus.",
    [6342] = "Bucht bei Hippogryphenmeister Vesprystus einen Hippogryphen nach Auberdine und bringt dann Nessas Sammlung zu Laird.",
    [6343] = "Bringt Lairds Antwort zu Nessa Shadowsong.",
    [6344] = "Sprecht mit Nessa Shadowsong.",
    [6361] = "Bringt das Bündel Bälge zu Windreitermeister Devrak in Crossroads.",
    [6362] = "Bucht einen Windreiter nach Thunder Bluff bei Windreitermeister Devrak und bringt dann das Bündel Bälge zu Ahanu in Thunder Bluff.",
    [6363] = "Bringt Ahanus Lederwaren zu Tal in Thunder Bluff.",
    [6364] = "Bucht einen Windreiter nach Crossroads bei Windreitermeister Tal und bringt dann Ahanus Lederwaren zu Jahan Hawkwing.",
    [6365] = "Bringt Zarghs Fleisch zu Devrak in Crossroads.",
    [6381] = "Pflanzt 10 Gaeasamenkörner in Gaeaerdhügel und sprecht dann mit Tammra in Sonnenfels.",
    [6382] = "Sprecht mit Seneni Thunderheart im Splintertreeposten in Ashenvale.",
    [6384] = "Bucht einen Windreiter nach Orgrimmar bei Windreitermeister Devrak und bringt dann Zarghs Fleisch zu Gryshka in Orgrimmar.",
    [6385] = "Bringt Gryshkas Brief zu Doras in Orgrimmar.",
    [6386] = "Bucht einen Windreiter nach Crossroads bei Windreitermeister Doras und bringt dann Gryshkas Brief zu Zargh in Crossroads.",
    [6387] = "Bringt Brocks Liste zu Thorgrum Borrelson in Thelsamar.",
    [6388] = "Bringt die Ehrenhacken zu Gryth Thurden in Ironforge.",
    [6389] = "Befreit die Pestländer-Termiten im Sägewerk von Northridge, dann kehrt mit dem Fass Pestländer-Termiten zu Nathaniel Dumah im Chillwind-Posten in den westlichen Pestländern zurück.",
    [6390] = "Befreit die Pestländer-Termiten im Sägewerk von Northridge, dann kehrt mit dem Fass Pestländer-Termiten zu Mickey Levine im Bollwerk in Tirisfal zurück.",
    [6391] = "Bucht einen Greifen nach Ironforge von Greifenmeister Thorgrum Borrelson, dann bringt Brocks Liste zu Golnir Bouldertoe in Ironforge.",
    [6392] = "Bucht einen Greifen nach Thelsamar bei Greifenmeister Gryth Thurden, dann bringt die Ehrenhacken zu Brock Stoneseeker in Thelsamar.",
    [6393] = "Bringt 10 Pyrophore zu Tsunaman in Sonnenfels.",
    [6394] = "Bringt Thazz'rils Hacke zu Großknecht Thazz'ril.",
    [6395] = "Bringt Samuel Fipps' sterbliche Überreste zu Marlas Grab und kehrt dann zu Novize Elreth zurück.",
    [6401] = "Teilt Tammra Windfield, die in Sonnenfels lebt, die gute Nachricht mit.",
    [6402] = "Reist nach Stormwind und begebt Euch zu den Stadttoren. Sprecht mit Knappe Rowe, damit er Marshal Windsor über Eure Ankunft informiert.",
    [6403] = "Folgt Reginald Windsor durch Stormwind. Schützt ihn vor Gefahren! Sprecht mit Knappe Rowe, wenn Ihr Reginald Windsor nochmal kontaktieren müsst.",
    [6421] = "Erkundet die Tiefen der Höhle in der Steinschlagklamm und bringt Mor'rogal in Sonnenfels 10 Resonitkristalle, damit er sie untersuchen kann.",
    [6441] = "Sammelt für Pixel im Splintertreeposten 16 Satyrhörner.",
    [6442] = "Bringt Marukai am Zoramstrand 20 Köpfe von Rächerflossen.",
    [6461] = "Xen'zilla am Malaka'jin möchte, dass Ihr 10 Kluftmooskrabbler und 7 Kluftmoosgiftspucker tötet.",
    [6462] = "Bringt Mitsuwa im Zoram'gar-Außenposten 8 Troll-Glücksbringer.",
    [6481] = "Öffnet das Resonitfässlein mit dem verzauberten Resonitkristall und tötet Goggeroc. Kehrt mit der Vollzugsmeldung und dem verzauberten Resonitkristall zu Mor'rogal zurück.",
    [6482] = "Begleitet Ruul und sprecht dann mit Yama Snowhoof im Splintertreeposten.",
    [6501] = "Ihr müsst die Welt nach jemandem absuchen, der fähig ist, die Macht des Fragments des Großdrachenauges wieder herzustellen. Die einzige Information, die Ihr über ein solches Wesen besitzt ist, dass es existiert.",
    [6502] = "Ihr müsst das Blut des schwarzen Großdrachen-Helden von General Drakkisath bekommen. Ihr findet Drakkisath in seinem Thronsaal hinter den Hallen des Aufstiegs auf der Blackrockspitze.",
    [6503] = "Tötet 9 Kundschafter von Ashenvale und kehrt dann zu Kuray'bin im Splintertreeaußenposten zurück.",
    [6504] = "Findet die 12 fehlenden Seiten der Schredderanleitung und fügt sie zu den Kapiteln 1, 2 und 3 zusammen.",
    [6521] = "Bringt den Kopf von Botschafter Malcin zu Varimathras nach Undercity.",
    [6522] = "Bringt die kleine Rolle zu Varimathras nach Undercity.",
    [6523] = "Begleitet Kaya Flathoof zum Camp Aparaje und kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück.",
    [6541] = "Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak.",
    [6542] = "Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak.",
    [6543] = "Bringt die Warsongberichte dem Warsongspäher, dem Warsongläufer und der Warsongvorhut. Meldet die Neuigkeiten, die Ihr von ihnen erfahrt, Kadrak im nördlichen Wachturm des Brachlands.",
    [6544] = "Eskortiert Torek bei seinem Angriff auf den Außenposten der Silverwing und Duriel Moonfire. Erstattet dann Ertog Ragetusk im Splintertreeposten Bericht.",
    [6548] = "Tötet 8 Grobiane der Grimmtotem und 6 Söldner der Grimmtotem. Kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück.",
    [6561] = "Bringt den Kopf des Twilight-Lords Kelris zu Bashana Runetotem in Thunder Bluff.",
    [6562] = "Sprecht in Ashenvale mit Je'neu Sancrea.",
    [6563] = "Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea nach Ashenvale.",
    [6564] = "Bringt die durchfeuchtete Notiz zu Je'neu Sancrea nach Ashenvale.",
    [6565] = "Tötet Lorgus Jett in der Blackfathom-Tiefe und kehrt dann zu Je'neu Sancrea nach Ashenvale zurück.",
    [6566] = "Hört Thrall zu.",
    [6567] = "Sucht Rexxar auf. Der Kriegshäuptling hat Euch erklärt, wo Ihr ihn finden könnt. Sucht die Wege von Desolace zwischen dem Steinkrallengebirge und Feralas ab.",
    [6568] = "Überbringt Myranda der Vettel in den westlichen Pestländern Rexxars Nachricht.",
    [6569] = "Reist zur Blackrockspitze und sammelt 20 schwarze Drachenbrutaugen. Kehrt zu Myranda der Vettel zurück, sobald Ihr die Aufgabe erfüllt habt.",
    [6570] = "Reist zum Drachensumpf in den Marschen von Dustwallow und begebt Euch in Aschenschwinges Bau. Sobald Ihr darin seid, tragt das Amulett der drachischen Subversion und sprecht mit Aschenschwinge.",
    [6571] = "Tragt den Warsongnachschub zusammen: Warsongsägeblätter, Holzfäller-Seil, Warsongöl und die Warsongaxtlieferung für Locke Okarr im Splintertreeposten.",
    [6582] = "Ihr müsst Scryer, den Champion der blauen Großdrachen, finden und ihn töten. Schlagt seinem Kadaver den Schädel ab und bringt ihn zu Aschenschwinge. Ihr wisst, dass Scryer in Winterspring zu finden ist.",
    [6583] = "Vernichtet den Drachenchampion des grünen Drachenschwarms, Somnus. Nehmt seinen Schädel und bringt ihn zu Aschenschwinge zurück.",
    [6584] = "Chronalis, ein Kind Nozdormus, bewacht die Höhlen der Zeit in der Tanariswüste. Vernichtet ihn und bringt seinen Schädel zu Aschenschwinge.",
    [6585] = "Begebt Euch nach Grim Batol und spürt Axtroz auf, den Drachenchampion des Roten Drachenschwarms. Vernichtet ihn und nehmt seinen Schädel. Bringt den Schädel zu Aschenschwinge zurück.",
    [6601] = "Mir scheint, als sei die Charade jetzt vorüber. Ihr wisst, dass das Amulett der drachischen Unterwanderung, das Myranda die Vettel für Euch erschuf, auf der Blackrockspitze nicht funktioniert. Vielleicht solltet Ihr Rexxar aufsuchen und ihm Eure Notlage erklären. Zeigt ihm das glanzlose Drachenfeueramulett. Er wird hoffentlich wissen, was als Nächstes zu tun ist.",
    [6602] = "Begebt Euch zur Blackrockspitze und tötet General Drakkisath. Sammelt sein Blut und bringt es zu Rexxar.",
    [6603] = "Findet Donova Snowden bei den Thermalquellen in Winterspring.",
    [6604] = "Sprecht mit Jaron Stoneshaper in Starfall.",
    [6605] = "Sprecht im Teufelswald mit Winna Hazzard.",
    [6607] = "Nat Pagle möchte, dass Ihr folgende Fische fangt: Nebelschilf-Mahi Mahi vom Nebelschilfstrand in den Sümpfen des Elends. Einen Sar'theris-Barsch vom Sar'theris-Strand in Desolace. Feralas-Ahi aus dem Verdantis in Feralas. Blauwimpel von der ungezähmten Küste im Schlingendorntal. Kehrt zu Nat Pagle zurück, wenn Ihr alle an Land gezogen habt!",
    [6608] = "Ihr nehmt an, dass Lumak Euch zu erklären versucht, dass er nicht mehr tun kann, um Eure Angelfertigkeit zu verbessern. Ihr solltet seinen Freund aufsuchen, diesen Nat Pagle, einen Menschen, der auf einer der Inseln südlich von Theramore (jedenfalls glaubt Ihr, dass Lumak das gemeint hat) auf Fischfang geht.",
    [6609] = "Reist nach Kalimdor zur Küstenstadt Theramore. Dort müsst Ihr nach einer Insel suchen, die südlich der Hauptstadt liegt. Nat Pagle erwartet Euch!",
    [6610] = "Dirge Quikcleave möchte, dass Ihr folgende Dinge besorgt: 12 Rieseneier. Ihr findet sie bei den Rocs, die Tanaris durchstreifen, oder anderen Großvogelarten. 10 Stück scharfes Muschelfleisch. Die findet Ihr natürlich in Muscheln! 20 Stück Alteraclochkäse. Begebt Euch zu einer Käserei! Sammelt all diese Gegenstände und kehrt dann zu Dirge zurück.",
    [6611] = "Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Quikcleave über den Ausbau Eurer Kochkarriere.",
    [6612] = "Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Quikcleave über den Ausbau Eurer Kochkarriere.",
    [6621] = "Platziert Karangs Banner auf dem Totemhügel der Fäulnisklauen. Die Furbolgs dürfen das Banner nicht zerstören. Besiegt Häuptling Murgut und bringt Murguts Totem zu Karang Amakkar in Zoram'gar.",
    [6622] = "Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen. Denkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt.",
    [6623] = "Reist nach Hammerfall im Arathihochland und sprecht mit Doktor Gregory Victor darüber, dass Ihr auch ein Traumachirurg der Horde werden wollt.",
    [6624] = "Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen. Denkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt.",
    [6625] = "Reist nach Theramore in den Marschen von Dustwallow und sprecht mit Doktor Gustaf van Howzen darüber, dass Ihr auch ein Traumachirurg der Allianz werden wollt.",
    [6626] = "Tötet 8 Schlachtwachen von Razorfen, 8 Dornenwirker von Razorfen und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Moonsinger nahe dem Eingang zu den Hügeln von Razorfen zurück.",
    [6627] = "Beantwortet Braug Dimspirits Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch im Steinkrallengebirge sein, wenn Ihr bereit seid.",
    [6628] = "Beantwortet Parqual Fintallas' Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch in Undercity sein, wenn Ihr bereit seid.",
    [6629] = "Tötet Grundig Finsterwolke und 6 Schläger der Grimmtotem und kehrt dann zu Makaba Flathoof am südöstlichen Rand des Steinkrallengebirges zurück.",
    [6641] = "Beschützt Muglash, wenn er zu der Kohlenpfanne reist. Helft ihm, indem Ihr die Kohlenpfanne löscht, und beschützt ihn dann, während Ihr gegen die Naga kämpft. Wenn Ihr erfolgreich gewesen seid, kehrt zum Zoram'garposten zurück und informiert den Warsongläufer über den Tod von Vorsha der Peitscherin.",
    [6661] = "Fangt mit Hilfe der Rattenfängerflöte 5 Untergrundratten in der Tiefenbahn. Führt die Ratten zu Monty. Und vergesst nicht, die Flöte zurückzugeben, wenn Ihr fertig seid.",
    [6662] = "Bringt den Karton mit eigenartigem Fleisch zu Nipsy im Tiefenbahndepot von Stormwind.",
    [6681] = "Bringt das Ravenholdt-Siegel zu Fahrad im Ravenholdt-Anwesen, das versteckt in den Hügeln von Hillsbrad liegt. Unterwegs wird man Eure Schlauheit testen. Seid darauf gefasst.",
    [6721] = "Sprecht mit Dazalar in Dolanaar.",
    [6722] = "Sprecht mit Dazalar in Dolanaar.",
    [6761] = "Sprecht mit Mathrengyl Bearwalker in der Enklave des Cenarius von Darnassus.",
    [6762] = "Sprecht mit Rabine Saturna im Dorf Nighthaven in Moonglade. Moonglade liegt zwischen dem Teufelswald und Winterspring, und Ihr erreicht es über den Pfad, der aus der Holzschlundfeste herausführt.",
    [6804] = "Wendet den Aspekt von Neptulon auf die vergifteten Elementare der östlichen Pestländer an. Bringt 12 disharmonische Armschienen, sowie den Aspekt von Neptulon zu Fürst Hydraxis in Azshara.",
    [6805] = "Tötet 15 Staubstürmer und 15 Wüstenrumpler und kehrt dann zu Fürst Hydraxis in Azshara zurück.",
    [6821] = "Bringt das Auge des Glutsehers zu Fürst Hydraxis in Azshara.",
    [6822] = "Tötet 1 Feuerlord, 1 geschmolzenen Riesen, 1 uralten Kernhund sowie 1 Lavawoger und kehrt dann zu Fürst Hydraxis in Azshara zurück.",
    [6823] = "Verdient Euch eine geehrte Fraktion bei den hydraxianischen Wasserlords und sprecht dann mit Fürst Hydraxis in Azshara.",
    [6824] = "Bringt die Hände von Lucifron, Sulfuron, Gehennas und Shazzrah zu Fürst Hydraxis in Azshara.",
    [6844] = "Bringt das verkrustete Silithidenobjekt zu Umber, dem Archivar des Zirkels des Cenarius, ins Dorf Nighthaven in Moonglade.",
    [6845] = "Sprecht mit Rabine Saturna im Dorf Nighthaven in Moonglade.",
    [6921] = "Bringt den Fathom-Kern zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale.",
    [6922] = "Bringt die seltsame Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale.",
    [6981] = "Begebt Euch nach Ratchet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann. Liefert dann den Splitter ab, wie Ihr angewiesen wurdet.",
    [6982] = "Bringt 5 Coldtooth-Vorräte zum Rüstmeister der Allianz in Dun Baldar.",
    [6985] = "Bringt 10 Irondeep-Vorräte zum Rüstmeister der Horde in die Burg Frostwolf.",
    [7001] = "Findet einen Frostwolf im Alteractal. Wenn Ihr Euch in der Nähe eines Frostwolfs befindet, benutzt den Frostwolfmaulkorb um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Frostwolf bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden.",
    [7003] = "Benutzt Zorbins Super-Schrumpfer, um jegliche Art von Riesen in Feralas in eine handlichere Form zu schrumpfen. Bringt Zorbin Fandazzle 15 Schrumpf-Überreste von diesen Riesen. Ihr findet ihn bei den Docks, an der vergessenen Küste in Feralas.",
    [7027] = "Findet einen Alteracwidder im Alteractal. Wenn Ihr Euch in der Nähe eines Alteracwidders befindet, benutzt das Stormpike Zähmungshalsband um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Alteracwidder bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden.",
    [7028] = "Sammelt 25 theradrische Kristallschnitzereien für Willow in Desolace.",
    [7029] = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon. Benutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxious-Spross herausgezwungen wird. Heilt 8 Pflanzen, indem Ihr diesen Noxxious-Spross tötet und kehrt dann zu Vark Battlescar in Shadowprey zurück.",
    [7041] = "Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon. Benutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxious-Spross herausgezwungen wird. Heilt 8 Pflanzen, indem Ihr diesen Noxxious-Spross tötet und kehrt dann zu Talendria an der Nijelspitze zurück.",
    [7044] = "Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten. Findet einen Weg, um mit Celebras zu sprechen.",
    [7046] = "Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt. Sprecht mit ihm, nachdem das Ritual vollendet ist.",
    [7064] = "Tötet Prinzessin Theradras und kehrt zu Selendra in der Nähe von Shadowprey in Desolace zurück.",
    [7065] = "Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück.",
    [7066] = "Sucht Remulos in Moonglade auf und gebt ihm das Samenkorn des Lebens.",
    [7067] = "Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace.",
    [7068] = "Sammelt 10 Schattensplitter aus Maraudon und bringt sie zu Uthel'nay nach Orgrimmar.",
    [7070] = "Sammelt 10 Schattensplitter in Maraudon und bringt sie zu Erzmagier Tervosh in den Marschen von Dustwallow.",
    [7081] = "Erobert einen Friedhof und kehrt zu Sergeant Durgen Stormpike im Alteracgebirge zurück.",
    [7082] = "Erobert einen Friedhof und kehrt zu Corporal Teeka Bloodsnarl im Alteracgebirge zurück.",
    [7101] = "Erobert einen gegnerischen Turm und kehrt anschließend zu Corporal Teeka Bloodsnarl in Frostwolf zurück.",
    [7102] = "Zerstört das Banner im Inneren eines gegnerischen Bunkers oder Turms. Kehrt anschließend zu Sergeant Durgen Stormpike im Alteracgebirge zurück.",
    [7121] = "Sprecht mit dem Rüstmeister der Stormpike.",
    [7122] = "Erobert eine Mine, die die Stormpike noch nicht kontrollieren, und kehrt dann zu Sergeant Durgen Stormpike im Alteracgebirge zurück.",
    [7123] = "Sprecht mit dem Rüstmeister der Frostwolf.",
    [7124] = "Erobert eine Mine und kehrt zu Corporal Teeka Bloodsnarl im Alteracgebirge zurück.",
    [7141] = "Betretet das Alteractal, bezwingt den Hordegeneral Drek'thar und kehrt dann zu Ausgrabungsleiter Stonehewer im Alteracgebirge zurück.",
    [7142] = "Betretet das Alteractal und bezwingt den Zwergengeneral, Vanndar Stormpike. Kehrt anschließend zu Voggah Deathgrip im Alteracgebirge zurück.",
    [7161] = "Begebt euch in die Höhle der Wildpfoten südöstlich vom Hauptstützpunkt und findet das Banner der Frostwolf. Bringt anschließend Kriegsmeister Laggrond das Banner.",
    [7162] = "Begebt euch in die Icewinghöhle südwestlich von Dun Baldar und findet das Banner der Stormpike. Bringt anschließend Lieutenant Haggerdin im Alteracgebirge das Banner.",
    [7181] = "Tief in den Winteraxhöhlen versteckt sich Korrak der Blutrünstige. Den Legenden nach, wird der mächtige Anführer der Winteraxtrolle nur erscheinen, wenn 500 seiner Männer getötet wurden. Begebt Euch zu den Winteraxhöhlen und vernichtet alles was sich Euch in den Weg stellt, solange bis Korrak selbst auftaucht. Tötet Korrak und kehrt zu Kriegsmeister Laggrond zurück.",
    [7201] = "Begebt Euch in die Blackrocktiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hin gemurmelt hat.",
    [7202] = "Tief in den Winteraxhöhlen versteckt sich Korrak der Blutrünstige. Den Legenden nach, wird der mächtige Anführer der Winteraxtrolle nur erscheinen, wenn 500 seiner Männer getötet wurden. Begebt Euch zu den Winteraxhöhlen und vernichtet alles was sich Euch in den Weg stellt, solange bis Korrak selbst auftaucht. Tötet Korrak und kehrt zu Lieutenant Haggerdin zurück.",
    [7223] = "Bringt Murgot Deepforge in Dun Baldar 20 Rüstungsfetzen.",
    [7224] = "Bringt 20 Rüstungsfetzen zu Schmied Regzar in Frostwolf.",
    [7241] = "Reist ins Alteractal im Vorgebirge von Hillsbrad. Sucht dort Kriegsmeister Laggrond auf und beginnt Eure Karriere als Soldat der Frostwolf.",
    [7261] = "Reist ins Alteractal im Vorgebirge von Hillsbrad. Wenn Ihr dort angekommen seid, meldet Euch umgehend bei Leutnant Haggerdin. Für den Ruhm von Bronzebeard!",
    [7281] = "Begebt euch ins Gebiet der Stormpike und tötet Kommandant Karl Philips. Kehrt zu Kommandant Louis Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt.",
    [7282] = "Begebt euch ins Frostwolfgebiet und tötet Kommandant Louis Philips. Kehrt zu Kommandant Karl Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt.",
    [7301] = "Begebt Euch ins Frostwolf Territorium und sucht nach Schwadronskommandant Slidore, Schwadronskommandant Vipore und Schwadronskommandant Ichman. Meldet Euch bei Kommandant Duffy, sobald Ihr Eure Mission erfüllt habt.",
    [7302] = "Findet heraus was aus Schwadronskommandant Guse, Schwadronskommandant Jeztor, und Schwadronskommandant Mulverick geworden ist. Wenn Eure Mission erfüllt ist, kehrt zu Kommandant Mulfort zurück.",
    [7321] = "Bringt 10 Stücke Schildkrötenfleisch und einige feine Gewürze zu Christoph Jeffcoat in Tarrens Mühle.",
    [7361] = "Ihr wurdet beauftragt gegnerische Nachtelfenspieler im Alteractal zu töten. Tötet einen Nachtelfen und bringt einen abgeschlagenen Nachtelfenkopf zu Najak Hexxen in Burg Frostwolf.",
    [7362] = "Ihr wurdet beauftragt gegnerische Gnomspieler im Alteractal zu töten. Tötet einen Gnom und bringt ein Büschel Gnomhaar zu Ravak Grimmtotem in Burg Frostwolf.",
    [7363] = "Ihr wurdet beauftragt gegnerische Menschenspieler im Alteractal zu töten. Tötet einen Menschen und bringt dessen Knochensplitter zu Kommandant Louis Philips (er bewegt sich zwischen den Frontlinien und Burg Frostwolf hin und her). Die Heilung für die menschliche Existenz ist zum Greifen nahe!",
    [7366] = "Ihr wurdet beauftragt gegnerische Verlassenen-Spieler im Alteractal zu töten. Tötet einen Verlassenen und bringt dessen Herz zu Kommandant Karl Philips (er bewegt sich zwischen dem Sägewerk und der Mine hin und her).",
    [7381] = "Sollte Korrak der Blutrünstige wieder in den Winteraxhöhlen auftauchen, sucht ihn auf und tötet ihn. Bringt Korraks Schädel zu Kriegsmeister Laggrond auf Burg Frostwolf.",
    [7382] = "Sollte Korrak der Blutrünstige wieder in den Winteraxhöhlen auftauchen, sucht ihn auf und tötet ihn. Bringt Korraks Schädel zu Leutnant Haggerdin in Dun Baldar.",
    [7383] = "Füllt die Amethystphiole und bringt sie Corithras Moonrage in Dolanaar.",
    [7441] = "Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben. Kehrt mit dem Buch zu Az'Tordin, an Lariss' Pavillon in Feralas, zurück.",
    [7461] = "Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen. Betretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten. Kehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück.",
    [7463] = "Reist nach Düsterbruch in das Wucherborkenviertel und besiegt den Wasserelementar Hydrobrut. Kehrt anschließend mit der Hydrobrutessenz, zum Hüter des Wissens Lydros im Athenaeum zurück.",
    [7481] = "Sucht in Düsterbruch nach Telmius Dreamseeker. Meldet Euch anschließend bei Sage Korolusk in Camp Mojache.",
    [7482] = "Sucht in Düsterbruch nach Telmius Dreamseeker. Meldet Euch anschließend bei der Gelehrten Runethorn in Feathermoon.",
    [7483] = "Bringt ein Buchband der Schnelligkeit, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 2 mal das Blut von Helden, zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum der Schnelligkeit zu erhalten.",
    [7484] = "Bringt ein Buchband des Fokus, 1 makellosen schwarzen Diamanten, 4 große glänzende Splitter und 2 mal Schattenhaut, zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum des Fokus zu erhalten.",
    [7485] = "Bringt ein Buchband des Schutzes, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 1 ausgefranste Monstrositätenstickerei zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum des Schutzes zu erhalten.",
    [7486] = "Nehmt Eure Belohnung aus Hydraxis' Kasten.",
    [7488] = "Bringt Lethtendris' Netz zu Latronicus Moonspear in der Festung Feathermoon, in Feralas.",
    [7489] = "Bringt Lethtendris' Netz zu Talo Thornhoof im Camp Mojache in Feralas.",
    [7490] = "Bringt Onyxias Kopf zu Thrall in Orgrimmar.",
    [7491] = "Sucht Oberanführer Runthak im Tal der Stärke auf.",
    [7492] = "Sprecht mit Talo Thornhoof in Camp Mojache, in Feralas.",
    [7494] = "Sprecht mit Latronicus Moonspear in der Festung Feathermoon, in Feralas.",
    [7495] = "Bringt Onyxias Kopf zu Hochlord Bolvar Fordragon in Stormwind.",
    [7496] = "Sucht Major Mattingly im Tal der Helden auf.",
    [7498] = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.",
    [7499] = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.",
    [7500] = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.",
    [7501] = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.",
    [7502] = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.",
    [7503] = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.",
    [7504] = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.",
    [7505] = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.",
    [7506] = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.",
    [7507] = "Bringt Nostros Kompendium des Drachentötens zurück in das Athenaeum.",
    [7508] = "Bringt dem Hüter des Wissens Lydros, die stumpfe und glanzlose Elfenklinge.",
    [7509] = "Bringt Onyxia dazu, ihren Feueratem auf die noch unerhitzte Klinge zu benutzen. Sobald dies geschehen ist, hebt die erhitzte Klinge wieder auf. Doch seid gewarnt, die erhitzte Klinge wird nicht auf ewig erhitzt bleiben - behaltet also die Zeit im Auge. Zuletzt müsst Ihr das Biest töten und die uralte erhitzte Klinge in ihren Leib rammen. Kehrt anschließend zu mir zurück und Quel'Serrar wird Euer sein.",
    [7562] = "Sprecht mit Mor'zul Bloodbringer in der brennenden Steppe.",
    [7563] = "Mor'zul Bloodbringer in der brennenden Steppe möchte, dass Ihr ihm 30 Flaschen mit dem Blut der tobenden Bestien bringt.",
    [7564] = "Bringt den Behälter mit Blut zu Gorzeeki Wildeyes in der brennenden Steppe.",
    [7581] = "Reist nach Düsterbruch in Feralas und holt Euch das Blut von 15 Satyrn der Wildhufe, die im Wucherborkenviertel ansässig sind. Kehrt anschließend zu Daio in der faulenden Narbe zurück.",
    [7582] = "Reist in die flüsternde Schlucht in Winterspring und besorgt Euch 5 Tränen bei den Dämonen von Hederine, die in der Schlucht leben. Kehrt zu Daio in der faulenden Narbe zurück, sobald Ihr diese Aufgabe vollständig erledigt habt.",
    [7583] = "Wagt Euch in die faulende Narbe heraus und macht einen Kommandant der Verdammniswache ausfindig. Wendet das leuchtende Kristallgefängnis auf den Kommandanten der Verdammniswache an. Bereitet Euch auf eine heftige Serie von Attacken vor, da der Dämon alles gegen seine Gefangennahme unternehmen wird. Solltet Ihr erfolgreich sein, bringt die gefangene Verdammniswache zu Daio in der faulenden Narbe.",
    [7601] = "Sprecht mit Impsy im Teufelswald.",
    [7602] = "Impsy im Teufelswald möchte, dass Ihr ihm drei reine Teufelsessenzen aus drei bestimmten Gebieten besorgt. Die Satyrn der Legashi von Azshara bergen die Teufelsessenz ihrer Region. Die Legionäre von Jaedenar in Jaedenar bergen die Teufelsessenz ihrer Region. Die Wachposten der Teufelswache in den verwüsteten Landen bergen die Teufelsessenz ihrer Region. Findet die Teufelsessenzen und bringt sie zu Impsy im Teufelswald.",
    [7603] = "Sucht im Shattered Scar-Tal im Teufelswald nach den Überresten von Kroshius. Habt Ihr sie gefunden, so verwendet das Teufelsfeuer in deren Nähe und wartet dann auf Kroshius' Rückkehr. Tötet die Höllenbestie und entnehmt ihrem Körper den Höllenbestienkern. Bringt Kroshius' Höllenbestienkern zu Niby dem Allmächtigen im Teufelswald.",
    [7604] = "Bringt den Vertrag der Thoriumbruderschaft zu Lokhtos Darkbargainer, wenn Ihr die Pläne für das Sulfuron erhalten möchtet.",
    [7622] = "Rettet 50 Arbeiter bevor 15 getötet wurden. Sprecht mit Eris Havenfire, falls Ihr diesen Auftrag erfolgreich zu Ende bringen solltet. Konsultiert den Todesposten, um zu sehen wie viele Arbeiter bereits getötet wurden.",
    [7623] = "Erwerbt schattenhaftige Tränke von Gorzeeki in der brennenden Steppe. Benutzt die Tränke um durch Jaedenar zu reisen und sprecht mit Lord Banehollow.",
    [7624] = "Stellt Euch Ulathek und bringt das Herz des Verräters zu Lord Banehollow in Jaedenar.",
    [7625] = "Erwerbt xorothianischen Sternenstaub von Ur'dan. Bringt es anschließend Gorzeeki in der brennenden Steppe.",
    [7626] = "Bringt 10 Elixiere der Schattenmacht zu Gorzeeki Wildeyes in die brennende Steppe.",
    [7627] = "Bringt 6 große glänzende Splitter und 25 Stücke Dunkeleisenerz zu Gorzeeki Wildeyes in die brennende Steppe.",
    [7628] = "Bringt 35 Schuppen eines schwarzen Drachen zu Gorzeeki Wildeyes in der brennenden Steppe.",
    [7629] = "Bringt den Wichtel im Gefäß in das Alchimielabor in der Scholomance. Bringt nach der Herstellung des Pergaments, dass Gefäß zurück zu Gorzeeki Wildeyes.",
    [7630] = "Bringt 3 Arkanitbarren zu Gorzeeki in der brennenden Steppe.",
    [7631] = "Lest Morzuls Anweisungen. Beschwört ein xorothianisches Schreckensross, besiegt es und bindet seinen Geist an Euch.",
    [7632] = "Findet den Besitzer des uralten, versteinerten Blatts. Viel Glück, <Name>; die Welt ist groß.",
    [7634] = "Hastat der Uralte hat Euch um die Beschaffung einer Sehne eines ausgewachsenen, blauen Drachens gebeten. Solltet Ihr diese Sehne finden, kehrt zu Hastat im Teufelswald zurück.",
    [7635] = "Stoma der Uralte hat Euch um die Beschaffung einer Sehne eines ausgewachsenen, schwarzen Drachens gebeten. Solltet Ihr diese Sehne finden, kehrt zu Stoma im Teufelswald zurück.",
    [7636] = "Ihr müsst die vier dämonischen Verderber ausfindig machen und zerstören: Simone die Verführerin. Klinfran der Wahnsinnige. Solenor der Schlächter. Artorius der Verhängnisvolle. Vernichtet diese Kreaturen und kehrt zu Vartrus dem Uralten im Teufelswald zurück. Haltet Euch an die versteinerte Rinde in Eurem Inventar, um Hinweise zu ihren Aufenthaltsorten zu erhalten. Ihr MÜSST diese Aufgabe eigenständig erledigen.",
    [7637] = "Reist nach Ironforge und besorgt Euch Hohepriester Rohans Weihrauchschwenker. Eine Spende von 150 Gold wird erforderlich sein, um es zu bekommen.",
    [7638] = "Sprecht mit Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind.",
    [7639] = "Bringt den Weihrauchschwenker zu Lord Grayson Shadowbreaker in Stormwind zurück.",
    [7640] = "Vertreibt mit Hilfe des Weihrauchschwenkers die Geister im Schreckenstal. Vernichtet 25 Schreckenstalgeister und kehrt anschließend zu Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind zurück.",
    [7641] = "Sprecht mit Grimand Elmore im Zwergendistrikt von Stormwind.",
    [7642] = "Bringt 40 Lagen Runenstoff, 6 Arkanitbarren, 10 Artha's Tränen, 5 Phiolen heiliges Wasser aus Stratholme und 150 Gold zu Grimand Elmore im Zwergendistrikt von Stormwind.",
    [7643] = "Beschafft spezielles Pferdefutter mit dem man ein Geisterpferd füttern kann. Meredith Carlson in Southshore scheint dafür eine recht gute Quelle zu sein. Reist anschließend nach Düsterbruch in Feralas und tötet Tendris Wucherborke. Dies wird den uralten Pferdegeist befreien. Füttert den Geist zur Beruhigung mit dem speziellen Pferdefutter. Gebt dem Pferdegeist das Arkanitpferdegeschirr, um es segnen zu lassen.",
    [7644] = "Kehrt mit dem gesegneten Arkanitpferdegeschirr zu Lord Grayson Shadowbreaker in das Kathedralenviertel von Stormwind zurück.",
    [7645] = "Treibt 20 angereicherte Manakekse - die ausschlaggebende Zutat für die Herstellung von mit Mana angereichertem Pferdefutter - für Merideth Carlson aus Southshore in dem Vorgebirge von Hillsbrad auf. Die Argentumdämmerung ist als alleiniger Händler dieser Kekse bekannt. Zusätzlich müsst Ihr ihre Gefühle noch mit 50 Goldstücken besänftigen.",
    [7646] = "Bringt Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind einen Azerothianischen Diamanten und einen makellosen schwarzen Diamanten.",
    [7647] = "Benutzt das Orakel der Anrufung im Herzen des Kellergewölbes des großen Ossuariums, in Scholomance. Damit ruft Ihr die verfluchten Geister, über deren Schicksal Ihr richten müsst. Durch das besiegen der Geister wird der Todesritter Schattensichel beschworen. Besiegt ihn und holt Euch die verlorene Seele des gefallenen Streitrosses. Gebt die Seele des gefallenen Streitrosses und das gesegnete und verzauberte Pferdegeschirr Schattensichels gefallenem Streitross zurück.",
    [7648] = "Bringt das Arkanitpferdegeschirr zur Begutachtung zu Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind.",
    [7649] = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.",
    [7650] = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.",
    [7651] = "Bringt das Buch seinen rechtmäßigen Besitzern zurück.",
    [7667] = "Wenn Ihr Sagorne Crestrider im Tal der Weisheit von Orgrimmar helfen wollt, so bringt ihm einen azerothianischen und einen makellosen schwarzen Diamanten.",
    [7670] = "Sprecht mit Lord Grayson Shadowbreaker im Kathedralenviertel von Stormwind.",
    [7701] = "Tief in der Schlackengrube des Kessels in der sengenden Schlucht werdet Ihr den verräterischen Dunkeleisenzwerg, Aufseher Maltorius, finden. Tötet den Aufseher Maltorius und nehmt seinen Kopf an Euch. Bringt diesen zum Ausguck Captain Lolo Longstriker in der sengenden Schlucht für eine Belohnung.",
    [7703] = "Findet die Stulpen der Gordokmacht und bringt sie zu Captain Kromcrush in Düsterbruch. Kromcrush zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat.",
    [7721] = "Sammelt 10 Wasserelementarkerne von den Meereselementaren und Meeresschauern entlang der Vergessenen Küste von Feralas und bringt sie zurück zu Zorbin Fandazzle in der Nähe des dortigen Docks.",
    [7722] = "Irgendwo in der Schlackengrube des Kessels findet Ihr die geheimen Pläne des Feurigen Fluxus, die der Aufseher Maltorius stahl. Findet diese Pläne und bringt sie zurück zu Meisterschmied Burninate in der sengenden Schlucht.",
    [7723] = "Hansel Heavyhands möchte, dass Ihr 20 Schwere Kriegsgolems tötet. Die Schweren Kriegsgolems wandern in der Gegend um den Kessel in der sengenden Schlucht herum. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück.",
    [7724] = "Hansel Heavyhands möchte, dass Ihr 20 sengende Lavaspinnen in der sengenden Schlucht tötet. Die sengenden Lavaspinnen findet Ihr auf den Plateaus und in den Lavabecken der sengenden Schlucht. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück.",
    [7725] = "Benutzt Zorbins Super-Schrumpfer, um jegliche Art von Riesen in Feralas in eine handlichere Form zu schrumpfen. Bringt 10 Schrumpf-Überreste, die auf den kleineren handlicheren Riesen liegen zu Zorbin Fandazzle am Dock der Vergessenen Küste in Feralas.",
    [7726] = "Sammelt 6 Wasserelementarkerne von den Meereselementaren und Meeresschauern entlang der Vergessenen Küste von Feralas und bringt sie zurück zu Zorbin Fandazzle in der Nähe des dortigen Docks.",
    [7727] = "Hansel Heavyhands möchte, dass Ihr 20 Incendosaurier tötet. Die Incendosaurier haben sich in den Lavabecken der Schlackengrube eingenistet. Ihr findet die Schlackengrube im Kessel der segenden Schlucht. Sobald Ihr genug Incendosaurier getötet habt, kehrt zu Hansel Heavyhands in der sengenden Schlucht zurück.",
    [7728] = "Sucht die Schmiedewindform und das Ausguck-Handfernrohr. Bringt diese Gegenstände zu Zuchtmeister Scrange in der sengenden Schlucht. Die einzigen Informationen die Ihr habt sind: Die Schmiedewindform is ein SCHMIEDEwerkzeug welches von SCHMIEDEN verwendet wird und das Ausguck-Handfernrohr ist ein unverzichtbares Werkzeug für SPÄHPOSTEN.",
    [7729] = "Tötet 15 Zuchtmeister der Dunkeleisenzwerge und 15 Sklavenhändler der Dunkeleisenzwerge. Kehrt zu Zuchtmeister Scrange zurück, sobald Ihr die Aufgabe erfüllt habt.",
    [7730] = "Bringt Hadoken Swiftstrider im Camp Mojache in Feralas 20 Zukk'ashknochenpanzer.",
    [7731] = "Besiegt Zornstachel in der verwundenen Tiefe und bringt seine Drüsen zu Hadoken Swiftstrider im Camp Mojache in Feralas zurück.",
    [7732] = "Bringt den Bericht über die Zukk'ash aus Camp Mojache zu Zilzibin Drumlore. Er wohnt in der Gasse von Orgrimmar.",
    [7733] = "Bringt Pratt McGrubben in der Festung Feathermoon 10 Wutschrammyetibälge.",
    [7734] = "Bringt Jangdor Swiftstrider im Camp Mojache in Feralas 10 Wutschrammyetibälge.",
    [7735] = "Bringt Pratt McGrubben in der Festung Feathermoon den makellosen Yetibalg.",
    [7738] = "Bringt Jangdor Swiftstrider im Camp Mojache in Feralas den makellosen Yetibalg.",
    [7761] = "Das war ja vielleicht mal ein dummer Orc. Es sieht so aus, als müsstet Ihr dieses Brandzeichen finden, um an das Mal von Drakkisath zu gelangen. Damit sollte sich die Befehlskugel aktivieren lassen. Dem Brief zufolge, wird das Brandzeichen von General Drakkisath bewacht. Vielleicht solltet Ihr diesem Hinweis nachgehen.",
    [7781] = "Bringt Hochlord Bolvar Fordragon in Stormwind den Kopf von Nefarian.",
    [7782] = "Reist in nach Stormwind in das Tal der Helden und sprecht mit Feldmarschall Afrasiabi.",
    [7783] = "Bringt Thrall in Orgrimmar den Kopf von Nefarian.",
    [7784] = "Sprecht mit Hochfürst Saurfang in Orgrimmar. Er wartet im Tal der Stärke auf Euch.",
    [7785] = "Untersucht das Gefäß der Wiedergeburt und bringt es zu Hochlord Demitrian.",
    [7786] = "Um Donneraan den Windsucher aus seiner Gefangenschaft zu befreien, müsst Ihr Hochlord Demitrian die rechten und linken Hälften der Fesseln des Windsuchers, 10 Elementiumbarren und die Essenz des Feuerfürsten bringen.",
    [7787] = "Präsentiert Hochlord Demitrian die vom Wind berührte, schlummernde Klinge.",
    [7790] = "Sucht am Thondroril nach dem Grund für das Ableben des Himmelsgeborenen.",
    [7810] = "Begebt Euch in die Arena des Schlingendorntals und sprecht mit Short John Mithril.",
    [7815] = "Katoom, der Angler aus Revantusk im Hinterland möchte, dass Ihr 15 Salzwasserschnappkiefer-Schildkröten tötet. Kehrt zu Ihm zurück, sobald Ihr Eure Aufgabe erledigt habt.",
    [7816] = "Katoom, der Angler aus Revantusk im Hinterland möchte, dass Ihr Gammerita  tötet und Katooms besten Köder aus ihrem Kadaver holt. Katoom meinte, dass Gammerita sich an der Küste bei den anderen Schildkröten aufhält.",
    [7828] = "Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr 15 Silbermähnenpirscher und 15 Silbermähnenheuler tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt. Markhor erwähnte, dass sich die Wölfe in der Wildnis des Hinterlands verstecken.",
    [7829] = "Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr 20 Wilde Eulenbestien tötet. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt. Markhor erwähnte, dass sich die Eulenbestien in der Wildnis des Hinterlands befinden.",
    [7830] = "Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr einen Klingenschnabelhimmelsfürsten tötet und dessen Federbusch an Euch nehmt. Kehrt zu ihm zurück sobald Ihr diese Aufgabe erledigt habt. Die Klingenschnabelhimmelsfürsten sind eine recht seltene Spezies und nisten meist in der Wildnis des Hinterlands.",
    [7839] = "Schmied Slagtree aus Revantusk im Hinterland möchte, dass Ihr seine verlorenen Werkzeuge ausfindig macht und dann zu ihm zurückkehrt. Ihr erinnert Euch an Schmied Slagtrees Worte, dass die Werkzeuge möglicherweise bei einem der Tempel der Vilebranch zu finden seien, im Nordosten des Hinterlands. Ihr solltet auch Skulk Rock absuchen.",
    [7840] = "Lard aus Revantusk im Hinterland möchte, dass Ihr Lards Brotzeit wieder findet. Kehrt nach Erfüllung dieser Aufgabe zu ihm zurück. Lard erwähnte, dass er es auf der Insel im Norden vergessen habe. Achtet auf die Trolle der Vilebranch.",
    [7841] = "Otho Moji'ko aus Revantusk im Hinterland möchte, dass Ihr 15 Hochtalkundschafterinnen, 15 Hochtalspäher, 15 Hochtalschützen und 15 Hochtalwaldläuferinnen tötet. Kehrt nach vollendeten Taten zu ihm zurück. Ihr findet die Hochtalelfen bei der Jagdhütte Quel'Danil im Nordwesten des Hinterlands.",
    [7842] = "Otho Moji'ko aus Revantusk im Hinterland möchte, dass Ihr ihm 10 lange elegante Federn von Greifen besorgt, die das Hinterland bewohnen. Kehrt mit den Federn zu ihm zurück. Es ist bekannt, dass Greifen überall im Hinterland zu finden sind.",
    [7843] = "Otho Moji'ko aus Revantusk im Hinterland möchte, dass Ihr zum Aerie Peak im Westen des Hinterlands reist und die letzte Botschaft an die Wildhammer beim Brunnen im Stadtzentrum platziert. Kehrt nach Vollendung der Aufgabe zu ihm zurück. Hütet Euch vor zornigen Wildhammer-Zwergen und niederträchtigen Mitgliedern der Allianz.",
    [7844] = "Mystikerin Yayo'jin aus Revantusk im Hinterland möchte, dass Ihr 30 Skalpierer der Vilebranch und 15 Sterndeuter der Vilebranch tötet. Kehrt nach Vollendung dieser Aufgabe zu ihr zurück. Yayo'jin deutete an, dass man diese Trolle nahe der Tempel von Shaol'watha und Agol'watha finden könnte. Sie liegen im Nordosten des Hinterlands.",
    [7845] = "Primal Torntusk aus Raventusk im Hinterland möchte, dass Ihr ihren Gefährten, den Älteren Torntusk, aus Jintha'Alor befreit. Man sagte Euch, dass er hoch oben in Jintha'Alor gefangen gehalten wird - der Hauptstadt der Vilebranch im Süden des Hinterlands.",
    [7846] = "Der Ältere Torntusk in Jintha'Alor möchte, dass Ihr Hitah'ya die Bewahrerin tötet, um in den Besitz des Fesselnschlüssels zu kommen. Kehrt zum Älteren Torn'tusk zurück, wenn Ihr den Schlüssel habt.",
    [7847] = "Der Ältere Torntusk in Jintha'Alor möchte, dass Ihr Primal Torntusk in Revantusk die Neuigkeit von seiner Befreiung überbringt.",
    [7848] = "Begebt Euch zum Portal in den Blackrocktiefen, das in den geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Riftwaker am Blackrock zurück.",
    [7849] = "Jäger Markhor aus Revantusk im Hinterland möchte, dass Ihr die Überreste seines Zwillingsbruders bergt. Findet den Schädel und die Knochen des Jägers Malkhor und bringt sie zu Jäger Markhor zurück. Markhor erwähnte, dass die Überreste seines Bruders an die Brühschlammer und Wölfe der Vilebranch verfüttert wurden. Er sagte weiterhin, dass es in Jintha'Alor eine Grube mit Brühschlammern gibt, sowie einen Wolfsbau. Beide liegen in der Nähe der Tempelspitze.",
    [7850] = "Primal Torntusk aus Revantusk im Hinterland möchte, dass Ihr Euch 10 Gefäße mit besudeltem Blut aus Jintha'Alor beschafft. Kehrt dann damit zu Primal Torntusk zurück.",
    [7861] = "Ihr habt die Anweisung erhalten die üble Priesterin Hexx und 20 Aman'zasiwachen der Vilebranch zu töten. Habt Ihr Eure Aufgabe erfüllt, so sprecht mit Primal Torntusk aus Revantusk im Hinterland. Die üble Priesterin Hexx und die Aman'zasiwachen halten sich hoch oben in Jintha'Alor im Hinterland auf.",
    [7862] = "Ihr wurdet mit der Vernichtung von 20 Berserkern der Vilebranch, 20 Schattenjägern der Vilebranch, 20 Bluttrinkern der Vilebranch und 20 Seelenfressern der Vilebranch beauftragt. Kehrt nach Beendigung dieser Aufgabe zu Primal Torntusk aus Revantusk im Hinterland zurück.",
    [7877] = "Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!",
    [7907] = "Gebt das Bestienkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.",
    [7927] = "Gebt das Portalkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.",
    [7928] = "Gebt das Kriegsherrenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.",
    [7929] = "Gebt das Elementarkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.",
    [8053] = "Bringt urzeitliche Hakkaribindungen zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens freundlich oder höher sein. Jin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.",
