    [8079] = "Bringt einen urzeitlichen Hakkarikosak zu Jin'rokh dem Zerstörer. Die Einstellung des Stammes der Zandalar muss Euch gegenüber wenigstens respektvoll oder höher sein. Jin'rokh der Zerstörer befindet sich auf der Insel Yojamba im Schlingendorntal.",
    [8105] = "Erobert die Mine, das Sägewerk, die Schmiede und die Farm und meldet Euch anschließend bei Feldmarschall Onslight in der Zuflucht.",
    [8114] = "Betretet das Arathibecken, erobert und kontrolliert gleichzeitig vier Stützpunkte im Arathibecken und kehrt danach zu Feldmarschall Oslight in der Zuflucht zurück.",
    [8115] = "Kontrolliert gleichzeitig fünf Stützpunkte im Arathibecken und kehrt danach zu Feldmarschall Oslight in der Zuflucht zurück.",
    [8120] = "Erobert die Mine, das Sägewerk, die Schmiede, die Farm und die Ställe und kehrt dann zu Todesmeister Dwire in Hammerfall zurück.",
    [8121] = "Haltet vier Stützpunkte zurselben Zeit im Arathibecken und kehrt danach zu Todesmeister Dwire nach Hammerfall zurück.",
    [8122] = "Haltet fünf Stützpunkte zurselben Zeit im Arathibecken und kehrt danach zu Todesmeister Dwire nach Hammerfall zurück.",
    [8151] = "Sprecht mit Ogtinc in Azshara.",
    [8152] = "Reist zur Kapelle des hoffnungsvollen Lichts und fragt jemanden nach den durchnässten Hinweisen, die Ihr gefunden habt.",
    [8153] = "Bringt ein perfektes Rennergeweih zu Ogtinc nach Azshara. Er befindet sich auf den Klippen nordöstlich der Ruinen von Eldarath.",
    [8166] = "Erobert die Mine, das Sägewerk, die Schmiede und die Farm und meldet Euch anschließend bei Feldmarschall Onslight in der Zuflucht.",
