    [8201] = "Reiht die Köpfe der 5 Kanalisierer auf der heiligen Kordel aneinander. Bringt dann die Trollschädelsammlung zu Exzhal auf der Insel Yojamba.",
    [8227] = "Bringt Nats Maßband zu Nat Pagle in den Marschen von Dustwallow zurück.",
    [8231] = "Bringt 6 Wellenhauerschuppen zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.",
    [8232] = "Bringt Morphaz' Zahn zu Ogtinc in Azshara. Ogtinc wohnt oberhalb des Kliffs, nordöstlich der Ruinen von Eldarath.",
    [8233] = "Sprecht mit Lord Jorach Ravenholdt im Ravenholdt-Anwesen.",
    [8234] = "Erlangt die versiegelte azurblaue Tasche von dem Schamanen der Holzschlundfeste in Azshara zurück. Bringt sie anschließend zum Erzmagier Xylem, der ebenfalls in Azshara zu finden ist.",
    [8235] = "Bringt Erzmagier Xylem in Azshara 10 verschlüsselte Fragmente.",
    [8236] = "Bringt den azurblauen Schlüssel zu Lord Jorach Ravenholdt.",
    [8240] = "Zerstört jedes Schmuckstück der Hakkari, das Ihr in Zul'Gurub findet, am Altar von Zanza auf der Insel Yojamba. Sobald Ihr dies getan habt, sprecht ganz in der Nähe mit Vinchaxa.",
    [8250] = "Sucht nach Sanath Lim-yo und verschafft Euch Zugang zu Erzmagier Xylem.",
    [8251] = "Bringt Erzmagier Xylem in Azshara 10 glitzernde Staubproben.",
    [8252] = "Sammelt 6 verzauberte Korallen und bringt sie zum Erzmagier Xylem.",
    [8253] = "Beschafft den arkanen Splitter von Morphaz' Leichnam und kehrt mit ihm zu Erzmagier Xylem zurück.",
    [8254] = "Sucht Ogtinc in Azshara auf.",
    [8255] = "Beschafft 4 gesunde Rennerdrüsen und bringt sie zu Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath.",
    [8256] = "Beschafft ein Sekret des Untodes für Ogtinc in Azshara. Ihr findet ihn auf den Klippen, nordöstlich der Ruinen von Eldarath.",
    [8257] = "Tötet Morphaz im versunkenen Tempel von Atal'Hakkar und bringt Greta Mosshoof im Teufelswald sein Blut. Der Eingang zum versunkenen Tempel liegt in den Sümpfen des Elends.",
    [8258] = "Wendet das Orakel der Anrufung inmitten des Kellergewölbes des großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel auftauchen; besiegt ihn. Bringt Schattensichels Kopf zu Sagorne Creststrider im Tal der Weisheit in Orgrimmar.",
    [8275] = "Sprecht mit Windruferin Proudhorn auf Burg Cenarius in Silithus.",
    [8276] = "Sprecht mit Windruferin Proudhorn auf Burg Cenarius in Silithus.",
    [8277] = "Beetix Ficklespragg von der Burg Cenarius in Silithus möchte, dass Ihr 8 Stachel von Steinpanzerskorpiden und 8 Giftzähne von Sandhuschern für sie sammelt. Kehrt zu ihr zurück, sobald Ihr diese Aufgabe erfüllt habt.",
    [8278] = "Beetix Ficklespragg von der Burg Cenarius in Silithus möchte, dass Ihr je 3 Stachel von Steinpanzerzangen und Steinpanzerschindern, sowie 3 Felspirschergiftzähne für sie sammelt.",
    [8279] = "Bringt Ortell dem Einsiedler in Silithus die drei Kapitel des Lexikons der Twilight.",
    [8280] = "Windruferin Proudhorn auf Burg Cenarius in Silithus möchte, dass Ihr 15 Baggerschläger tötet.",
    [8281] = "Windruferin Proudhorn auf Burg Cenarius in Silithus möchte, dass Ihr 20 Baggerbrecher tötet.",
    [8282] = "Spürt Noggles Ranzen im südlichen Gebirge von Silithus auf und bringt ihn zu ihm, auf Burg Cenarius, zurück.",
    [8283] = "Bringt die Zange Totenstachels zu Vish Kozus, Captain der Wache.",
    [8284] = "Geologin Larksbane auf Burg Cenarius möchte, dass Ihr ihr 8 Schrifttafelfragmente der Twilight bringt.",
    [8285] = "Bringt die wiederhergestellte Schrifttafel zu Ortell dem Einsiedler in Silithus.",
    [8286] = "Reist zu den Höhlen der Zeit in Tanaris und findet Anachronos, Nachkomme Nozdormus.",
    [8287] = "Bringt Kommandant Mar'alith die entschlüsselte Abschrift der Schrifttafel.",
    [8288] = "Bringt Brutwächter Dreschbringers Kopf zu Baristolth der Sandstürme in die Burg Cenarius in Silithus.",
    [8301] = "Kehrt zu Baristolth zurück, sobald Ihr 200 Silithidenknochenpanzerfragmente gesammelt habt.",
    [8302] = "Kehrt zu Baristolth zurück, sobald Ihr 200 Silithidenknochenpanzerfragmente gesammelt habt.",
    [8303] = "Sucht nach Anachronos bei den Höhlen der Zeit in Tanaris.",
    [8304] = "Kommandant Mar'alith auf Burg Cenarius in Silithus möchte, dass Ihr die Bewohner von Bronzebeards Lager befragt. Das Lager befindet sich südlich von Burg Cenarius. Kehrt zu Kommandant Mar'alith zurück, wenn Ihr die benötigten Informationen gesammelt habt.",
    [8305] = "Sucht die Kristallträne und blickt in ihr Innerstes.",
    [8306] = "Kommandant Mar'alith auf Burg Cenarius in Silithus möchte, dass Ihr seine geliebte Natalia wiederfindet. Die von Euch gesammelten Informationen deuten darauf hin, dass Ihr sie im Bau des Regalschwarms im Süden finden könntet. Sprecht noch einmal mit den Zwergen in Bronzebarts Lager, bevor Ihr Euch in den Schwarmbau begebt. Ihr Wissen könnte sich als hilfreich erweisen und sicherlich, haben sie noch einige Aufgaben für Euch. Und <name>, denkt an die Worte des Kommandanten: \"Tut, was Ihr tun müsst...\"",
    [8307] = "Haltet beim Lager der Twilight-Hammer westlich von Burg Cenarius nach Informationen zum Zubereiten von Sandwurmfleisch Ausschau.",
    [8308] = "Liefert Brann Bronzebeards verlorenen Brief in Bronzebeards Lager im südlichen Silithus ab.",
    [8309] = "Rutgar Glyphshaper in Bronzebeards Lager in Silithus möchte, dass Ihr in den Bau des Ashischwarms, Bau des Zoraschwarms und Bau des Regalschwarms eindringt und dort Abpausbilder von den glyphenverzierten Kristallen anfertigt. Benutzt das Abschriftenset für Geologen, um Abpausbilder der uralten Glyphen herzustellen. Kehrt nach Abschluss der Aufgabe zu Rutgar Glyphshaper zurück.",
    [8310] = "Frankal Stonebridge in Bronzebeards Lager möchte, dass Ihr ihm jeweils ein Silithidengehirn des Zoraschwarms, Ashischwarms und des Regalschwarms bringt. Kehrt nach der Erfüllung Eurer Aufgabe zu Frankal zurück.",
    [8313] = "Bringt die ausgerissene Rezeptseite zu Calandrath ins Gasthaus der Burg Cenarius.",
    [8314] = "Rutgar Glyphshaper in Bronzebeards Lager möchte, dass Ihr Geologin Larksbane auf Burg Cenarius in Silithus das glyphenverzierte Kristallprisma bringt.",
    [8315] = "Geologin Larksbane auf Burg Cenarius in Silithus möchte, dass Ihr ihr den Kristallentriegelungsmechanismus vom Abgesandten der Qiraji beschafft. Nehmt die Glyphen der Anrufung, begebt Euch zu den Knochen von Grakkarond südlich von Burg Cenarius und zeichnet sie dort in den Sand. Sollte der Abgesandte der Qiraji erscheinen, tötet ihn und nehmt den Kristallentriegelungsmechanismus an Euch. Kehrt anschließend zu Geologin Larksbane zurück. Für diese Aufgabe werdet Ihr eine kleine Armee benötigen, <Name>!",
    [8317] = "Calandrath von der Burg Cenarius braucht 10 geräucherte Wüstenknödel.",
