    [8446] = "Sucht nach jemandem, der die Bedeutung des in Alpträume gehüllten Gegenstands entschlüsseln kann. Vielleicht kann Euch ein Druide von großer Macht weiterhelfen.",
    [8447] = "Wartet, bis Bewahrer Remulos in Moonglade den von Alpträumen eingehüllten Gegenstand gereinigt hat.",
    [8460] = "Grazle möchte, dass Ihr Euch beweist, indem Ihr 6 Krieger der Totenwaldfelle, 6 Pfadfinder der Totenwaldfelle und 6 Gärtner der Totenwaldfelle besiegt. Kehrt zu ihm in den Süden des Teufelswalds nahe des Smaragdrefugiums zurück, sobald Ihr dies getan habt.",
    [8461] = "Nafien möchte, dass Ihr 6 Höhlenbehüter der Totenwaldfelle, 6 Rächer der Totenwaldfelle und 6 Schamanen der Totenwaldfelle besiegt. Kehrt danach zu ihm in den Norden des Teufelswalds nahe des Eingangs der Holzschlundfeste zurück.",
    [8462] = "Reist nach Norden entlang der Hauptstraße des Teufelswalds und sprecht mit einem Furbolg names Nafien. Er hält außerhalb des Eingangs zur Holzschlundfeste Wache.",
    [8464] = "Salfa möchte, dass Ihr 8 Schamanen der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Ursa der Winterfelle erledigt. Salfa befindet sich direkt außerhalb des Eingangs zur Holzschlundfeste in Winterspring.",
    [8465] = "Durchquert die Holzschlundfeste und verlasst sie in Richtung Winterspring. Sprecht mit Salfa, die außerhalb des Eingangs zur Holzschlundfeste Wache steht.",
    [8470] = "Bringt das Ritualtotem in die Holzschlundfeste und findet heraus, ob einer der dortigen Furbolgs eine Verwendung für diesen Gegenstand hat. Die Furlbolgs der Holzschlundfeste werden solange nicht mit Euch sprechen, bis Euer Ruf bei ihnen neutral oder höher ist.",
    [8471] = "Bringt das Ritualtotem in die Holzschlundfeste und findet heraus, ob einer der dortigen Furbolgs eine Verwendung für diesen Gegenstand hat. Die Furlbolgs der Holzschlundfeste werden solange nicht mit Euch sprechen, bis Euer Ruf bei ihnen neutral oder höher ist.",
    [8481] = "Stellt die Fackel zur Dämonenbeschwörung im Eingang der Höhle des Oberhäuptlings der Winterfelle, im Lager der Winterfellfurbolgs auf. Besiegt den Dämon und erlangt die Essenz von Xandivious für Gorn Einauge in der Holzschlundfeste.",
    [8484] = "Bringt das Friedensangebot der Holzschlundfeste zu König Magni Bronzebeard in Ironforge.",
    [8485] = "Bringt das Friedensangebot der Holzschlundfeste zu Thrall in Orgrimmar.",
