    [8495] = "Bringt 20 Eisenbarren zu Corporal Carnes beim Landeplatz in Dun Morogh.",
    [8496] = "Bringt 30 schwere Runenstoffverbände, 30 schwere Seidenverbände und 30 schwere Magiestoffverbände zu Windruferin Proudhorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz X, um diese Aufgabe abschließen zu können.",
    [8497] = "Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 geräucherte Wüstenknödel zu Calandrath in der Taverne von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz I, um diese Aufgabe abschließen zu können.",
    [8498] = "Beschafft Euch die Schlachtordnungen der Twilight und bringt sie zu Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch den taktischen Einsatz X, um diese Aufgabe abschließen zu können.",
    [8499] = "Bringt 20 Thoriumbarren zu Dame Twinbraid im Militärviertel in Ironforge.",
    [8500] = "Bringt 20 Thoriumbarren zu Dame Twinbraid beim Landeplatz in Dun Morogh.",
    [8501] = "Tötet 30 Stecher des Ashischwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz XII, um diese Aufgabe abschließen zu können.",
    [8502] = "Tötet 30 Arbeiter des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz III, um diese Aufgabe abschließen zu können.",
    [8503] = "Bringt 20 Stück Würgetang zu dem Gefreiten Draxlegauge im Militärviertel in Ironforge.",
    [8504] = "Bringt 20 Stück Würgetang zu dem Gefreiten Draxlegauge beim Landeplatz in Dun Morogh.",
    [8505] = "Bringt 20 lila Lotus zu Meister Nightsong im Militärviertel in Ironforge.",
    [8506] = "Bringt 20 lila Lotus zu Meister Nightsong beim Landeplatz in Dun Morogh.",
    [8507] = "Erstattet am Posten der Ironforgebrigade beim Zoraschwarmbau Bericht. Bereitet Eure nicht unterzeichneten Felddienstpapiere vor, lasst sie von Captain Blackanvil unterzeichnen und kehrt zu Windrufer Kaldon auf Burg Cenarius in Silithus zurück. Hinweis: das Heilen oder Wirken von begünstigenden Zaubern auf ein Mitglied der Ironforgebrigade wird Euch für den PvP-Kampf markieren.",
