    [8988] = "Bringt Bodley im Blackrock etwas Seelenasche der Verbannten.",
    [8989] = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Mor Grayhoof zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück.",
    [8990] = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Isalien zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück.",
    [8991] = "Benutzt das Räuchergefäß der Beschwörung, um die Geister von Jarien und Sothos zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück.",
    [8992] = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Kormok zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück.",
    [8994] = "Bringt Bodley im Blackrock 40 Blackrockarmschienen und ein Fläschchen mit oberster Macht.",
    [8995] = "Benutzt das Räuchergefäß der Beschwörung, um Lord Valthalak zu beschwören. Macht ihn unschädlich und benutzt dann Lord Valthalaks Amulett bei seiner Leiche. Danach werdet Ihr dem Geist von Lord Valthalak sein Amulett zurückgeben müssen.",
    [8996] = "Bringt das Räuchergefäß der Beschwörung zurück zu Bodley im Blackrock.",
    [8997] = "Sprecht mit Deliana am Hohen Sitz von Ironforge.",
    [8998] = "Sprecht mit Mokvar in der Feste Grommash im Tal der Weisheit von Orgrimmar.",
