    [9013] = "Gebt Mokvar Euren Helm der Ehre und Eure Brustplatte der Ehre.",
    [9014] = "Gebt Mokvar Eure Krone des Magisters und Eure Roben des Magisters.",
    [9015] = "Reist zum Ring des Gesetzes der Blackrocktiefen und errichtet das Banner der Provokation in dessen Mitte, während Ihr von Oberrichter Grimmstein verurteilt werdet. Tötet Theldren und seine Gladiatoren und kehrt dann mit dem ersten Stück von Lord Valthalaks Amulett zu Anthion Harmon in den östlichen Pestländern zurück.",
    [9016] = "Kehrt mit einem Paar Stiefel des Wildherzens, einem Kilt des Wildherzens und einer Schiftung des Wildherzens zu Mokvar in Orgrimmar zurück.",
    [9017] = "Kehrt mit einem Paar Bestienjägerstiefeln, einer Bestienjägerhose und einem Bestienjägermantel zu Mokvar in Orgrimmar zurück.",
    [9018] = "Kehrt mit einem Paar Stiefel des Magisters, Gamaschen des Magisters und einem Mantel des Magisters zu Mokvar in Orgrimmar zurück.",
