    [9021] = "Kehrt mit einem Paar Sandalen der Furcht, Gamaschen der Furcht und einem Mantel der Furcht zu Mokvar in Orgrimmar zurück.",
    [9022] = "Kehrt mit einem Paar Stiefel der Ehre, Beinplatten der Ehre und einer Schiftung der Ehre zu Mokvar in Orgrimmar zurück.",
    [9023] = "Dirk Thunderwood in der Burg Cenarius will, dass Ihr ihm Venoxis' Giftbeutel und Kurinnaxx' Giftbeutel bringt.",
    [9032] = "Reist zum Blackrock und benutzt den extradimensionalen Geisterdetektor, um Bodley nahe der Blackrockspitze zu finden.",
