    [93090] = "Sprecht mit Ayessa Dawnsinger, wenn Ihr bereit seid, die Insel Zephras zu verlassen.",
    [93122] = "Wahrt Euren Ruf bei den Gelkis und untersucht Knotenpunkte der Zentrauren innerhalb von Shen'dralas. Kehrt mit Euren Erkenntnissen zu Nerlokh am Eingang zum Tal der Knochen zurück.",
    [93125] = "Wahrt Euren Ruf bei den Gelkis und begleitet Rokren aus der Zuflucht der Ausgestoßenen. Berichtet dann Nerlokh in der Nähe des Tals der Knochen, was sich zugetragen hat.",
    [93127] = "Aktiviert die Wächtersteine im Norden, Westen und Süden rund um die Blackthorne-Kultisten.",
    [93128] = "Wahrt Euren Ruf bei den Gelkis und besiegt Khan Jehn im Dorf Magram. Erstattet danach Bericht bei Uthek der Weisen im Dorf Gelkis in Desolace.",
    [93129] = "Wahrt Euren Ruf bei den Magram und bringt 6 gestohlene Vorräte zurück zu Hagiak an der Front der Magram.",
    [93159] = "Sprecht mit dem seltsamen Einsiedler im Schattenwindwald und erfahrt mehr über ihn.",
    [93160] = "Sammelt 8 Schattenwindeicheln.",
    [93161] = "Findet jemanden, der sich für den uralten Griff interessieren könnte, den Ihr in den Ruinen von Ban'aethal gefunden habt.",
    [93165] = "Sammelt 5 Ohren von Al'Aketh-Kultisten im Schattenwindwald, beim Schrein von Akir oder im Böenbeerentiefland.",
    [93172] = "Zerstört 10 Windhüllen im Schattenwindwald.",
    [93176] = "Benutzt die Gegenstände aus dem Einsteigerpaket für Entomologen, um eine Laubengangtarantel, einen Heurüsselkäfer und einen Fleischpflücker zu finden und einzufangen.",
    [93188] = "Wahrt Euren Ruf bei den Magram und erstattet Orgrul in der Nähe des nördlichen Eingangs zum Tal der Knochen Bericht.",
    [93196] = "Wahrt Euren Ruf bei den Magram und vollführt ein nekromantisches Ritual, um Khan Jehn wiederzubeleben. Die Ritualstätte findet Ihr in einem Zelt beim zentralen See im Dorf Magram.",
    [93197] = "Bringt die Postpakete von Sebelia aus dem Gipfellager am Hyjal zu Gastwirt Vizzie in Everlook.",
    [93224] = "Sammelt 5 geschnitzte Zentaurentotems, indem Ihr Zentauren aller Klans in Desolace tötet. Bringt sie dann zu Captain Pentigast auf der Nijelspitze.",
    [93225] = "Sammelt 5 geschnitzte Zentaurentotems, indem Ihr Zentauren aller Klans in Desolace tötet. Bringt sie dann zu Gurda Wildmähne im Geistwandlerposten.",
    [93226] = "Bringt die Totemtasche zum Rüstmeister der Magram im Dorf der Magram in Desolace, um Euren Ruf bei diesem Klan deutlich zu erhöhen. Ihr müsst dem Magramklan gegenüber mindestens neutral eingestellt sein.",
    [93227] = "Bringt die Totemtasche zum Rüstmeister der Gelkis im Dorf der Gelkis in Desolace, um Euren Ruf bei diesem Klan deutlich zu erhöhen. Ihr müsst dem Gelkisklan gegenüber mindestens neutral eingestellt sein.",
    [93269] = "Bringt die Post von Everlook hoch zu Gastwirt Sebelia auf dem Gipfel von Hyjal.",
    [93317] = "Sammelt 6 Stück Windweisenkriecherfleisch.",
    [93318] = "Tötet Vulgara den Unersättlichen im Shen'darhochland and bringt ihren Kopf zu Danarii Bellowveil.",
    [93319] = "Sammelt 10 gestohlene Windsteine von den Hochlandbanditen im Shen'darhochland.",
    [93320] = "Meldet Euch bei Yorana Windyreed im östlichen Wachturm im Böenbeerentiefland.",
    [93341] = "Untersucht die Verlorenen Gärten in der Nähe von Shen'dralas und kehrt anschließend zurück zu Mithera im nahegelegenen Tempel.",
    [93362] = "Merzt Pflanzen im Verlorenen Garten aus und kehrt anschließend zurück zu Mithera in Shen'dralas.",
    [93383] = "Wartet, bis Ihr das persönliche Überlebenspaket sicher öffnen könnt",
    [93394] = "Findet Magister Kirandis im Tempel von Shen'dralas.",
    [93404] = "Begebt Euch nach Maraudon und besorgt für Waldemar in den Verlorenen Gärten in Desolace eine Phiole mit Wasser aus den Fällen des Irdenen Gesangs.",
    [93406] = "Findet 4 vermisste Post in den Hügeln nördlich von Everlook und bringt sie zurück zu Gastwirt Vizzie.",
    [93407] = "Findet Dornensamen in den Wäldern am Gipfel von Hyjal und bringt sie zu Tiala Whitemane zurück.",
    [93422] = "Tötet die Kurierin der Blackthorne und beschlagnahmt ihre Nachricht.",
    [93429] = "Tötet 10 Verirrte im Fallow Heiligtum.",
    [93430] = "Findet den Angler der Verirrten, der Pelluks Köder gestohlen hat, und holt ihn zurück.",
    [93443] = "Bringt die verlorene Transportkiste zu Friz Frazzlespark im Hafen von Powderfuse in den Flusslanden zurück.",
    [93444] = "Tötet einen Nachtsäblerwächter am nördlichen Rand des Gipfels und lockt anschließend Ghansurok mit dem Schenkel des Nachtsäblerwächters hervor und tötet das Monster. Kehrt mit dem Herz der Schimäre zurück.",
    [93450] = "Nehmt Vindaels unvollendetes Schwert und findet einen Weg, es in die Geisterwelt zu bringen. Bringt die geisterhafte Klinge anschließend zurück zu ihm nach Shen'dralas.",
    [93461] = "Sprecht mit Rathiril Sunlance und Coriella Calmbreeze in Shen'dar.",
    [93464] = "Findet den Magier in Desolace, der von der Macht des Draenethyst weiß.",
    [93465] = "Holt Gimashis Notizen über Draenethyst und bringt sie zu Azore Aldamort.",
    [93510] = "Findet den Anker am Immerruhsee, an den sich der Kriegsveteran aus seiner Kindheit erinnert.",
    [93521] = "Bringt Ve'hans Forschungsnotizen zu Tiala Whitemane.",
    [93546] = "Sucht in der Umgebung von Shen'dralas nach Spektraleisenvorkommen und sammelt 10 Spektraleisenerze. Kehrt zu Vindael in Shen'dralas zurück, sobald Ihr genug gefunden habt.",
    [93547] = "Pflanzt Dornensamen in der Nähe des Gasthauses, des Lagerturms und der Baumgruppe im Lager der loyalistischen Druiden.",
    [93551] = "Verwendet die geschmückte Waffenscheide, um den Veteranen des Dritten Krieges am Hyjal, neben der zerbrochenen Kanone in Klageruh, zu treffen.",
    [93552] = "Sammelt 15 Windsteinhaufen von rohen Windsteinen im Thendalhain.",
    [93567] = "Erlaubt dem Veteranen des Dritten Krieges neben der zerbrochenen Kanone in Klageruh, seine Geschichte zu erzählen.",
    [93568] = "Bringt das teilweise verdaute Halsband zu jemandem, der mehr darüber weiß. In Shen'dralas in Desolace oder in unmittelbarer Umgebung davon sollte sich jemand finden lassen.",
    [93574] = "Findet jemanden, der Interesse an dem Leichenfresserpanzer haben könnte.",
    [93584] = "Tötet 10 Adepten der Blackthorne und 10 wildnisgezeichnete Kultisten.",
    [93585] = "Begleitet Vater Tuttle zum Sicheren Hafen.",
    [93594] = "Findet Waldemar in den Verlorenen Gärten bei Shen'dralas in Desolace.",
    [93601] = "Sucht beim Rückzugsort der Borstennacken einen Stacheleber von Bedeutung auf.",
    [93604] = "Begebt Euch zu den Hügeln von Razorfen und besorgt virulentes Blut von Agamaggan. Kehrt dann zu Kog'thug dem Tapferen im Rückzugsort der Borstennacken in Desolace. Kog'thug hielt es für nötig, Euch daran zu erinnern, dass das Blut von Agamaggan in den Kral von Razorfen nicht ausreicht.",
    [93606] = "Schlichtet den Streit der Stacheleber, indem Ihr Quolga einen großzügigen Blumenstrauß und das virulente Blut von Agamaggan bringt. Die Blumen für den Strauß findet Ihr bei den Verlorenen Gärten in der Nähe von Shen'dralas in Desolace.",
    [93609] = "Bringt die verlorene Halskette zu Mithera beim Tempel von Shen'dralas in Desolace.",
    [93615] = "Sucht in der Wildnis auf dem Hyjal nach Shalla'kals Kätzchen.",
    [93617] = "Bringt die Hirsche davon ab, sich wie Raubtiere aufzuführen.",
    [93644] = "Der Text deutet darauf hin, dass sich der Verfasser dieses Tagebuchs irgendwo in Shen'dralas befinden könnte.",
    [93663] = "Findet den vermissten Kurier und stellt sicher, dass Dars Lieferung im Sicheren Hafen ankommt.",
    [93678] = "Bringt Azores abgeschriebene Notizen zu Magtoor im Sicheren Hafen in den Sümpfen des Elends.",
    [93679] = "Seht Euch gemeinsam mit Magtoor Onkus Vision an.",
    [93680] = "Holt den Kanalisationsschlüssel von Dalaran für Magus Wordeen Voidglare in Tarrens Mühle.",
    [93684] = "Findet den Draenei, der nach Draenethyst sucht, in den Verwüsteten Landen.",
    [93685] = "Findet eine fehlerlose Draenethystsphäre in den Verwüsteten Landen und bringt sie zu Kum'isha dem Sammler. Doch seid gewarnt. Der Edelstein ist einer der rarsten Kristalle von ganz Azeroth. Jedes Wesen in diesem Land könnte eine fehlerlose Draenethystsphäre bei sich haben.",
    [93735] = "Findet Riaani Nightwind im westlichen Teil von Valanaar.",
    [93736] = "Sammelt 10 Windhüllenessenzen von Windhüllen im Schattenwindwald.",
    [93737] = "Sprecht mit Rianni Nightwind und hört, was er zu sagen hat.",
    [93738] = "Erstattet Ayessa Dawnsinger in Valanaar Bericht.",
    [93739] = "Sprecht mit Nazgrel in der Festung Grommash, um weitere Hinweise zu erhalten. Befolgt die erhaltenen Hinweise, um Vol'jin, Cairne Bloodhoof und Fürstin Sylvanas Windrunner aufzusuchen und mit ihnen zu sprechen.",
    [93740] = "Sammelt 10 Windsteinamulette der Al'Aketh von toten Kultisten im Böenbeerentiefland.",
    [93746] = "Konfrontiert Belathaan Brightwish auf der Straße zum Schrein von Akir.",
    [93747] = "Pflanzt die verzauberten Samen in der Nähe der zerstörten Balliste, des zerstörten Katapults und der zerstörten Flugmaschine.",
    [93759] = "Sammelt 2 Stücke Wildfleisch von unbefleckten Hyjalhirschen und 6 scharlachrote Wurmknollen für den Eintopf des Einsiedlers.",
    [93773] = "Erstattet Ketharas auf dem Hyjal Bericht.",
    [93786] = "Tötet 12 Landarbeiter aus Wiesenbach und kehrt dann zu Krom'rosh zurück, um ihm von Eurem Erfolg zu berichten.",
    [93787] = "Stehlt 6 Futterbeutel von der Allianzfarm in Wiesenbach und kehrt zu Krom'rosh zurück.",
    [93788] = "Erbeutet 10 Äxte des Holzarbeiters von den Holzfällern bei Turners Holzfällerlager für Kreza Darkthorn in Rog'mar.",
    [93791] = "Sprecht mit Belann Windwood in Valanaar.",
    [93797] = "Bringt einen winddurchfluteten Zweig zu Belann Windwood in Valanaar.",
    [93825] = "Sammelt 12 Klumpen Mondschleiermoos und kehrt zu Suma Mossmane zurück.",
    [93826] = "Tötet 8 Totemiker der Totenwaldfelle und 8 Teufelspfleger der Totenwaldfelle und kehrt zum Ältesten Pinespeaker zurück.",
    [93827] = "Sammelt 16 verzauberte Harpyienamulette und kehrt zu Thobon Sapclaw zurück.",
    [93828] = "Sammelt 10 luftgetrocknete Kräuter überall im Bau der Baumrindenfurbolgs und bringt sie zu Fennar Mossmane.",
    [93830] = "Füllt Fennar Mossmanes Wasserschlauch am Teich außerhalb des Baus der Totenwaldfelle.",
    [93831] = "Sammelt 30 Bärenbeeren von Hyjal und kehrt zu Osi Mistpaw zurück.",
    [93832] = "Zerstört 6 Gargoyles des ewigen Wachpostens in der zerstörten Allianzbasis im oberen Hyjal und kehrt zur Ältesten Mistpaw zurück.",
    [93833] = "Bringt 5 Eulenkörper zum Ältesten Pinespeaker im Bau der Baumrindenfurbolgs in Hyjal.",
    [93834] = "Sammelt 10 Höhlenkäferteile für Dala Fairmaw.",
    [93835] = "Nehmt das Portal zu den Türmen der Rohashi oben und schließt Euch Elaadrin Evengale und Ayessa Dawnsinger bei ihrer Konfrontation mit der Hohepriesterin Lorthuna an.",
    [93836] = "Sprecht mit Talaanis Shadowsong in Valanaar.",
    [93848] = "Kehrt zu Ketharas zurück und berichtet ihm von den Ereignissen am Gipfel der Ewigkeit.",
    [93926] = "Findet Friedensbewahrer Vaaniel im westlichen Wachturm.",
    [93927] = "Hebt die Notiz auf, die Ihr bei dem toten Friedensbewahrer gefunden habt, um über Eure nächsten Schritte zu entscheiden.",
    [93948] = "Überbringt das Siegel der Familie Shadowsong an Talaanis Shadowsong in Valanaar.",
    [93949] = "Tötet Himmelshüpfer in Valanaar, bis Ihr 8 verzauberte Himmelshüpfer eliminiert habt.",
    [93951] = "Sammelt 8 Hippogryphendaunen im Shen'darhochland.",
    [93952] = "Bezwingt 9 Höhlenwächter der Totenwaldfelle und kehrt zu Brerufa zurück.",
    [93958] = "Sprecht mit Valanaar Stormfist im inneren Sanktum beim Schrein von Akir.",
    [93963] = "Sprecht mit Randal Emerson in der Burg Stomwind, um weitere Hinweise zu erhalten. Nutzt die erhaltenen Hinweise, um König Magni Bronzebeard, Hochtüftler Mekkatorque und Tyrande Whisperwind aufzusuchen und mit ihnen zu sprechen.",
    [93971] = "Bringt den Bericht zu Krom'rosh in Rog'mar.",
    [93976] = "Bringt die Klinge zu Kreza Darkthorns Bekannten bei den Docks östlich von Rog'mar.",
    [94003] = "Holt das Bollwerk der Himmelsbrecher von Zaal Stormshield am Schrein von Akir zurück.",
    [94004] = "Besorgt die vom Kunden angeforderten Gegenstände und liefert sie an die auf Eurer Karte markierte Position. Dieses Schriftstück muss sich in Eurem Besitz befinden, um die Transaktion abzuschließen.",
    [94006] = "Sprecht mit Urs'endris in der Nähe der Wasserfälle im Nordosten von Valanaar.",
    [94007] = "Meldet Euch bei Quel'ana Quickgale in Valanaar.",
    [94013] = "Benutzt die Zähmerrute, um einen Vuldrenalpha im Böenbeerentiefland zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmerrute dann zu Quel'ana Quickgale in Valanaar zurück.",
    [94050] = "Sprecht mit Quel'dora Quickgale in Valanaar.",
