    [96784] = "Findet jemanden in Burg Stromgarde, der etwas über den geheimen Handel weiß, während Ihr als ein Mitglied des Syndikats verkleidet seid.",
    [96785] = "Findet etwas in Burg Stromgarde, das Anastasia davon überzeugen kann, Euch Details über den geheimen Handel zu verraten.",
    [96786] = "Vereitelt den geheimen Handel und nehmt den Gegenstand, der an das Syndikat verkauft wird, an Euch. Kehrt dann zu Myrokos Silentform im Ravenholdtanwesen zurück.",
