    [96833] = "Warnt die anderen auf dem Berg vor der aggressiven Schimäre namens Ghansurok.",
    [96873] = "Pa'zula in Sen'jin möchte, dass Ihr 3 leuchtende Rückstände sammelt. Leuchtende Rückstände können durch das Entzaubern von verhexten Anhängern gefunden werden, die Trolle auf den Echoinseln fallen lassen.",
    [96874] = "Ug'thok in Orgrimmar möchte, dass Ihr 5 verwitterte Stacheln von Bestien am Donnergrat und 5 raue Schleifsteine für ihn sammelt.",
