    [96984] = "Holt den Arkanpartikel für Magus Wordeen Voidglare in Tarrens Mühle aus Dalaran.",
    [96986] = "Besiegt Atrexis den Grabritter in Dalaran für Melisara in Tarrens Mühle.",
    [96987] = "Holt das Buch \"Die Gründung von Dalaran\" aus Dalaran für Rexxie Copperclutch in der Nähe des Kanalisationseingangs.",
    [96988] = "Sammelt 6 gesprungene Wächterkerne in Dalaran für Doktor Martin Felben in Undercity.",
    [96989] = "Inspiziert die reitbaren Raptoren, um Euer erstes Reittier zu wählen.",
    [96991] = "Liefert Galvinquams Habseligkeiten bei Marn Euhron am Gipfel ab.",
    [96992] = "Sucht in den ausgebrannten Gebäuden der Wiege der Ruhe nach 6 Metallklammern und 30 Nägeln und bringt sie Johun \"Haudrauf\" Dillis in Hyjal.",
    [96994] = "Inspiziert die reitbaren Wölfe, um Euer erstes Reittier zu wählen.",
    [96996] = "Inspiziert die reitbaren Schreiter, um Euer erstes Reittier zu wählen.",
    [96997] = "Inspiziert die untoten Reitpferde, um Euer erstes Reittier zu wählen.",
    [96998] = "Sucht nach jemandem, der Kriegsbemalungsrolle wiedererkennen könnte.",
    [96999] = "Gebt die Kriegsbemalungsrolle jemandem in Sen'jin.",
    [97000] = "Durchsucht die zerstörten Lager der Allianz am Hyjal nach Hinweisen auf Abigail Sawyers Vater Lawrence.",
    [97001] = "Bringt das Geschäftsbuch der Familie Sawyer zu Abigail Sawyer im Kriegsviertel von Undercity.",
    [97003] = "Bringt den Kopf von Chol'aruk zu Gur'ak im Brachland.",
    [97005] = "Bringt Chol'aruks Kopf zu Bainham im Brachland.",
    [97006] = "Bringt das Geschäftsbuch der Familie Sawyer zum königlichen Vorarbeiter Bauhaus im Handwerksviertel von Undercity.",
    [97007] = "Bringt das beglaubigte Geschäftsbuch der Familie Sawyer zurück zu Abigail Sawyer im Kriegsviertel.",
    [97009] = "Bringt 12 Teufelshundstacheln zu Maerion Thaelemaches in Dae'gun.",
    [97010] = "Steigt auf die Spitze des Magierturms der Horde und werft einen explosiven Runensplitter ab, um Maerion Thalemaches das Signal zum Angriff auf die Dämonen zu geben.",
    [97017] = "Inspiziert die reitbaren Widder, um Euer erstes Reittier zu wählen.",
    [97018] = "Erlernt die Fähigkeit \"Unerfahrener Reiter\" von Ultham Ironhorn.",
    [97022] = "Sprecht mit Danitha Morr in der Bandarionfestung.",
    [97045] = "Inspiziert die Reitpferde, um Euer erstes Reittier zu wählen.",
    [97046] = "Inspiziert die Roboschreiter, um Euer erstes Reittier zu wählen.",
    [97047] = "Findet einen Schlüssel für Wendels Käfig und eine Verkleidung, mit der er sich aus Kurzens Truppenlager schleichen kann.",
    [97048] = "Sprecht mit Kapitänin Aransas in Booty Bay.",
    [97049] = "Sammelt 8 Essenzen des sickernden Schleims auf der Terrasse des Formers.",
    [97074] = "Erlernt die Fähigkeit \"Unerfahrener Reiter\" von Jartsam.",
    [97119] = "Bringt 6 pikante Hirschfrikadellen zu Ortak Lomgok in Holderwild.",
    [97130] = "Bergt einen uralten Götzen der Gurubashi aus der Versunkenen Stadt.",
    [97168] = "Wenn Ihr Eldrun Stormbreaker in Ironforge helfen wollt, so bringt ihm einen azerothianischen und einen makellosen schwarzen Diamanten.",
    [97169] = "Wendet das Orakel der Anrufung inmitten des Kellergewölbes des großen Ossuariums in Scholomance an. Ihr werdet damit Geister herbeirufen, die es zu bekämpfen gilt. Nach Vernichtung dieser Geister wird der Todesritter Schattensichel auftauchen; besiegt ihn. Bringt Schattensichels Kopf zu Eldrun Stormbreaker im düsteren Viertel von Ironforge.",
    [97170] = "Erlernt die Fähigkeit \"Unerfahrener Reiter\" von Randal Hunter.",
    [97171] = "Inspiziert die Reitpferde, um Euer erstes Reittier zu wählen.",
    [97173] = "Bergt ein Ritualtotem des Schwarzschlunds in der Schwarzschlundfeste.",
    [97174] = "Sprecht mit Danitha Morr in der Bandarionfestung in Tirisfal.",
    [97175] = "Reist nach Orgrimmar und besorgt Euch Hohepriester Zayus' Weihrauchschwenker. Eine Spende von 150 Gold wird erforderlich sein, um ihn zu bekommen.",
    [97176] = "Vertreibt mithilfe des Weihrauchschwenkers die gequälten Geister im Schreckenstal. Wenn Ihr 25 Schreckenstalgeister vernichtet habt, kehrt zu Danitha Morr in der Bandarionfestung in Tirisfal zurück.",
    [97177] = "Bringt den Weihrauchschwenker zu Danitha Morr in der Bandarionfestung in Tirisfal.",
    [97178] = "Sprecht mit Ott in Tarrens Mühle im Vorgebirge von Hillsbrad.",
    [97179] = "Bringt 40 Lagen Runenstoff, 6 Arkanitbarren, 10 Arthas' Tränen, 5 Phiolen Weihwasser aus Stratholme und 150 Gold zu Ott im Vorgebirge von Hillsbrad.",
    [97180] = "Bringt das Arkanitpferdegeschirr zur Prüfung zu Danitha Morr in der Bandarionfestung.",
    [97182] = "Beschafft spezielles Pferdefutter, mit dem man ein Geisterpferd füttern kann. Nathanos Blightcaller in den Östlichen Pestländern könnte Euch ein solches Futter geben. Reist anschließend nach Düsterbruch in Feralas und tötet Tendris Wucherborke. Dies wird den uralten Pferdegeist befreien. Füttert den Geist zur Beruhigung mit dem speziellen Pferdefutter. Gebt dem Pferdegeist schließlich das Arkanitpferdegeschirr und hofft, dass er bereit ist, es zu segnen.",
    [97183] = "Kehrt mit dem gesegneten Arkanitpferdegeschirr zu Danitha Morr in der Bandarionfestung in Tirisfal zurück.",
    [97184] = "Bringt Danitha Morr in der Bandarionfestung in Tirisfal einen azerothischen Diamant und einen makellosen schwarzen Diamant.",
    [97185] = "Benutzt das Orakel der Anrufung im Herzen des Kellergewölbes des großen Ossuariums in Scholomance. Damit ruft Ihr die verfluchten Geister, über deren Schicksal Ihr richten müsst. Durch das Besiegen der Geister wird der Todesritter Schattensichel beschworen. Besiegt ihn und holt Euch die verlorene Seele des gefallenen Streitrosses. Gebt den Geist der Vergeltung und das gesegnete und verzauberte Pferdegeschirr Schattensichels gefallenem Streitross.",
    [97186] = "Treibt 20 angereicherte Manakekse für Nathanos Blightcaller in den Östlichen Pestländern auf. Die Argentumdämmerung ist als alleiniger Händler dieser Kekse bekannt. Zusätzlich müsst Ihr Blightcaller noch 50 Goldstücke für seine Zeit zahlen.",
    [97188] = "Erlernt die Fähigkeit \"Unerfahrener Reiter\" von Binjy Featherwhistle.",
    [97194] = "Erlernt die Fähigkeit \"Unerfahrener Reiter\" von Kildar.",
    [97196] = "Bergt das Auge des Kältebringers in den Hügeln von Razorfen.",
    [97197] = "Beschafft ein Fragment der Feuerlande aus den Blackrocktiefen für Alaana Stormwalker in Mulgore.",
    [97198] = "Bergt ein Ritualtotem des Schwarzschlunds in der Schwarzschlundfeste.",
    [97200] = "Erlernt die Fähigkeit \"Unerfahrener Reiter\" von Xar'Ti.",
    [97203] = "Erlernt die Fähigkeit \"Unerfahrener Reiter\" von Velma Warnam.",
    [97204] = "Erlernt die Fähigkeit \"Unerfahrener Reiter\" von Kar Stormsinger.",
    [97205] = "Erlernt die Fähigkeit \"Unerfahrener Reiter\" von Genn Fairweather.",
    [97220] = "Bringt die Torhauslieferung zum Lagerraumeingang in Trias' Käseladen im Handelsdistrikt.",
    [97222] = "Tragt die Torhauslieferung die Treppe in Trias' Laden hoch und stellt sie vor der Tür ab.",
    [97223] = "Bringt die Eier der Blutkrallenmatriarchin zu Xar'Ti in Sen'jin.",
    [97225] = "Sammelt 8 vergessene Loagötzen auf den Echoinseln. Bringt sie Meister Gadrin in Sen'jin.",
    [97234] = "Bringt das verpackte Lesematerial zur Bibliothek von Stormwind.",
    [97236] = "Bringt den Fangzahn von Githyiss zu jemandem in Aldrassil, der sich für das Studium von Spinnen interessiert.",
    [97237] = "Findet die Lesematerialien, die sich irgendwo in der Bibliothek befinden, und kehrt dann zu Roy Lewells im Park von Stormwind zurück.",
    [97242] = "Sammelt Stecklinge vom Rohrkolben und Speergras, das in der Nähe der fließenden Gewässer im Tal der Ehre wächst, und bringt sie zu Kor'geld in Yelmaks Alchimie und Tränke.",
    [97243] = "Bringt die Fackel der schlafenden Flamme zu Olariaan Swiftburn im Schrein der Flammen in im Böenbeerentiefland.",
    [97244] = "Tötet Himmelspriester Faladiel im Böenbeerentiefland und nehmt Faladiels Herz mit.",
    [97245] = "Findet Kuramaas Zuhause im Shen'darhochland und besiegt den Geist im Kampf. Bringt nach dem Sieg Kuramaas Maske zu Olariaan Swiftburn im Böenbeerentiefland.",
    [97246] = "Besucht Borstans Feuergrube und sagt ihm, dass Ihr Migis Mittagessen im Auftrag von Thatog persönlich überbringt.",
    [97249] = "Bringt Migi hinter der Feste Grommash sein Mittagessen.",
    [97250] = "Tötet Soldaten der Allianz, die an der Grenze zu den Marschen von Dustwallow ins Brachland vordringen, und kehrt anschließend zu Grunzer Logmar ins Camp Taurajo zurück.",
    [97253] = "Sammelt 5 Handvoll komplexer Teile vom oberen Piratenlager südlich von Ratchet und kehrt anschließend zurück zu Wrenix dem Jämmerlichen in Ratchet.",
    [97257] = "Wartet, bis Olariaan mit dem Ritual bei der Kohlenpfanne der Opfergabe beginnt, und folgt seinen Anweisungen. Ihr müsst die Ewige Flamme nach Valanaar bringen, bevor die Zeit abläuft.",
    [97263] = "Bringt Eldrun sein verlorengegangenes Paket.",
    [97264] = "Entfernt 12 alten Splitterzahn aus dem Umland und kehrt zu Sarna Braunhorn zurück.",
    [97265] = "Besiegt eine Auswahl an Satyrn der Zornsäer bei Sargeron in Desolace und kehrt dann zu Aka'rai im Dorf Shadowprey zurück.",
    [97275] = "Gebt Whuut Yelmaks Trank.",
    [97277] = "Findet das Lager von Grund und Gozwin in den Hügeln im Nordwesten. Bergt Gozwins Mechanikerlogbuch und tötet den Schneeleopardenpirscher.",
    [97279] = "Sammelt 6 zurückgelassene Übungswaffen und kehrt dann zu Kzan Thornslash im Höhlenbau zurück.",
    [97281] = "Bringt die matte Sturmkugel zu Rezlak in der Nähe der Staubwindklamm.",
    [97282] = "Bringt 5 geladene Donnerechsenorgane zu Rezlak in der Nähe der Staubwindklamm.",
    [97284] = "Tötet Orcs der Burning Blade in der Festung Thunder Axe in Desolace und kehrt dann zu Vahlarriel Dämonenjäger auf der Nijelspitze zurück.",
    [97287] = "Sprecht mit dem Abbild der Erzmagierin Modera in der Nähe von Dalaran.",
    [97288] = "Bringt den monströsen Kopf zu Apothekermeister Faranell in Undercity.",
    [97289] = "Bringt den Kopf des Barons zu Othmars Leiche in Undercity.",
    [97290] = "Berichtet Apothekermeister Faranell in Undercity von Euren Erkenntnissen.",
    [97291] = "Holt eine giftige Schädelkappe von Tawny Grisette im Handwerksviertel, Blasenkraut in der Nähe des Kräuterkundelehrers und eine Essenz der Pein vom Giftverkäufer im Schurkenviertel für Meisterapotheker Faranell in Undercity.",
    [97292] = "Spritzt das zischende Serum für Meisterapotheker Faranell in das System über Othmars Leiche.",
    [97319] = "Findet den verschollenen Cousin auf dem Hyjal.",
    [97326] = "Bringt 8 glatte Felsen zu Thra hinter der Feste Grommash.",
    [97327] = "Begebt Euch in die Schwarzschlundfeste und bergt 5 Schwarzschlundbeutel für Ekkal an den Ruinen von Eldarath in Azshara.",
    [97328] = "Bergt 8 gestohlene Lieferungen aus den Ruinen von Zul'Kunda im Schlingendorntal und kehrt damit nach Booty Bay zurück.",
    [97329] = "Bringt Zimmix Sputterspark den primitiven Schlüssel, den Ihr von den Trollen in den Runen von Zul'kunda im Schlingendorntal erhalten habt.",
    [97331] = "Eskortiert Zimmix Sputterspark fort von den Ruinen von Zul'Kunda und erzählt Werftmeister Lozgil in Booty Bay von Eurer erfolgreichen Rettung.",
    [97332] = "Liefert das zweifach wiederbestellte Paket an Werftmeister Whizzbuzz im Hafen von Powderfuse in den Flusslanden.",
    [97378] = "Bringt Spiegelschuppes Flügel zu Melor Stonehoof in Thunder Bluff.",
    [97386] = "Kommandant Aggro'gosh vom Basislager von Grom'gol will, dass Ihr Oger beim Ogerhügel der Mosh'Ogg tötet.",
    [97403] = "Tötet 15 Eiswindverheerer und kehrt zu Rilan Howard im Norden von Winterspring zurück.",
    [97404] = "Tötet die alten Splitterzahnmatriarchen Kuroma und Kamuro und kehrt mit ihren Köpfen zu Sarna Braunhorn zurück.",
    [97405] = "Knaz Blunderflame möchte, dass Ihr 3 Zauberkundige der Mosh'Ogg, 3 Kriegstreiber der Mosh'Ogg, 3 Zermalmer der Mosh'Ogg Maulers und 3 Schamanen der Mosh'Ogg auf dem Ogerberg der Mosh'Ogg tötet.",
    [97411] = "Sammelt 15 Giftproben aus Silithus und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Lichts zu Mokvar in Orgrimmar.",
    [97420] = "Besorgt 4 Fässer mit Rohöl aus den Operationen der Venture Co. am Nazferitisee und kehrt dann zu Knaz Blunderflame im Schlingendorntal zurück.",
    [97447] = "Sammelt 15 Blutproben aus Winterquell und bringt sie zusammen mit 20 Gold und einem Paar Bindungen der Elemente zu Deliana in Ironforge.",
    [97453] = "Tötet 6 fleischfressendes Unkraut südlich von Grom'gol und informiert dann Gemmils Mutter.",
    [97485] = "Kauft ein Kräuterbündel von Nida der Kräuterkundigen, ein Bündel Zedernzweige von Nata, der Verkäuferin für Verzauberkunstbedarf, und Sehnenfaden von Mahu, dem Verkäufer für Lederverarbeitungsbedarf, sowie Feuerstein und Zunder von Naal, dem Verkäufer für Kochbedarf. Fügt die Gegenstände zusammen und streut das Räucherwerk von der Anhöhe der Jäger.",
    [97490] = "Sucht in den südlichen Hügeln von Winterspring nach dem Riesen namens Hagelschuft und besorgt das Frostmoos, das auf ihm wächst.",
    [97530] = "Sicherheitschef Bilgewhizzle aus Steamwheedle in Tanaris möchte, dass Ihr einen besonders glänzenden Armreif zurückbringt, der irgendwo beim Lager der Oger der Dünenbrecher verloren ging.",
    [97534] = "Quinn möchte, dass Ihr 7 Haufen Wüstenschutt sammelt und zu ihr nach Gadgetzan bringt.",
    [97536] = "Jhordy Lapforge möchte, dass Ihr zu ihm zurückkehrt, nachdem Ihr die Kiste mit radioaktiven Abfällen in der Wüste von Tanaris entsorgt habt, in sicherer Entfernung von Gadgetzan und anderem Müll.",
    [97538] = "Tah Winterhoof in Thunder Bluff möchte 30 Mirkkrautsamenkapseln vom Mirkfallonsee.",
