    [97558] = "Bringt Shelene Rhobart 8 Nachtsaugerflügelmembranen, 6 Schattenhundbälge und 3 Häute eines Murlocs der Finsterflossen.",
    [97583] = "Kauft nahrhafte Schleimpampe und kehrt zu Eurem freundlichen erregbaren Schleim zurück. Versucht, mit ihm zu tanzen, wenn er müde wirkt, um wieder seine Aufmerksamkeit zu erregen.",
    [97617] = "Bergt 8 nicht studierte Artefakte, einen Bergbauhelm der Forscherliga sowie eine makellose Kreuzhacke und bringt alles zu Dorgaron an der Grenze zu Loch Modan und dem Ödland.",
    [97663] = "Tötet Oger im Staubbecken für Mus'hales gestohlene Vorräte und fertigt damit Abdrücke der hiesigen Steinschnitzereien an. Kehrt dann zu Mus'hale in Kargath zurück.",
    [97821] = "Findet jemanden im Ödland, der an dieser Entdeckung interessiert wäre.",
